package io.huze.glamourer.plate;

import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.glam.Glamourer;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class PlateManager
{
	private final PlateStore plateStore;
	@Getter
	private final Glamourer glamourer;
	@Getter
	private final IconService iconService;
	@Getter
	private final ChangeLog changeLog;

	@Getter
	private final List<Plate> plates = new ArrayList<>();
	@Setter
	@Nonnull
	private Consumer<Void> onPlatesChanged = ignored -> {};

	@Getter
	private volatile boolean starterPlateNeeded;
	private final AtomicInteger loadGeneration = new AtomicInteger();

	private final List<PlateData> orphanedPlates = new ArrayList<>();

	public CompletableFuture<Void> loadPlates()
	{
		final int generation = loadGeneration.incrementAndGet();
		orphanedPlates.clear();

		if (plateStore.isLegacyFormat())
		{
			plateStore.migrateFromLegacy();
		}
		plateStore.cleanupTombstones();
		orphanedPlates.addAll(plateStore.loadOrphanedPlates());

		List<CompletableFuture<Plate>> futures = new ArrayList<>();
		for (PlateData data : plateStore.loadAllPlates())
		{
			futures.add(Plate.loadFromData(data, glamourer, changeLog, this));
		}

		return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
			.thenRunAsync(() -> {
				if (generation != loadGeneration.get())
				{
					log.debug("Discarding stale plate load (gen {} != {})", generation, loadGeneration.get());
					return;
				}
				plates.clear();
				for (CompletableFuture<Plate> f : futures)
				{
					plates.add(f.join());
				}
				starterPlateNeeded = plates.isEmpty();
				log.info("Loaded {} plates", plates.size());
				notifyPlatesChanged();
			}, SwingUtilities::invokeLater);
	}

	void saveSinglePlate(Plate plate)
	{
		try
		{
			plateStore.savePlate(plate);
		}
		catch (Exception e)
		{
			log.error("Failed to save plate '{}'", plate.getName(), e);
		}
	}

	void savePlateOrder()
	{
		plateStore.savePlateOrder(plates.stream().map(Plate::getId).collect(Collectors.toList()));
	}

	void tombstonePlate(String id)
	{
		plateStore.tombstonePlate(id);
	}

	public void createPlate()
	{
		Plate plate = Plate.newEmptyPlate(glamourer, changeLog, this);
		apply(new PlateCreateChange(this, plate));
	}

	public CompletableFuture<Void> createStarterPlate(Collection<Integer> itemIds)
	{
		final int generation = loadGeneration.get();
		starterPlateNeeded = false;
		List<CompletableFuture<Glamour>> futures = new ArrayList<>();
		for (int itemId : itemIds)
		{
			futures.add(glamourer.startGlamourAsync(itemId));
		}
		return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
			.thenRunAsync(() -> {
				if (generation != loadGeneration.get())
				{
					log.debug("Discarding stale starter plate creation (gen {} != {})", generation, loadGeneration.get());
					return;
				}
				ArrayList<Glamour> glamours = new ArrayList<>();
				for (CompletableFuture<Glamour> f : futures)
				{
					glamours.add(f.join());
				}
				glamours.sort(Comparator.comparing(Glamour::getItemName));
				Plate plate = Plate.newPlate("My Equipment (Example)", glamourer, changeLog, this, glamours);
				plates.add(plate);
				reapplyAllPlates();
				saveSinglePlate(plate);
				savePlateOrder();
				notifyPlatesChanged();
			}, SwingUtilities::invokeLater);
	}

	public int getOrphanedPlateCount()
	{
		return orphanedPlates.size();
	}

	public CompletableFuture<Void> recoverOrphanedPlates()
	{
		if (orphanedPlates.isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}
		final int generation = loadGeneration.get();
		List<PlateData> toRecover = new ArrayList<>(orphanedPlates);
		orphanedPlates.clear();

		List<CompletableFuture<Plate>> futures = new ArrayList<>();
		for (PlateData data : toRecover)
		{
			futures.add(Plate.loadFromData(data, glamourer, changeLog, this));
		}
		return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
			.thenRunAsync(() -> {
				if (generation != loadGeneration.get())
				{
					log.debug("Discarding stale orphan recovery (gen {} != {})", generation, loadGeneration.get());
					return;
				}
				int recovered = 0;
				for (CompletableFuture<Plate> f : futures)
				{
					Plate plate = f.join();
					if (hasPlateWithId(plate.getId()))
					{
						continue;
					}
					plates.add(plate);
					recovered++;
				}
				reapplyAllPlates();
				savePlateOrder();
				log.info("Recovered {} orphaned plates", recovered);
				notifyPlatesChanged();
			}, SwingUtilities::invokeLater);
	}

	public void discardOrphanedPlates()
	{
		for (PlateData data : orphanedPlates)
		{
			tombstonePlate(data.getId());
		}
		log.info("Discarded {} orphaned plates", orphanedPlates.size());
		orphanedPlates.clear();
	}

	public void deletePlate(String id)
	{
		for (int i = 0; i < plates.size(); i++)
		{
			if (plates.get(i).getId().equals(id))
			{
				apply(new PlateDeleteChange(this, plates.get(i), i));
				return;
			}
		}
	}

	public void movePlate(int fromIndex, int toIndex)
	{
		int size = plates.size();
		if (fromIndex < 0 || fromIndex >= size || toIndex < 0 || toIndex >= size || fromIndex == toIndex)
		{
			return;
		}
		apply(new PlateReorderChange(this, fromIndex, toIndex));
	}

	public void setPlateEnabled(Plate plate, boolean enabled)
	{
		if (plate.isEnabled() == enabled)
		{
			return;
		}
		apply(new PlateEnableChange(this, plate, plate.isEnabled()));
	}

	public void setPlateDisplayStyle(Plate plate, DisplayStyle displayStyle)
	{
		apply(new PlateDisplayStyleChange(this, plate, plate.getDisplayStyle(), displayStyle));
	}

	public void setPlateIconStyle(Plate plate, IconStyle iconStyle)
	{
		apply(new PlateIconStyleChange(this, plate, plate.getIconStyle(), iconStyle));
	}

	public void removeGlamour(Plate plate, int glamourIndex)
	{
		if (glamourIndex < 0 || glamourIndex >= plate.getGlamours().size())
		{
			return;
		}
		Glamour removed = plate.getGlamours().get(glamourIndex);
		apply(new GlamourRemoveChange(this, plate, removed, glamourIndex));
	}

	public CompletableFuture<Void> addGlamour(Plate plate, int itemId)
	{
		return glamourer.startGlamourAsync(itemId).thenAcceptAsync(glamour -> {
			if (plate.containsItem(glamour.getPrimaryItemId()))
			{
				return;
			}
			apply(new GlamourAddChange(this, plate, glamour, plate.getGlamours().size()));
		}, SwingUtilities::invokeLater);
	}

	public void moveGlamour(Plate plate, int fromIndex, int toIndex)
	{
		final int size = plate.getGlamours().size();
		if (fromIndex == toIndex || fromIndex < 0 || fromIndex >= size || toIndex < 0 || toIndex >= size)
		{
			return;
		}
		String itemName = plate.getGlamours().get(fromIndex).getItemName();
		apply(new GlamourReorderChange(this, plate, fromIndex, toIndex, itemName));
	}

	public void transferGlamour(Plate sourcePlate, int sourceIndex, Plate targetPlate, int targetIndex)
	{
		Glamour glam = sourcePlate.getGlamours().get(sourceIndex);
		if (targetPlate.containsItem(glam.getPrimaryItemId()))
		{
			return;
		}
		apply(new GlamourMoveChange(this, sourcePlate, sourceIndex, targetPlate, targetIndex, glam));
	}

	public CompletableFuture<Void> importPlateAsNew(String json)
	{
		PlateData data = plateStore.parseImportJson(json);
		data.setId(UUID.randomUUID().toString());
		return importPlateData(data);
	}

	public CompletableFuture<Void> importPlate(String json)
	{
		return importPlateData(plateStore.parseImportJson(json));
	}

	private CompletableFuture<Void> importPlateData(PlateData data)
	{
		data.setEnabled(true);

		final int generation = loadGeneration.get();
		final String importId = data.getId();
		return Plate.loadFromData(data, glamourer, changeLog, this).thenAcceptAsync(plate -> {
			if (generation != loadGeneration.get())
			{
				log.debug("Discarding stale plate import (gen {} != {})", generation, loadGeneration.get());
				return;
			}
			int existingIndex = -1;
			for (int i = 0; i < plates.size(); i++)
			{
				if (plates.get(i).getId().equals(importId))
				{
					existingIndex = i;
					break;
				}
			}
			if (existingIndex >= 0)
			{
				plates.set(existingIndex, plate);
			}
			else
			{
				plates.add(plate);
			}

			reapplyAllPlates();
			saveSinglePlate(plate);
			savePlateOrder();
			changeLog.clear();
			notifyPlatesChanged();
		}, SwingUtilities::invokeLater).exceptionally(e -> {
			log.error("Failed to import plate", e);
			return null;
		});
	}

	public String exportPlateJson(Plate plate, boolean verbose)
	{
		return plateStore.exportJson(plate, verbose);
	}

	public CompletableFuture<Plate> loadImportPreview(String json)
	{
		PlateData data = plateStore.parseImportJson(json);
		if (data == null || data.getName() == null || data.getGlamours() == null)
		{
			throw new IllegalArgumentException("Invalid plate data: missing required fields.");
		}
		return Plate.loadFromData(data, glamourer, changeLog, null);
	}

	public boolean hasPlateWithId(String id)
	{
		return plates.stream().anyMatch(plate -> plate.getId().equals(id));
	}

	public void reapplyAllPlates()
	{
		glamourer.batch(() -> plates.forEach(Plate::applyAll));
	}

	private void apply(Change change)
	{
		change.redo();
		change.save();
		changeLog.record(change);
		notifyPlatesChanged();
	}

	private void notifyPlatesChanged()
	{
		onPlatesChanged.accept(null);
	}
}

package io.huze.glamourer.plate;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import io.huze.glamourer.Config;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class PlateStore
{
	static final String PLATE_LIST_KEY = "plateList";
	static final String PLATE_KEY_PREFIX = "plate.";
	static final String LEGACY_KEY = "userPlates";
	static final long TOMBSTONE_TTL_MS = 7L * 24 * 60 * 60 * 1000;

	private static final Type STRING_LIST_TYPE = new TypeToken<List<String>>()
	{
	}.getType();
	private static final Type LEGACY_PLATES_TYPE = new TypeToken<List<PlateData>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	@Nonnull
	public List<String> getPlateOrder()
	{
		String json = configManager.getConfiguration(Config.GROUP, PLATE_LIST_KEY);
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		try
		{
			List<String> ids = gson.fromJson(json, STRING_LIST_TYPE);
			return ids != null ? ids : Collections.emptyList();
		}
		catch (JsonSyntaxException e)
		{
			log.error("Failed to parse plate order", e);
			return Collections.emptyList();
		}
	}

	@Nullable
	PlateData loadPlate(String uuid) throws IOException
	{
		PlateConfig stored = readConfig(uuid);
		if (stored == null || stored.isTombstone())
		{
			return null;
		}
		return stored.toPlateData(uuid);
	}

	List<PlateData> loadAllPlates()
	{
		List<String> order = getPlateOrder();
		List<PlateData> plates = new ArrayList<>();
		for (String uuid : order)
		{
			try
			{
				PlateData plate = loadPlate(uuid);
				if (plate != null)
				{
					plates.add(plate);
				}
			}
			catch (Exception e)
			{
				log.error("Failed to load plate {}", uuid, e);
			}
		}
		return plates;
	}

	List<PlateData> loadOrphanedPlates()
	{
		Set<String> ordered = new HashSet<>(getPlateOrder());
		List<PlateData> orphans = new ArrayList<>();
		String prefix = Config.GROUP + "." + PLATE_KEY_PREFIX;

		for (String fullKey : configManager.getConfigurationKeys(prefix))
		{
			String uuid = fullKey.substring(prefix.length());
			if (ordered.contains(uuid))
			{
				continue;
			}
			try
			{
				PlateData plate = loadPlate(uuid);
				if (plate != null)
				{
					orphans.add(plate);
				}
			}
			catch (Exception e)
			{
				log.error("Failed to load orphaned plate {}", uuid, e);
			}
		}
		return orphans;
	}

	boolean isLegacyFormat()
	{
		String plateList = configManager.getConfiguration(Config.GROUP, PLATE_LIST_KEY);
		if (plateList != null && !plateList.isEmpty())
		{
			return false;
		}
		String legacy = configManager.getConfiguration(Config.GROUP, LEGACY_KEY);
		return legacy != null && !legacy.isEmpty();
	}

	public void savePlate(Plate plate) throws IOException
	{
		writeConfig(plate.getId(), PlateConfig.fromPlate(plate));
		log.debug("savePlate '{}' ({})", plate.getName(), plate.getId());
	}

	public void savePlateOrder(List<String> uuids)
	{
		String json = gson.toJson(uuids, STRING_LIST_TYPE);
		configManager.setConfiguration(Config.GROUP, PLATE_LIST_KEY, json);
		log.debug("savePlateOrder {}", uuids);
	}

	public void tombstonePlate(String uuid)
	{
		PlateConfig stored = readConfig(uuid);
		if (stored != null)
		{
			stored.setDeletedAt(System.currentTimeMillis());
			writeConfig(uuid, stored);
			log.debug("tombstonePlate {}", uuid);
		}
	}

	public String exportJson(Plate plate, boolean verbose)
	{
		PlateData data = plate.getData(verbose);
		data.setEnabled(null);
		data.setDisplayStyle(null);
		data.setIconStyle(null);
		return gson.toJson(data);
	}

	PlateData parseImportJson(String json) throws JsonSyntaxException
	{
		PlateData data = gson.fromJson(json, PlateData.class);
		requireSupportedVersion(data);
		return data;
	}

	static void requireSupportedVersion(@Nullable PlateData data)
	{
		if (data != null && data.getVersion() != null && data.getVersion() > PlateData.SUPPORTED_VERSION)
		{
			throw new IllegalArgumentException("This plate was exported by a newer version of Glamourer. Update the plugin to import it.");
		}
	}

	public void migrateFromLegacy()
	{
		String json = configManager.getConfiguration(Config.GROUP, LEGACY_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		List<PlateData> legacyPlates;
		try
		{
			legacyPlates = gson.fromJson(json, LEGACY_PLATES_TYPE);
		}
		catch (Exception e)
		{
			log.error("Failed to parse legacy plates for migration", e);
			return;
		}

		if (legacyPlates == null || legacyPlates.isEmpty())
		{
			savePlateOrder(Collections.emptyList());
			return;
		}

		List<String> uuids = new ArrayList<>();
		for (PlateData plate : legacyPlates)
		{
			if (plate.getId() == null)
			{
				log.warn("Skipping legacy plate with null ID");
				continue;
			}
			try
			{
				writeConfig(plate.getId(), PlateConfig.fromPlateData(plate));
				uuids.add(plate.getId());
			}
			catch (Exception e)
			{
				log.error("Failed to migrate plate '{}'", plate.getName(), e);
			}
		}
		savePlateOrder(uuids);
		configManager.unsetConfiguration(Config.GROUP, LEGACY_KEY);
		log.info("Migrated {} plates to per-plate config keys", uuids.size());
	}

	public void cleanupTombstones()
	{
		long now = System.currentTimeMillis();
		String prefix = Config.GROUP + "." + PLATE_KEY_PREFIX;

		for (String fullKey : configManager.getConfigurationKeys(prefix))
		{
			String uuid = fullKey.substring(prefix.length());
			PlateConfig stored = readConfig(uuid);
			if (stored != null && stored.isExpiredTombstone(now))
			{
				log.debug("Cleaning up tombstoned plate {}", uuid);
				configManager.unsetConfiguration(Config.GROUP, PLATE_KEY_PREFIX + uuid);
			}
		}
	}

	@Nullable
	private PlateConfig readConfig(String uuid)
	{
		String json = configManager.getConfiguration(Config.GROUP, PLATE_KEY_PREFIX + uuid);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, PlateConfig.class);
		}
		catch (JsonSyntaxException e)
		{
			log.error("Failed to read plate config {}", uuid, e);
			return null;
		}
	}

	private void writeConfig(String uuid, PlateConfig config)
	{
		configManager.setConfiguration(Config.GROUP, PLATE_KEY_PREFIX + uuid, gson.toJson(config));
	}
}

package io.huze.glamourer.plate;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.texture.TextureReplacement;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class GlamourBinaryCodec
{
	private static final int VERSION = 1;
	private static final int FLAG_HAS_ITEM_KEY = 1;
	private static final int FLAG_HAS_TEXTURES = 1 << 1;

	private GlamourBinaryCodec()
	{
	}

	public static byte[] encodeList(List<GlamourData> glamours) throws IOException
	{
		ByteArrayOutputStream baos = new ByteArrayOutputStream();
		DataOutputStream dos = new DataOutputStream(baos);
		dos.writeByte(VERSION);
		dos.writeShort(glamours.size());
		for (GlamourData glamour : glamours)
		{
			encode(dos, glamour);
		}
		dos.flush();
		return baos.toByteArray();
	}

	public static List<GlamourData> decodeList(byte[] bytes) throws IOException
	{
		DataInputStream dis = new DataInputStream(new ByteArrayInputStream(bytes));
		int version = dis.readUnsignedByte();
		if (version != VERSION)
		{
			throw new IOException("Unsupported glamour binary version: " + version);
		}
		int count = dis.readUnsignedShort();
		List<GlamourData> glamours = new ArrayList<>(count);
		for (int i = 0; i < count; i++)
		{
			glamours.add(decode(dis));
		}
		return glamours;
	}

	private static void encode(DataOutputStream dos, GlamourData glamour) throws IOException
	{
		int flags = 0;
		if (glamour.getItemKey() != null)
		{
			flags |= FLAG_HAS_ITEM_KEY;
		}
		boolean hasTextures = glamour.getTextureReplacements() != null && !glamour.getTextureReplacements().isEmpty();
		if (hasTextures)
		{
			flags |= FLAG_HAS_TEXTURES;
		}
		dos.writeByte(flags);

		if ((flags & FLAG_HAS_ITEM_KEY) != 0)
		{
			dos.writeUTF(glamour.getItemKey());
		}
		else
		{
			dos.writeInt(glamour.getItemId() != null ? glamour.getItemId() : -1);
		}

		List<ColorReplacement> colors = glamour.getColorReplacements();
		dos.writeShort(colors.size());
		for (ColorReplacement cr : colors)
		{
			dos.writeShort(cr.getOriginal());
			dos.writeShort(cr.getReplacement());
			boolean hasModel = cr.getModel() != null;
			dos.writeBoolean(hasModel);
			if (hasModel)
			{
				dos.writeShort(cr.getModel());
			}
		}

		if (hasTextures)
		{
			List<TextureReplacement> textures = glamour.getTextureReplacements();
			dos.writeShort(textures.size());
			for (TextureReplacement tr : textures)
			{
				dos.writeShort(tr.getOriginal());
				dos.writeShort(tr.getReplacement());
			}
		}
	}

	private static GlamourData decode(DataInputStream dis) throws IOException
	{
		int flags = dis.readUnsignedByte();

		String itemKey = null;
		int itemId = -1;
		if ((flags & FLAG_HAS_ITEM_KEY) != 0)
		{
			itemKey = dis.readUTF();
		}
		else
		{
			itemId = dis.readInt();
		}

		int colorCount = dis.readUnsignedShort();
		List<ColorReplacement> colors = new ArrayList<>(colorCount);
		for (int i = 0; i < colorCount; i++)
		{
			ColorReplacement cr = new ColorReplacement(dis.readShort(), dis.readShort());
			if (dis.readBoolean())
			{
				cr.setModel(dis.readShort());
			}
			colors.add(cr);
		}

		List<TextureReplacement> textures = null;
		if ((flags & FLAG_HAS_TEXTURES) != 0)
		{
			int textureCount = dis.readUnsignedShort();
			textures = new ArrayList<>(textureCount);
			for (int i = 0; i < textureCount; i++)
			{
				textures.add(new TextureReplacement(dis.readShort(), dis.readShort()));
			}
		}

		return new GlamourData(itemKey, itemId, colors, textures);
	}
}

package io.huze.glamourer.plate;

import io.huze.glamourer.glam.Glamour;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.Set;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class ChangeLog
{
	private static final int MAX_HISTORY = 100;

	private final Deque<Change> undoStack = new ArrayDeque<>();
	private final Deque<Change> redoStack = new ArrayDeque<>();

	@Setter
	@Nonnull
	private Consumer<Set<Integer>> onGlamourChanged = itemIds -> {};

	@Setter
	@Nonnull
	private Runnable onUndoRedoAvailabilityChanged = () -> {};

	void record(Change change)
	{
		undoStack.push(change);
		if (undoStack.size() > MAX_HISTORY)
		{
			undoStack.removeLast();
		}
		redoStack.clear();
		notifyChanged(change);
		onUndoRedoAvailabilityChanged.run();
	}

	public boolean canUndo()
	{
		return !undoStack.isEmpty();
	}

	public boolean canRedo()
	{
		return !redoStack.isEmpty();
	}

	@Nullable
	public String undoDescription()
	{
		return "Undo" + (canUndo() ? " " + undoStack.peek().description() : "");
	}

	@Nullable
	public String redoDescription()
	{
		return "Redo" + (canRedo() ? " " + redoStack.peek().description() : "");
	}

	public void undo()
	{
		if (!canUndo())
		{
			return;
		}
		Change change = undoStack.pop();
		change.undo();
		change.save();
		redoStack.push(change);
		notifyChanged(change);
		onUndoRedoAvailabilityChanged.run();
	}

	public void redo()
	{
		if (!canRedo())
		{
			return;
		}
		Change change = redoStack.pop();
		change.redo();
		change.save();
		undoStack.push(change);
		notifyChanged(change);
		onUndoRedoAvailabilityChanged.run();
	}

	private void notifyChanged(Change change)
	{
		onGlamourChanged.accept(change.affectedItemIds());
	}

	public void clear()
	{
		undoStack.clear();
		redoStack.clear();
		onUndoRedoAvailabilityChanged.run();
	}
}

// --- Change interface and base ---

interface Change
{
	void undo();

	void redo();

	void save();

	@Nonnull
	String description();

	@Nonnull
	default Set<Integer> affectedItemIds()
	{
		return Collections.emptySet();
	}
}

abstract class ReapplyChange implements Change
{
	protected abstract PlateManager getPlateManager();

	protected abstract void applyRedo();

	protected abstract void applyUndo();

	@Override
	public final void redo()
	{
		applyRedo();
		getPlateManager().reapplyAllPlates();
	}

	@Override
	public final void undo()
	{
		applyUndo();
		getPlateManager().reapplyAllPlates();
	}
}

