import lombok.Setter;

public abstract class ColorLabel extends JPanel implements Hoverable
{
	public static final int ROW_HEIGHT = 24;

	@Setter
	@Nonnull private Consumer<Short> onColorChange = x -> {};
	@Setter
	@Nonnull private Consumer<Short> onColorPreview = x -> {};
	@Setter
	@Nonnull private Runnable onHoverStart = () -> {};
	@Setter
	@Nonnull private Runnable onHoverEnd = () -> {};
	private final String pickerName;
	private final short originalHsl;
	protected final JLabel colorDisplay;
	protected final JButton revertButton;
	private final JPanel revertWrapper;
	private JDialog activeDialog;

	protected ColorLabel(String name, short originalHsl)
	{
		this.pickerName = name;
		this.originalHsl = originalHsl;

		setLayout(new BorderLayout(3, 0));
		setOpaque(false);

		// Main color display label (clickable to open picker)
		colorDisplay = new JLabel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				var replacementShadedColors = getColorReplacements().stream()
					.map(r -> Colors.hslToShadedColor(r.getReplacement()))
					.toArray(Color[]::new);
				ColorUtil.paintColorSpread(g, 0, 0, getWidth(), getHeight(), replacementShadedColors);
				super.paintComponent(g);
			}
		};
		colorDisplay.setOpaque(false);
		colorDisplay.setBorder(new EmptyBorder(5, 5, 5, 5));
		colorDisplay.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		colorDisplay.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent mouseEvent)
			{
				showPicker();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				onHoverStart.run();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				onHoverEnd.run();
			}
		});
		add(colorDisplay, BorderLayout.CENTER);

		// Revert button (double-click to revert)
		revertButton = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				var originalShadedColors = getColorReplacements().stream()
					.map(r -> Colors.hslToShadedColor(r.getOriginal()))
					.toArray(Color[]::new);
				ColorUtil.paintColorSpread(g, 0, 0, getWidth(), getHeight(), originalShadedColors);
				super.paintComponent(g);
			}
		};
		revertButton.setPreferredSize(new Dimension(ROW_HEIGHT, ROW_HEIGHT));
		revertButton.setToolTipText("Double-click to revert to original color");
		revertButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		revertButton.setBorderPainted(false);
		revertButton.setFocusPainted(false);
		revertButton.setContentAreaFilled(false);
		Color originalColor = Colors.hslToColor(originalHsl);
		revertButton.setBackground(originalColor);
		ImageIcons.setResetIcon(revertButton, originalColor);
		revertButton.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					revertToOriginal();
				}
			}
		});
		revertWrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		revertWrapper.setOpaque(false);
		revertWrapper.add(revertButton);
		add(revertWrapper, BorderLayout.EAST);
	}

	protected void updateColorDisplay()
	{
		List<ColorReplacement> colors = getColorReplacements();
		short medianHsl = colors.get(colors.size() / 2).getReplacement();
		Color displayColor = Colors.hslToShadedColor(medianHsl);
		colorDisplay.setBackground(displayColor);
		colorDisplay.setForeground(getContrastColor(displayColor));
		colorDisplay.setText(getDisplayText());

		boolean hasChanges = colors.stream().anyMatch(ColorReplacement::hasChanged);
		revertWrapper.setVisible(hasChanges);
		short medianOriginalHsl = colors.get(colors.size() / 2).getOriginal();
		ImageIcons.setResetIcon(revertButton, Colors.hslToShadedColor(medianOriginalHsl));
		revertButton.repaint();
	}

	private static Color getContrastColor(Color color)
	{
		return ImageIcons.shouldUseDarkForeground(color) ? Color.BLACK : Color.WHITE;
	}

	protected void notifyColorChange(short newColor)
	{
		onColorChange.accept(newColor);
	}

	@Override
	public void removeNotify()
	{
		onHoverEnd.run();
		if (activeDialog != null)
		{
			activeDialog.dispose();
			activeDialog = null;
		}
		super.removeNotify();
	}

	public void setViewOnly()
	{
		colorDisplay.setCursor(Cursor.getDefaultCursor());
		revertButton.setCursor(Cursor.getDefaultCursor());
		revertButton.setToolTipText(null);
		revertButton.setIcon(null);
		revertButton.setRolloverIcon(null);
		for (var listener : colorDisplay.getMouseListeners()) {
			colorDisplay.removeMouseListener(listener);
		}
	}

	public void showPicker()
	{
		if (activeDialog != null && activeDialog.isVisible())
		{
			activeDialog.toFront();
			return;
		}

		final var initialColor = getPickerInitialColor();
		HslColorPicker picker = new HslColorPicker(originalHsl, initialColor);
		picker.setOnChange(onColorPreview);
		final AtomicBoolean okPressed = new AtomicBoolean();
		activeDialog = DialogUtil.showModelessDialogNearCursor(
			this,
			picker,
			pickerName,
			picker.getModeControls(),
			d -> {
				okPressed.set(true);
				if (picker.getColor() != initialColor)
				{
					onColorChanged(picker.getColor());
				}
			}
		);
		activeDialog.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				if (!okPressed.get() && picker.getColor() != initialColor)
				{
					onColorPreview.accept(initialColor);
				}
				activeDialog = null;
			}
		});
	}

	protected abstract List<ColorReplacement> getColorReplacements();

	protected abstract String getDisplayText();

	protected abstract void revertToOriginal();

	protected abstract void onColorChanged(short newColor);

	protected abstract short getPickerInitialColor();
}

package io.huze.glamourer.ui.colorpicker;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Rectangle;
import javax.swing.JSlider;
import javax.swing.plaf.basic.BasicSliderUI;
import lombok.Setter;

public class ColorSliderUI extends BasicSliderUI
{
	private static final int TRACK_HEIGHT = 10;
	private static final int THUMB_WIDTH = 3;

	@Setter
	private Color[] colors;

	public ColorSliderUI(JSlider b, Color[] colors)
	{
		super(b);
		this.colors = colors;
	}

	@Override
	public int xPositionForValue(int value)
	{
		double stepWidth = (double) trackRect.width / colors.length;
		return trackRect.x + (int) ((value + 0.5) * stepWidth);
	}

	@Override
	public int valueForXPosition(int xPos)
	{
		double stepWidth = (double) trackRect.width / colors.length;
		int value = (int) ((xPos - trackRect.x) / stepWidth);

		if (value < 0)
		{
			return 0;
		}
		if (value >= colors.length)
		{
			return colors.length - 1;
		}
		return value;
	}

	@Override
	public void paintThumb(Graphics g)
	{
		g.setColor(Color.WHITE);
		int x = thumbRect.x + (thumbRect.width / 2);
		g.fillRect(x - 1, thumbRect.y, THUMB_WIDTH, thumbRect.height);
		g.setColor(Color.BLACK);
		g.drawRect(x - 1, thumbRect.y, THUMB_WIDTH, thumbRect.height);
	}

	@Override
	public void paintTrack(Graphics g)
	{
		Rectangle t = trackRect;
		int trackY = t.y + (t.height / 2) - (TRACK_HEIGHT / 2);

		ColorUtil.paintColorSpread(g, t.x, trackY, t.width, TRACK_HEIGHT, colors);

		g.setColor(Color.DARK_GRAY);
		g.drawRect(t.x, trackY, t.width, TRACK_HEIGHT);
	}
}

package io.huze.glamourer.ui.colorpicker;

import io.huze.glamourer.color.Colors;
import io.huze.glamourer.ui.ImageIcons;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import javax.annotation.Nonnull;
import javax.swing.border.Border;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.ChangeEvent;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.util.function.Consumer;
import lombok.Setter;
import lombok.Getter;
import net.runelite.api.JagexColor;

public class HslColorPicker extends JPanel
{
	private static final int SHADED_GRADIENT_STEPS = 21;
	private static int previousModeIndex = 0;

	@Setter
	@Nonnull private Consumer<Short> onChange = x -> {};
	private final JSlider hueSlider;
	private final JSlider satSlider;
	private final JSlider lumSlider;
	private final JTextField hueText;
	private final JTextField satText;
	private final JTextField lumText;
	private final JLabel colorPreview;
	@Nonnull private Color[] previewColors;
	private final Color[] satColors = new Color[Colors.MAX_SAT + 1];
	private final Color[] lumColors = new Color[Colors.MAX_LUM + 1];
	private final JTextField hslField = new JTextField("0", 6);
	private static final Border INVALID_BORDER = BorderFactory.createLineBorder(Color.RED);
	private static final Border VALID_BORDER = new JTextField().getBorder();
	private final JComboBox<String> modeCombo;
	@Getter
	private final JPanel modeControls;

	public HslColorPicker(final short original, final short previous)
	{
		setLayout(new BorderLayout(10, 10));

		modeCombo = new JComboBox<>(new String[]{"Shaded Gradient", "Shaded Median", "Unshaded"});
		modeCombo.setSelectedIndex(previousModeIndex);
		modeCombo.addActionListener(e -> {
			previousModeIndex = modeCombo.getSelectedIndex();
			previewColors = createColorArray();
			onUpdate(null);
		});
		modeControls = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		modeControls.add(new JLabel("Mode:"));
		modeControls.add(modeCombo);

		previewColors = createColorArray();
		colorPreview = new JLabel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				ColorUtil.paintPreview(g, getWidth(), getHeight(), previewColors);
				super.paintComponent(g);
			}
		};

		hueSlider = createGradientSlider(Colors.MAX_HUE, getHueSpectrum());
		satSlider = createGradientSlider(Colors.MAX_SAT, satColors);
		lumSlider = createGradientSlider(Colors.MAX_LUM, lumColors);
		updateGradients();
		hueText = createColorTextField(Colors.MAX_HUE, hueSlider);
		satText = createColorTextField(Colors.MAX_SAT, satSlider);
		lumText = createColorTextField(Colors.MAX_LUM, lumSlider);

		JPanel previewPanel = new JPanel();
		previewPanel.setLayout(new BoxLayout(previewPanel, BoxLayout.Y_AXIS));

		colorPreview.setAlignmentX(Component.CENTER_ALIGNMENT);
		colorPreview.setPreferredSize(new Dimension(100, 50));
		colorPreview.setMaximumSize(new Dimension(100, 50));
		colorPreview.setBorder(BorderFactory.createLineBorder(Color.BLACK));
		colorPreview.setOpaque(false);
		colorPreview.setToolTipText("Current color");
		previewPanel.add(colorPreview);

		previewPanel.add(Box.createVerticalStrut(2));
		previewPanel.add(createColorButton(previous, "Restore previous color"));
		previewPanel.add(Box.createVerticalStrut(2));
		previewPanel.add(createColorButton(original, "Restore original color"));
		previewPanel.add(Box.createVerticalGlue());

		JPanel controlsPanel = new JPanel();
		controlsPanel.setLayout(new BoxLayout(controlsPanel, BoxLayout.Y_AXIS));
		controlsPanel.add(createSliderRow("Hue:", "Hue (color tone)\n[0, " + Colors.MAX_HUE + "]", hueSlider, hueText));
		controlsPanel.add(Box.createVerticalStrut(2));
		controlsPanel.add(createSliderRow("Sat:", "Saturation (color intensity)\n[0, " + Colors.MAX_SAT + "]", satSlider, satText));
		controlsPanel.add(Box.createVerticalStrut(2));
		controlsPanel.add(createSliderRow("Lum:", "Luminance (lightness)\n[0, " + Colors.MAX_LUM + "]", lumSlider, lumText));
		controlsPanel.add(Box.createVerticalStrut(5));
		JPanel exportWrapper = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		exportWrapper.add(createExportRow("HSL:", "Jagex Color composed from Hue, Sat, and Lum components\n[" + Short.MIN_VALUE + ", " + Short.MAX_VALUE + "]", hslField));
		exportWrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, exportWrapper.getPreferredSize().height));
		controlsPanel.add(exportWrapper);

		add(previewPanel, BorderLayout.WEST);
		add(controlsPanel, BorderLayout.CENTER);

		hslField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				hslField.setText(String.valueOf(getColor()));
				validateField(hslField, true);
			}
		});
		hslField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e) { applyHslField(); }

			@Override
			public void removeUpdate(DocumentEvent e) { applyHslField(); }

			@Override
			public void changedUpdate(DocumentEvent e) { applyHslField(); }

			private void applyHslField()
			{
				if (!hslField.isFocusOwner()) return;
				String text = hslField.getText();
				try
				{
					int val = Integer.parseInt(text);
					validateField(hslField, val >= Short.MIN_VALUE && val <= Short.MAX_VALUE);
					short clamped = (short) Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, val));
					SwingUtilities.invokeLater(() -> setColor(clamped));
				}
				catch (NumberFormatException ignored)
				{
					validateField(hslField, false);
				}
			}
		});

		setColor(previous);

		hueSlider.addChangeListener(this::onUpdate);
		satSlider.addChangeListener(this::onUpdate);
		lumSlider.addChangeListener(this::onUpdate);
		onUpdate(null);

		SwingUtilities.invokeLater(() -> {
			hslField.requestFocusInWindow();
			hslField.selectAll();
		});
	}

	public void setColor(short hsl)
	{
		hueSlider.setValue(JagexColor.unpackHue(hsl));
		satSlider.setValue(JagexColor.unpackSaturation(hsl));
		lumSlider.setValue(JagexColor.unpackLuminance(hsl));
	}

	public short getColor()
	{
		return JagexColor.packHSL(hueSlider.getValue(), satSlider.getValue(), lumSlider.getValue());
	}

	private boolean isShaded()
	{
		return modeCombo.getSelectedIndex() <= 1;
	}

	private boolean isShadedGradient()
	{
		return modeCombo.getSelectedIndex() == 0;
	}

	private void onUpdate(ChangeEvent e)
	{
		short hsl = getColor();
		populateColorArray(hsl, previewColors);

		if (!hslField.isFocusOwner())
		{
			hslField.setText(String.valueOf(hsl));
		}
		if (!hueText.isFocusOwner())
		{
			hueText.setText(String.valueOf(hueSlider.getValue()));
		}
		if (!satText.isFocusOwner())
		{
			satText.setText(String.valueOf(satSlider.getValue()));
		}
		if (!lumText.isFocusOwner())
		{
			lumText.setText(String.valueOf(lumSlider.getValue()));
		}

		updateGradients();
		repaint();
		onChange.accept(hsl);
	}

	private static void validateField(JTextField field, boolean valid)
	{
		field.setBorder(valid ? VALID_BORDER : INVALID_BORDER);
	}

	private static Color[] getHueSpectrum()
	{
		Color[] colors = new Color[Colors.MAX_HUE + 1];
		for (int i = 0; i <= Colors.MAX_HUE; i++)
		{
			colors[i] = Colors.hslToColor(i, Colors.MAX_SAT, Colors.MAX_LUM / 2);
		}
		return colors;
	}

	private void updateGradients()
	{
		int h = hueSlider.getValue();
		int s = satSlider.getValue();
		int l = lumSlider.getValue();
		boolean shaded = isShaded();
		for (int i = 0; i <= Colors.MAX_SAT; i++)
		{
			satColors[i] = shaded
				? Colors.hslToShadedColor(h, i, l)
				: Colors.hslToColor(h, i, l);
		}
		for (int i = 0; i <= Colors.MAX_LUM; i++)
		{
			lumColors[i] = shaded
				? Colors.hslToShadedColor(h, s, i)
				: Colors.hslToColor(h, s, i);
		}
		((ColorSliderUI) satSlider.getUI()).setColors(satColors);
		((ColorSliderUI) lumSlider.getUI()).setColors(lumColors);
	}

	private JTextField createColorTextField(int max, JSlider slider)
	{
		JTextField field = new JTextField("0", 3);
		field.setHorizontalAlignment(JTextField.CENTER);
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				field.setText(String.valueOf(slider.getValue()));
				validateField(field, true);
			}
		});
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e) { apply(); }

			@Override
			public void removeUpdate(DocumentEvent e) { apply(); }

			@Override
			public void changedUpdate(DocumentEvent e) { apply(); }

			private void apply()
			{
				if (!field.isFocusOwner()) return;
				String text = field.getText();
				try
				{
					int val = Integer.parseInt(text);
					validateField(field, val >= 0 && val <= max);
					SwingUtilities.invokeLater(() ->
						slider.setValue(Math.max(0, Math.min(max, Integer.parseInt(text))))
					);
				}
				catch (NumberFormatException ignored)
				{
					validateField(field, false);
				}
			}
		});
		return field;
	}

	private JSlider createGradientSlider(int max, Color[] colors)
	{
		JSlider slider = new JSlider(0, max);
		slider.setPreferredSize(new Dimension(Colors.MAX_LUM * 2, slider.getPreferredSize().height));
		slider.setUI(new ColorSliderUI(slider, colors));
		return slider;
	}

	private JPanel createSliderRow(String labelText, String tooltip, JSlider slider, JTextField field)
	{
		JPanel row = new JPanel(new BorderLayout(2, 0));
		JLabel label = new JLabel(labelText);
		label.setToolTipText(tooltip);
		label.setPreferredSize(new Dimension(25, 0));
		row.add(label, BorderLayout.WEST);
		row.add(slider, BorderLayout.CENTER);
		row.add(field, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private JPanel createExportRow(String labelText, String tooltip, JTextField field)
	{
		JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
		JLabel label = new JLabel(labelText);
		label.setToolTipText(tooltip);
		panel.add(label);
		panel.add(field);

		JButton copyBtn = new JButton();
		ImageIcons.setCopyIcon(copyBtn);
		copyBtn.setToolTipText("Copy to clipboard");
		copyBtn.addActionListener(e -> copyToClipboard(field.getText()));
		panel.add(copyBtn);

		return panel;
	}

	private void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(text), null);
	}

	private Color[] createColorArray()
	{
		return new Color[isShadedGradient() ? SHADED_GRADIENT_STEPS : 1];
	}

	private void populateColorArray(short hsl, Color[] colors)
	{
		if (isShaded())
		{
			Colors.hslToShadedColors(hsl, colors);
		}
		else
		{
			colors[0] = Colors.hslToColor(hsl);
		}
	}

	private JButton createColorButton(short hsl, String tooltip)
	{
		JButton btn = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				var colors = createColorArray();
				populateColorArray(hsl, colors);
				ColorUtil.paintPreview(g, getWidth(), getHeight(), colors);
				super.paintComponent(g);
			}
		};
		btn.setAlignmentX(Component.CENTER_ALIGNMENT);
		btn.setPreferredSize(new Dimension(100, 25));
		btn.setMaximumSize(new Dimension(100, 25));
		btn.setBorder(BorderFactory.createLineBorder(Color.BLACK));
		btn.setContentAreaFilled(false);
		btn.setToolTipText(tooltip);
		btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		btn.addActionListener(e -> setColor(hsl));
		return btn;
	}
}

package io.huze.glamourer.ui.colorpicker;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.color.Colors;
import java.util.Collections;
import java.util.List;

public class SingleColorLabel extends ColorLabel
{
	private final ColorReplacement colorReplacement;

	public SingleColorLabel(String name, ColorReplacement colorReplacement)
	{
		super(name, colorReplacement.getOriginal());
		this.colorReplacement = colorReplacement;
		updateColorDisplay();
	}

	@Override
	protected List<ColorReplacement> getColorReplacements()
	{
		return Collections.singletonList(colorReplacement);
	}

	@Override
	protected String getDisplayText()
	{
		return Colors.formatHSL(colorReplacement.getReplacement());
	}

	@Override
	protected void revertToOriginal()
	{
		if (colorReplacement.hasChanged())
		{
			colorReplacement.setReplacement(colorReplacement.getOriginal());
			updateColorDisplay();
			notifyColorChange(colorReplacement.getReplacement());
		}
	}

	@Override
	protected void onColorChanged(short newColor)
	{
		colorReplacement.setReplacement(newColor);
		updateColorDisplay();
		notifyColorChange(newColor);
	}

	@Override
	protected short getPickerInitialColor()
	{
		return colorReplacement.getReplacement();
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.color.ColorGroupSettings;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

public class ThresholdSlidersPanel extends JPanel
{
	private static final int SLIDER_MIN = 0;
	private static final int SLIDER_MAX = 100;

	private final Config config;
	private final Runnable onSettingsChanged;

	private final JSlider hueSlider;
	private final JSlider satSlider;
	private final JSlider lumSlider;
	private final JLabel hueValue;
	private final JLabel satValue;
	private final JLabel lumValue;
	private final JCheckBox separateGrayscaleCheck;

	private boolean suppressEvents;

	public ThresholdSlidersPanel(Config config, Runnable onSettingsChanged)
	{
		this.config = config;
		this.onSettingsChanged = onSettingsChanged;

		setLayout(new GridBagLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(4, 6, 4, 6));

		GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(1, 2, 1, 2);
		c.fill = GridBagConstraints.HORIZONTAL;

		double hueDist = config.colorGroupHueDist();
		double satDist = config.colorGroupSatDist();
		double lumDist = config.colorGroupLumDist();
		boolean separateGrayscale = config.colorGroupSeparateGrayscale();

		// Row 0: Hue
		hueSlider = createSlider(hueDist);
		hueValue = new JLabel();
		addSliderRow(c, 0, "Hue", hueSlider, hueValue);

		// Row 1: Saturation
		satSlider = createSlider(satDist);
		satValue = new JLabel();
		addSliderRow(c, 1, "Saturation", satSlider, satValue);

		// Row 2: Luminance
		lumSlider = createSlider(lumDist);
		lumValue = new JLabel();
		addSliderRow(c, 2, "Luminance", lumSlider, lumValue);

		// Row 3: Separate grayscale checkbox + reset button
		separateGrayscaleCheck = new JCheckBox("Separate grayscale");
		separateGrayscaleCheck.setSelected(separateGrayscale);
		separateGrayscaleCheck.setOpaque(false);
		separateGrayscaleCheck.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		separateGrayscaleCheck.setToolTipText("Keep black, white, and gray colors in their own groups, separate from colored entries.");
		separateGrayscaleCheck.addActionListener(e -> onSliderChanged());

		c.gridy = 3;
		c.gridx = 0;
		c.gridwidth = 2;
		c.weightx = 1.0;
		c.fill = GridBagConstraints.HORIZONTAL;
		add(separateGrayscaleCheck, c);
		c.gridwidth = 1;

		JPanel resetPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		resetPanel.setOpaque(false);
		JButton resetButton = new JButton();
		ImageIcons.setResetIcon(resetButton, ColorScheme.DARK_GRAY_COLOR);
		resetButton.setToolTipText("Reset to defaults");
		resetButton.addActionListener(e -> resetToDefaults());
		resetPanel.add(resetButton);

		c.gridx = 2;
		c.weightx = 0;
		c.anchor = GridBagConstraints.EAST;
		c.fill = GridBagConstraints.NONE;
		add(resetPanel, c);

		updateValueLabels();
	}

	private JSlider createSlider(double value)
	{
		JSlider slider = new JSlider(SLIDER_MIN, SLIDER_MAX, toSlider(value));
		slider.setOpaque(false);
		slider.addChangeListener(e -> onSliderChanged());
		return slider;
	}

	private void addSliderRow(GridBagConstraints c, int row, String name, JSlider slider, JLabel valueLabel)
	{
		JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		valueLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		c.gridy = row;

		c.gridx = 0;
		c.weightx = 0;
		c.fill = GridBagConstraints.NONE;
		add(nameLabel, c);

		c.gridx = 1;
		c.weightx = 1.0;
		c.fill = GridBagConstraints.HORIZONTAL;
		add(slider, c);

		c.gridx = 2;
		c.weightx = 0;
		c.fill = GridBagConstraints.NONE;
		add(valueLabel, c);
	}

	private void onSliderChanged()
	{
		if (suppressEvents)
		{
			return;
		}
		updateValueLabels();
		saveToConfig();
		onSettingsChanged.run();
	}

	private void updateValueLabels()
	{
		hueValue.setText(String.format("%.2f", fromSlider(hueSlider.getValue())));
		satValue.setText(String.format("%.2f", fromSlider(satSlider.getValue())));
		lumValue.setText(String.format("%.2f", fromSlider(lumSlider.getValue())));
	}

	private void saveToConfig()
	{
		config.setColorGroupHueDist(fromSlider(hueSlider.getValue()));
		config.setColorGroupSatDist(fromSlider(satSlider.getValue()));
		config.setColorGroupLumDist(fromSlider(lumSlider.getValue()));
		config.setColorGroupSeparateGrayscale(separateGrayscaleCheck.isSelected());
	}

	private void resetToDefaults()
	{
		suppressEvents = true;
		hueSlider.setValue(toSlider(ColorGroupSettings.DEFAULT.getMaxHueDist()));
		satSlider.setValue(toSlider(ColorGroupSettings.DEFAULT.getMaxSatDist()));
		lumSlider.setValue(toSlider(ColorGroupSettings.DEFAULT.getMaxLumDist()));
		separateGrayscaleCheck.setSelected(ColorGroupSettings.DEFAULT.isSeparateGrayscale());
		suppressEvents = false;
		updateValueLabels();
		saveToConfig();
		onSettingsChanged.run();
	}

	private static double fromSlider(int v)
	{
		return (Math.pow(10, v / 100.0) - 1) / 9.0;
	}

	private static int toSlider(double v)
	{
		return (int) Math.round(Math.log10(v * 9.0 + 1) * 100);
	}
}

