package io.huze.glamourer.ui.texturepicker;

import io.huze.glamourer.texture.TextureReplacement;
import io.huze.glamourer.ui.DialogUtil;
import io.huze.glamourer.ui.Hoverable;
import io.huze.glamourer.ui.ImageIcons;
import io.huze.glamourer.ui.colorpicker.ColorLabel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Image;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import lombok.Setter;

public class TextureLabel extends JPanel implements Hoverable
{
	private static final int ICON_SIZE = ColorLabel.ROW_HEIGHT;

	@Setter
	@Nonnull private Consumer<Short> onTextureChange = x -> {};
	@Setter
	@Nonnull private Consumer<Short> onTexturePreview = x -> {};
	@Setter
	@Nonnull private Runnable onHoverStart = () -> {};
	@Setter
	@Nonnull private Runnable onHoverEnd = () -> {};
	private final String pickerName;
	private final TextureReplacement textureReplacement;
	private final JLabel textureDisplay;
	private final JButton revertButton;
	private JDialog activeDialog;

	public TextureLabel(String name, TextureReplacement textureReplacement)
	{
		this.pickerName = name;
		this.textureReplacement = textureReplacement;

		setLayout(new BorderLayout(3, 0));
		setOpaque(false);

		textureDisplay = new JLabel();
		textureDisplay.setOpaque(true);
		textureDisplay.setBackground(Color.BLACK);
		textureDisplay.setBorder(null);
		textureDisplay.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		textureDisplay.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				showPicker();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				onHoverStart.run();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				onHoverEnd.run();
			}
		});
		add(textureDisplay, BorderLayout.CENTER);

		revertButton = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				BufferedImage origImg = TexturePicker.getTextureImage(textureReplacement.getOriginal());
				if (origImg != null)
				{
					g.drawImage(origImg, 0, 0, getWidth(), getHeight(), null);
				}
				super.paintComponent(g);
			}
		};
		revertButton.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		revertButton.setToolTipText("Double-click to revert to original texture");
		revertButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		revertButton.setBorderPainted(false);
		revertButton.setFocusPainted(false);
		revertButton.setContentAreaFilled(false);
		ImageIcons.setResetIcon(revertButton, Color.DARK_GRAY);
		revertButton.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					revertToOriginal();
				}
			}
		});
		add(revertButton, BorderLayout.EAST);

		updateDisplay();
	}

	private void updateDisplay()
	{
		BufferedImage img = TexturePicker.getTextureImage(textureReplacement.getReplacement());
		if (img != null)
		{
			textureDisplay.setIcon(new ImageIcon(img.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH)));
		}
		textureDisplay.setText("Texture " + textureReplacement.getReplacement());
		textureDisplay.setForeground(Color.WHITE);

		revertButton.setVisible(textureReplacement.hasChanged());
		revertButton.repaint();
	}

	private void showPicker()
	{
		if (activeDialog != null && activeDialog.isVisible())
		{
			activeDialog.toFront();
			return;
		}

		final short initialTexture = textureReplacement.getReplacement();
		TexturePicker picker = new TexturePicker(initialTexture);
		picker.setOnChange(onTexturePreview);
		final AtomicBoolean okPressed = new AtomicBoolean();
		activeDialog = DialogUtil.showModelessDialogNearCursor(
			this,
			picker,
			pickerName,
			picker.getSizeControls(),
			d -> {
				okPressed.set(true);
				short selected = picker.getSelectedTextureId();
				if (selected != initialTexture)
				{
					textureReplacement.setReplacement(selected);
					updateDisplay();
					onTextureChange.accept(selected);
				}
			}
		);
		activeDialog.setResizable(true);
		activeDialog.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				if (!okPressed.get() && picker.getSelectedTextureId() != initialTexture)
				{
					onTexturePreview.accept(initialTexture);
				}
				activeDialog = null;
			}
		});
	}

	private void revertToOriginal()
	{
		if (textureReplacement.hasChanged())
		{
			textureReplacement.setReplacement(textureReplacement.getOriginal());
			updateDisplay();
			onTextureChange.accept(textureReplacement.getReplacement());
		}
	}

	public void setViewOnly()
	{
		textureDisplay.setCursor(Cursor.getDefaultCursor());
		revertButton.setCursor(Cursor.getDefaultCursor());
		revertButton.setToolTipText(null);
		revertButton.setIcon(null);
		revertButton.setRolloverIcon(null);
		for (var listener : textureDisplay.getMouseListeners())
		{
			textureDisplay.removeMouseListener(listener);
		}
	}

	@Override
	public void removeNotify()
	{
		onHoverEnd.run();
		if (activeDialog != null)
		{
			activeDialog.dispose();
			activeDialog = null;
		}
		super.removeNotify();
	}
}

package io.huze.glamourer.ui.texturepicker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Image;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.imageio.ImageIO;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.border.Border;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class TexturePicker extends JPanel
{
	private static final int BORDER_SIZE = 2;
	private static final int GAP = 2;
	private static final Border SELECTED_BORDER = BorderFactory.createLineBorder(Color.WHITE, BORDER_SIZE);
	private static final Border HOVER_BORDER = BorderFactory.createLineBorder(Color.LIGHT_GRAY, BORDER_SIZE);
	private static final Border DEFAULT_BORDER = BorderFactory.createLineBorder(Color.DARK_GRAY, BORDER_SIZE);
	private static final int[] SIZES = {32, 64, 128};

	private static Map<Short, BufferedImage> textureCache;
	private static int lastSizeIndex = 1;
	private static Dimension lastWindowSize = new Dimension(430, 400);

	@Setter
	@Nonnull private Consumer<Short> onChange = x -> {};
	@Getter
	private short selectedTextureId;
	@Getter
	private final JPanel sizeControls;
	private int thumbSize = SIZES[lastSizeIndex];
	private final JPanel gridPanel;
	private final JScrollPane scrollPane;

	public TexturePicker(short currentTextureId)
	{
		this.selectedTextureId = currentTextureId;
		setLayout(new BorderLayout());

		loadTextures();

		JComboBox<String> sizeCombo = new JComboBox<>(new String[]{"Small", "Medium", "Full"});
		sizeCombo.setSelectedIndex(lastSizeIndex);
		sizeCombo.addActionListener(e -> {
			lastSizeIndex = sizeCombo.getSelectedIndex();
			thumbSize = SIZES[lastSizeIndex];
			rebuildGrid();
		});
		sizeControls = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		sizeControls.add(new JLabel("Size:"));
		sizeControls.add(sizeCombo);

		gridPanel = new JPanel();
		scrollPane = new JScrollPane(gridPanel);
		scrollPane.setPreferredSize(lastWindowSize);
		scrollPane.addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				updateGridSize();
				lastWindowSize = scrollPane.getSize();
			}
		});
		add(scrollPane, BorderLayout.CENTER);

		rebuildGrid();
	}

	private void rebuildGrid()
	{
		gridPanel.removeAll();
		gridPanel.setLayout(new FlowLayout(FlowLayout.LEFT, GAP, GAP));
		previousSelected = null;

		int cellSize = thumbSize + BORDER_SIZE * 2;

		for (var entry : textureCache.entrySet())
		{
			short textureId = entry.getKey();
			BufferedImage img = entry.getValue();
			JLabel cell = createTextureCell(textureId, img, cellSize);
			gridPanel.add(cell);
		}

		updateGridSize();
		scrollPane.getVerticalScrollBar().setUnitIncrement(thumbSize);
	}

	private void updateGridSize()
	{
		int cellSize = thumbSize + BORDER_SIZE * 2;
		int viewWidth = scrollPane.getViewport().getWidth();
		if (viewWidth <= 0)
		{
			viewWidth = scrollPane.getPreferredSize().width - 20;
		}
		int cols = Math.max(1, (viewWidth - GAP) / (cellSize + GAP));
		int rows = (textureCache.size() + cols - 1) / cols;
		gridPanel.setPreferredSize(new Dimension(viewWidth, rows * (cellSize + GAP) + GAP));

		gridPanel.revalidate();
		gridPanel.repaint();
	}

	private JLabel createTextureCell(short textureId, BufferedImage img, int cellSize)
	{
		Image scaled = img.getScaledInstance(thumbSize, thumbSize, Image.SCALE_SMOOTH);
		JLabel cell = new JLabel(new ImageIcon(scaled));
		cell.setPreferredSize(new Dimension(cellSize, cellSize));
		cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		cell.setToolTipText("Texture " + textureId);
		cell.setBorder(textureId == selectedTextureId ? SELECTED_BORDER : DEFAULT_BORDER);

		cell.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (textureId != selectedTextureId)
				{
					cell.setBorder(HOVER_BORDER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (textureId != selectedTextureId)
				{
					cell.setBorder(DEFAULT_BORDER);
				}
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				selectTexture(textureId, cell);
			}
		});

		return cell;
	}

	private JLabel previousSelected;

	private void selectTexture(short textureId, JLabel cell)
	{
		if (previousSelected != null)
		{
			previousSelected.setBorder(DEFAULT_BORDER);
		}
		selectedTextureId = textureId;
		cell.setBorder(SELECTED_BORDER);
		previousSelected = cell;
		onChange.accept(textureId);
	}

	private static synchronized void loadTextures()
	{
		if (textureCache != null)
		{
			return;
		}
		textureCache = new LinkedHashMap<>();
		int consecutiveMisses = 0;
		for (int i = 0; consecutiveMisses < 3; i++)
		{
			try (InputStream is = TexturePicker.class.getResourceAsStream(i + ".png"))
			{
				if (is != null)
				{
					textureCache.put((short) i, ImageIO.read(is));
					consecutiveMisses = 0;
				}
				else
				{
					consecutiveMisses++;
				}
			}
			catch (IOException e)
			{
				log.warn("Failed to load texture {}", i, e);
				consecutiveMisses++;
			}
		}
	}

	public static BufferedImage getTextureImage(short textureId)
	{
		loadTextures();
		return textureCache.get(textureId);
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.item.SearchService;
import io.huze.glamourer.party.PartyInterface;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import java.awt.CardLayout;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.PluginPanel;

@Slf4j
public class MainPanel extends PluginPanel
{
	private static final String CARD_MAIN = "MAIN";
	private static final String CARD_SEARCH = "SEARCH";

	private final GlamourerPanel glamourerPanel;
	private final SearchPanel searchPanel;
	private final PlateManager plateManager;
	private final CardLayout cardLayout;

	private Plate currentSearchPlate;
	private int savedScrollPosition;

	@Inject
	public MainPanel(ClientThread clientThread, SearchService searchService,
					 ScheduledExecutorService executor, Config config,
					 PlateManager plateManager, PartyInterface partyInterface)
	{
		super(false);
		this.plateManager = plateManager;

		cardLayout = new CardLayout();
		setLayout(cardLayout);

		glamourerPanel = new GlamourerPanel(plateManager, partyInterface, config,
			this::showSearchPanelForPlate);

		searchPanel = new SearchPanel(clientThread, searchService, executor, config,
			this::onItemSelectedFromSearch, this::hideSearchPanel);

		add(glamourerPanel, CARD_MAIN);
		add(searchPanel, CARD_SEARCH);

		cardLayout.show(this, CARD_MAIN);
	}

	public void showError(Exception ex)
	{
		glamourerPanel.showError(ex);
		cardLayout.show(this, CARD_MAIN);
	}

	@Override
	public void onActivate()
	{
		glamourerPanel.onActivate();
	}

	public void showSearchPanelForPlate(Plate plate)
	{
		currentSearchPlate = plate;

		savedScrollPosition = glamourerPanel.getPlateManagerPanel().getScrollPosition();

		PlateRowPanel rowPanel = glamourerPanel.getPlateManagerPanel().findRowPanelForPlate(plate);
		if (rowPanel != null)
		{
			rowPanel.ensureExpanded();
		}

		searchPanel.setExistingItemIds(plate.getItemIds());
		searchPanel.clearSearch();
		cardLayout.show(this, CARD_SEARCH);
		searchPanel.focusSearchBar();
	}

	public void hideSearchPanel()
	{
		searchPanel.clearResults();
		cardLayout.show(this, CARD_MAIN);
		glamourerPanel.getPlateManagerPanel().setScrollPosition(savedScrollPosition);
		revalidate();
		repaint();
		currentSearchPlate = null;
	}

	private void onItemSelectedFromSearch(int itemId)
	{
		if (currentSearchPlate == null)
		{
			log.warn("No plate being edited when item selected");
			return;
		}

		final Plate searchPlate = currentSearchPlate;
		plateManager.addGlamour(searchPlate, itemId).thenRun(() -> {
			SwingUtilities.invokeLater(() -> {
				PlateRowPanel rowPanel = glamourerPanel.getPlateManagerPanel().findRowPanelForPlate(searchPlate);
				if (rowPanel != null)
				{
					rowPanel.rebuildDetailsPanel();
					rowPanel.ensureExpanded();
				}
				hideSearchPanel();
			});
		});
	}
}

package io.huze.glamourer.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

public class DialogUtil
{

	public static JDialog showModelessDialogNearCursor(Component parent, JPanel content,
													   String title, Consumer<JDialog> onOk)
	{
		return showModelessDialogNearCursor(parent, content, title, null, onOk);
	}

	public static JDialog showModelessDialogNearCursor(Component parent, JPanel content,
													   String title, Component bottomLeft,
													   Consumer<JDialog> onOk)
	{
		JDialog dialog = new JDialog(
			SwingUtilities.windowForComponent(parent),
			title
		);
		dialog.setModalityType(Dialog.ModalityType.MODELESS);

		JPanel contentPanel = new JPanel(new BorderLayout(0, 5));
		contentPanel.setBorder(new EmptyBorder(10, 10, 10, 10));
		contentPanel.add(content, BorderLayout.CENTER);

		JPanel bottomPanel = new JPanel(new BorderLayout());
		JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
		JButton okButton = new JButton("OK");
		JButton cancelButton = new JButton("Cancel");
		okButton.addActionListener(e -> {
			onOk.accept(dialog);
			dialog.dispose();
		});
		cancelButton.addActionListener(e -> dialog.dispose());
		buttonPanel.add(okButton);
		buttonPanel.add(cancelButton);
		bottomPanel.add(buttonPanel, BorderLayout.EAST);
		if (bottomLeft != null)
		{
			bottomPanel.add(bottomLeft, BorderLayout.WEST);
		}
		contentPanel.add(bottomPanel, BorderLayout.SOUTH);

		contentPanel.setFocusable(true);
		installDefocusListeners(contentPanel, contentPanel);

		dialog.setContentPane(contentPanel);
		dialog.getRootPane().setDefaultButton(okButton);
		dialog.setResizable(false);
		dialog.pack();
		positionNearCursor(dialog);
		dialog.setVisible(true);
		return dialog;
	}

	private static void installDefocusListeners(Container container, Component focusTarget)
	{
		for (Component comp : container.getComponents())
		{
			if (!(comp instanceof JTextField) && !(comp instanceof JComboBox))
			{
				comp.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						focusTarget.requestFocusInWindow();
					}
				});
			}
			if (comp instanceof Container && !(comp instanceof JComboBox))
			{
				installDefocusListeners((Container) comp, focusTarget);
			}
		}
	}

	public static int showConfirmDialogNearCursor(Component parent, Object message, String title,
												  int optionType, int messageType)
	{
		JOptionPane pane = new JOptionPane(message, messageType, optionType);
		JDialog dialog = pane.createDialog(parent, title);
		positionNearCursor(dialog);
		dialog.setVisible(true);

		Object selectedValue = pane.getValue();
		if (selectedValue == null)
		{
			return JOptionPane.CLOSED_OPTION;
		}
		if (selectedValue instanceof Integer)
		{
			return (Integer) selectedValue;
		}
		return JOptionPane.CLOSED_OPTION;
	}

	public static void positionNearCursor(Window dialog)
	{
		Point mousePos = MouseInfo.getPointerInfo().getLocation();
		Dimension dialogSize = dialog.getSize();

		// Get screen bounds
		GraphicsEnvironment ge = GraphicsEnvironment.getLocalGraphicsEnvironment();
		Rectangle screenBounds = ge.getDefaultScreenDevice().getDefaultConfiguration().getBounds();

		// Try to find the screen the mouse is on
		for (GraphicsDevice gd : ge.getScreenDevices())
		{
			Rectangle bounds = gd.getDefaultConfiguration().getBounds();
			if (bounds.contains(mousePos))
			{
				screenBounds = bounds;
				break;
			}
		}

		// Position dialog with small offset from cursor
		int x = mousePos.x + 10;
		int y = mousePos.y + 10;

		// Ensure dialog stays within screen bounds
		if (x + dialogSize.width > screenBounds.x + screenBounds.width)
		{
			x = mousePos.x - dialogSize.width - 10;
		}
		if (y + dialogSize.height > screenBounds.y + screenBounds.height)
		{
			y = mousePos.y - dialogSize.height - 10;
		}
		if (x < screenBounds.x)
		{
			x = screenBounds.x;
		}
		if (y < screenBounds.y)
		{
			y = screenBounds.y;
		}

		dialog.setLocation(x, y);
	}
}

package io.huze.glamourer.ui;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.PrintWriter;
import java.io.StringWriter;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

class ExceptionPanel extends JPanel implements GlamourerSubPanel
{
	ExceptionPanel(Exception ex)
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel message = new JLabel("<html>Glamourer encountered a critical error.<br><br>Please report this error on Discord or GitHub and wait for it to be fixed.<br><br>Sorry :(</html>");
		message.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		message.setBorder(new EmptyBorder(10, 10, 10, 10));
		message.setAlignmentX(LEFT_ALIGNMENT);
		contentPanel.add(message);

		StringWriter sw = new StringWriter();
		ex.printStackTrace(new PrintWriter(sw));
		final var stackTrace = sw.toString();

		JTextArea textArea = new JTextArea(stackTrace);
		textArea.setEditable(false);
		textArea.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 11));
		textArea.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		textArea.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		textArea.setCaretPosition(0);
		textArea.setBorder(new EmptyBorder(5, 5, 5, 5));

		JScrollPane scrollPane = new JScrollPane(textArea);
		scrollPane.setBorder(new EmptyBorder(0, 0, 0, 0));
		scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_NEVER);
		scrollPane.setAlignmentX(LEFT_ALIGNMENT);
		Dimension preferred = textArea.getPreferredSize();
		int scrollBarHeight = scrollPane.getHorizontalScrollBar().getPreferredSize().height;
		scrollPane.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height + scrollBarHeight));
		contentPanel.add(scrollPane);

		JButton copyButton = new JButton("Copy to Clipboard");
		copyButton.setAlignmentX(LEFT_ALIGNMENT);
		copyButton.addActionListener(e -> {
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(stackTrace), null);
			copyButton.setText("Copied!");
		});
		contentPanel.add(copyButton);

		add(contentPanel, BorderLayout.NORTH);
	}

	@Override
	public String getCardKey()
	{
		return "ERROR";
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.plate.Plate;
import java.awt.Color;
import java.awt.Insets;
import java.awt.datatransfer.DataFlavor;
import java.awt.dnd.DnDConstants;
import java.awt.dnd.DragGestureListener;
import java.awt.dnd.DragSource;
import java.awt.dnd.DropTarget;
import java.awt.dnd.DropTargetAdapter;
import java.awt.dnd.DropTargetDragEvent;
import java.awt.dnd.DropTargetDropEvent;
import java.awt.dnd.DropTargetEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import javax.swing.UIManager;

public class ItemDragDropHandler
{

	private static final Color DRAG_INDICATOR_COLOR = new Color(220, 138, 0);
	static final DataFlavor ITEM_FLAVOR = new DataFlavor(ItemData.class, "GlamourItem");

	public interface ItemMoveCallback
	{
		void moveItem(Plate sourcePlate, int sourceIndex, Plate targetPlate, int targetIndex);
	}

	/// Data transferred during item drag operations.
	public static class ItemData
	{
		public final Plate plate;
		public final int index;

		public ItemData(Plate plate, int index)
		{
			this.plate = plate;
			this.index = index;
		}
	}

	public static void setupItemDragAndDrop(JComponent component, Plate plate, int index,
											ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		setupDragSource(component, plate, index, onDragEnd);
		setupItemDropTarget(component, plate, index, moveCallback);
	}

	private static void setupDragSource(JComponent component, Plate plate, int index, Runnable onDragEnd)
	{
		Color originalBackground = component.getBackground();
		DragSource dragSource = DragSource.getDefaultDragSource();

		DragGestureListener listener = dge -> {
			if (DragDropUtil.isLeftButtonDrag(dge))
			{
				SingleFlavorTransferable<ItemData> transferable =
					new SingleFlavorTransferable<>(ITEM_FLAVOR, new ItemData(plate, index));
				DragDropUtil.startDrag(dge, transferable, component, originalBackground, onDragEnd);
			}
		};

		dragSource.createDefaultDragGestureRecognizer(component, DnDConstants.ACTION_MOVE, listener);
	}

	private static void setupItemDropTarget(JComponent component, Plate plate, int index,
											ItemMoveCallback moveCallback)
	{
		javax.swing.border.Border originalBorder = component.getBorder();
		Insets originalInsets = originalBorder != null ? originalBorder.getBorderInsets(component) : new Insets(0, 0, 0, 0);

		new DropTarget(component, DnDConstants.ACTION_MOVE, new DropTargetAdapter()
		{
			private boolean insertAfter = false;

			@Override
			public void dragOver(DropTargetDragEvent dtde)
			{
				ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
				if (data == null)
				{
					return;
				}

				dtde.acceptDrag(DnDConstants.ACTION_MOVE);
				insertAfter = calculateInsertPosition(dtde, data, plate, index, component);
				updateDragIndicator(component, data, plate, index, originalBorder, originalInsets, insertAfter);
			}

			@Override
			public void dragExit(DropTargetEvent dte)
			{
				component.setBorder(originalBorder);
			}

			@Override
			public void drop(DropTargetDropEvent dtde)
			{
				component.setBorder(originalBorder);
				handleItemDrop(dtde, plate, index, insertAfter, moveCallback);
			}
		}, true);
	}

	private static boolean calculateInsertPosition(DropTargetDragEvent dtde, ItemData data,
												   Plate plate, int index, JComponent component)
	{
		if (data.plate == plate)
		{
			return DragDropUtil.shouldInsertAfter(data.index, index);
		}
		else
		{
			return dtde.getLocation().y >= component.getHeight() / 2;
		}
	}

	private static void updateDragIndicator(JComponent component, ItemData data, Plate plate, int index,
											javax.swing.border.Border originalBorder, Insets originalInsets,
											boolean insertAfter)
	{
		if (data.plate == plate && data.index == index)
		{
			component.setBorder(originalBorder);
		}
		else
		{
			component.setBorder(DragDropUtil.createIndicatorBorder(originalInsets, !insertAfter, DRAG_INDICATOR_COLOR));
		}
	}

	private static void handleItemDrop(DropTargetDropEvent dtde, Plate plate, int index,
									   boolean insertAfter, ItemMoveCallback moveCallback)
	{
		ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
		if (data == null)
		{
			return;
		}

		if (data.plate == plate && data.index == index)
		{
			dtde.dropComplete(false);
			return;
		}

		dtde.acceptDrop(DnDConstants.ACTION_MOVE);
		int targetIndex = (data.plate == plate)
			? DragDropUtil.adjustTargetIndex(data.index, index, insertAfter)
			: (insertAfter ? index + 1 : index);

		moveCallback.moveItem(data.plate, data.index, plate, targetIndex);
		dtde.dropComplete(true);
	}

	public static void setupAddItemButtonDropTarget(JButton button, Plate plate,
													ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		String originalText = button.getText();

		new DropTarget(button, DnDConstants.ACTION_MOVE, new DropTargetAdapter()
		{
			private boolean isValidDrop = false;

			@Override
			public void dragOver(DropTargetDragEvent dtde)
			{
				ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
				isValidDrop = data != null && data.plate != plate;

				if (isValidDrop)
				{
					dtde.acceptDrag(DnDConstants.ACTION_MOVE);
					showDropZoneAppearance(button);
				}
			}

			@Override
			public void dragExit(DropTargetEvent dte)
			{
				revertButtonAppearance(button, originalText);
			}

			@Override
			public void drop(DropTargetDropEvent dtde)
			{
				revertButtonAppearance(button, originalText);
				handleButtonDrop(dtde, isValidDrop, plate, moveCallback, onDragEnd);
			}
		}, true);
	}

	private static void showDropZoneAppearance(JButton button)
	{
		button.setText("Drop Here");
		button.setBackground(new Color(
			DRAG_INDICATOR_COLOR.getRed(),
			DRAG_INDICATOR_COLOR.getGreen(),
			DRAG_INDICATOR_COLOR.getBlue(), 100));
		button.setBorder(BorderFactory.createLineBorder(DRAG_INDICATOR_COLOR, 2));
		button.setContentAreaFilled(true);
	}

	private static void revertButtonAppearance(JButton button, String originalText)
	{
		button.setText(originalText);
		button.setContentAreaFilled(false);
		button.setBorder(UIManager.getBorder("Button.border"));
	}

	private static void handleButtonDrop(DropTargetDropEvent dtde, boolean isValidDrop,
										 Plate plate, ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
		if (!isValidDrop || data == null)
		{
			dtde.rejectDrop();
			return;
		}

		dtde.acceptDrop(DnDConstants.ACTION_MOVE);
		moveCallback.moveItem(data.plate, data.index, plate, plate.getGlamours().size());
		dtde.dropComplete(true);

		if (onDragEnd != null)
		{
			SwingUtilities.invokeLater(onDragEnd);
		}
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.plate.ChangeLog;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.FlowLayout;
import java.awt.Toolkit;
import java.awt.event.ActionEvent;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.BoxLayout;
import javax.swing.KeyStroke;
import javax.swing.border.EmptyBorder;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.components.PluginErrorPanel;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

@Slf4j
public class PlateManagerPanel extends JPanel implements GlamourerSubPanel
{
	private final PlateManager plateManager;
	private final Consumer<Plate> onAddItemRequest;
	private final Config config;
	private final ChangeLog changeLog;

	private final PluginErrorPanel infoPanel;
	private final VerticalScrollPane scrollPane;
	private final JButton expandCollapseAllButton;
	private final JButton undoButton;
	private final JButton redoButton;
	private final JPanel toolbarButtons;
	private final JPanel secondaryToolbar;
	private final JPanel subHeaderPanel;
	private final ThresholdSlidersPanel thresholdSlidersPanel;
	private final String undoShortcutText;
	private final String redoShortcutText;
	private boolean pendingScrollToBottom;
	private int iconScale;

	public PlateManagerPanel(PlateManager plateManager, Config config, Consumer<Plate> onAddItemRequest)
	{
		this.plateManager = plateManager;
		this.config = config;
		this.changeLog = plateManager.getChangeLog();
		this.onAddItemRequest = onAddItemRequest;
		this.iconScale = config.iconScale();

		setLayout(new BorderLayout());

		// Title bar toolbar (right side of title)
		toolbarButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		toolbarButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		ToggleButton slidersToggleButton = new ToggleButton();
		ImageIcons.setSlidersIcon(slidersToggleButton);
		slidersToggleButton.setToolTipText("Color group settings");
		toolbarButtons.add(slidersToggleButton);

		JButton importPlateButton = new JButton();
		ImageIcons.setImportIcon(importPlateButton);
		importPlateButton.setToolTipText("Import plate JSON");
		toolbarButtons.add(importPlateButton);

		JButton createPlateButton = new JButton();
		ImageIcons.setCreateIcon(createPlateButton);
		createPlateButton.setToolTipText("Create empty plate");
		toolbarButtons.add(createPlateButton);

		expandCollapseAllButton = new JButton();
		expandCollapseAllButton.addActionListener(e -> toggleExpandCollapseAll());
		toolbarButtons.add(expandCollapseAllButton);

		// Secondary toolbar row (below title)
		secondaryToolbar = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 2));
		secondaryToolbar.setBorder(new EmptyBorder(0, 5, 0, 0));
		secondaryToolbar.setBackground(ColorScheme.DARK_GRAY_COLOR);

		undoButton = new JButton();
		ImageIcons.setUndoIcon(undoButton, false);
		undoButton.setToolTipText("Undo");
		undoButton.setEnabled(false);
		undoButton.addActionListener(e -> {
			changeLog.undo();
			rebuildPlatesSection();
		});
		secondaryToolbar.add(undoButton);

		redoButton = new JButton();
		ImageIcons.setRedoIcon(redoButton, false);
		redoButton.setToolTipText("Redo");
		redoButton.setEnabled(false);
		redoButton.addActionListener(e -> {
			changeLog.redo();
			rebuildPlatesSection();
		});
		secondaryToolbar.add(redoButton);

		changeLog.setOnUndoRedoAvailabilityChanged(() -> SwingUtilities.invokeLater(this::updateUndoRedoButtons));

		thresholdSlidersPanel = new ThresholdSlidersPanel(config, this::rebuildPlatesSection);
		thresholdSlidersPanel.setVisible(false);

		slidersToggleButton.addActionListener(e -> {
			boolean visible = !thresholdSlidersPanel.isVisible();
			thresholdSlidersPanel.setVisible(visible);
			slidersToggleButton.setActive(visible);
		});

		// Sub-header: secondary toolbar + threshold sliders
		subHeaderPanel = new JPanel();
		subHeaderPanel.setLayout(new BoxLayout(subHeaderPanel, BoxLayout.Y_AXIS));
		subHeaderPanel.add(secondaryToolbar);
		subHeaderPanel.add(thresholdSlidersPanel);

		infoPanel = new PluginErrorPanel();
		infoPanel.setContent("Getting Started",
			"Create a new plate with the + button, then search for items to glamour.");

		scrollPane = new VerticalScrollPane();
		add(scrollPane, BorderLayout.CENTER);

		// Undo/Redo keybindings (active when panel is showing)
		int menuShortcutMask = Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx();
		String modifierName = InputEvent.getModifiersExText(menuShortcutMask);
		undoShortcutText = modifierName + " + Z";
		redoShortcutText = modifierName + " + Shift + Z  /  " + modifierName + " + Y";

		var inputMap = getInputMap(WHEN_IN_FOCUSED_WINDOW);
		inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_Z, menuShortcutMask), "glamourerUndo");
		inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_Z, menuShortcutMask | InputEvent.SHIFT_DOWN_MASK), "glamourerRedo");
		inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_Y, menuShortcutMask), "glamourerRedo");
		getActionMap().put("glamourerUndo", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				SwingUtilities.invokeLater(() -> {
					changeLog.undo();
					rebuildPlatesSection();
				});
			}
		});
		getActionMap().put("glamourerRedo", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				SwingUtilities.invokeLater(() -> {
					changeLog.redo();
					rebuildPlatesSection();
				});
			}
		});

		importPlateButton.addActionListener(e -> {
			ImportPlateDialog dialog = new ImportPlateDialog(
				SwingUtilities.windowForComponent(this),
				config,
				plateManager,
				config.iconScale() / 100f
			);
			pendingScrollToBottom = true;
			dialog.setVisible(true);
			if (!dialog.isImported() || dialog.isOverwritten())
			{
				pendingScrollToBottom = false;
			}
		});

		createPlateButton.addActionListener(e -> {
			pendingScrollToBottom = true;
			plateManager.createPlate();
			rebuildPlatesSection();
		});

		// Listen for plate changes
		plateManager.setOnPlatesChanged(v -> SwingUtilities.invokeLater(this::rebuildPlatesSection));
	}

	@Override
	public String getCardKey()
	{
		return "PLATES";
	}

	@Override
	public JPanel getToolbarButtons()
	{
		return toolbarButtons;
	}

	@Nullable
	@Override
	public JPanel getSubHeaderPanel()
	{
		return subHeaderPanel;
	}

	@Override
	public void onActivate()
	{
		if (config.iconScale() != iconScale)
		{
			iconScale = config.iconScale();
			rebuildPlatesSection();
		}
	}

	public void rebuildPlatesSection()
	{
		var platesContainer = scrollPane.getContainer();

		// Save existing collapse state before removing panels
		Map<String, PlateRowPanel> oldPanels = new HashMap<>();
		for (Component comp : platesContainer.getComponents())
		{
			if (comp instanceof PlateRowPanel)
			{
				PlateRowPanel row = (PlateRowPanel) comp;
				oldPanels.put(row.getPlate().getId(), row);
			}
		}

		platesContainer.removeAll();

		List<Plate> plates = plateManager.getPlates();
		if (plates.isEmpty())
		{
			platesContainer.add(infoPanel);
		}
		for (int i = 0; i < plates.size(); i++)
		{
			Plate plate = plates.get(i);
			PlateRowPanel rowPanel = new PlateRowPanel(
				plate, plateManager.getIconService(), plateManager.getGlamourer(), config,
				plateManager::exportPlateJson,
				iconScale / 100f, onAddItemRequest,
				p -> plateManager.deletePlate(p.getId()),
				() -> {
					updateExpandCollapseButton();
					revalidate();
					repaint();
				},
				this::handleItemMove,
				plateManager::setPlateEnabled,
				plateManager::setPlateDisplayStyle,
				plateManager::removeGlamour,
				plateManager::setPlateIconStyle
			);

			PlateRowPanel oldPanel = oldPanels.get(plate.getId());
			if (oldPanel != null)
			{
				rowPanel.restoreCollapseState(oldPanel);
			}

			PlateDragDropHandler.setupDragAndDrop(
				rowPanel.getHeaderPanel(),
				rowPanel,
				i,
				plateManager::movePlate,
				this::rebuildPlatesSection
			);

			platesContainer.add(rowPanel);
		}

		updateExpandCollapseButton();

		platesContainer.revalidate();
		platesContainer.repaint();

		if (pendingScrollToBottom)
		{
			pendingScrollToBottom = false;
			SwingUtilities.invokeLater(scrollPane::scrollToBottom);
		}
	}

	public PlateRowPanel findRowPanelForPlate(Plate plate)
	{
		for (Component comp : scrollPane.getContainer().getComponents())
		{
			if (comp instanceof PlateRowPanel)
			{
				PlateRowPanel row = (PlateRowPanel) comp;
				if (row.getPlate() == plate)
				{
					return row;
				}
			}
		}
		return null;
	}

	private boolean isAnyPlateExpanded()
	{
		for (Component comp : scrollPane.getContainer().getComponents())
		{
			if (comp instanceof PlateRowPanel)
			{
				if (((PlateRowPanel) comp).isExpanded())
				{
					return true;
				}
			}
		}
		return false;
	}

	private void updateUndoRedoButtons()
	{
		boolean canUndo = changeLog.canUndo();
		boolean canRedo = changeLog.canRedo();
		undoButton.setEnabled(canUndo);
		redoButton.setEnabled(canRedo);
		ImageIcons.setUndoIcon(undoButton, canUndo);
		ImageIcons.setRedoIcon(redoButton, canRedo);

		String undoDesc = changeLog.undoDescription();
		undoButton.setToolTipText("<html>" + undoDesc + "<br>" + undoShortcutText + "</html>");
		String redoDesc = changeLog.redoDescription();
		redoButton.setToolTipText("<html>" + redoDesc + "<br>" + redoShortcutText + "</html>");
	}

	private void updateExpandCollapseButton()
	{
		boolean hasExpanded = isAnyPlateExpanded();
		ImageIcons.setExpandCollapseAllIcon(expandCollapseAllButton, hasExpanded);
		expandCollapseAllButton.setToolTipText(hasExpanded ? "Collapse all" : "Expand all");
	}

	private void toggleExpandCollapseAll()
	{
		boolean shouldExpand = !isAnyPlateExpanded();
		for (Component comp : scrollPane.getContainer().getComponents())
		{
			if (comp instanceof PlateRowPanel)
			{
				((PlateRowPanel) comp).setExpanded(shouldExpand);
			}
		}
		updateExpandCollapseButton();
	}

	private void handleItemMove(Plate sourcePlate, int sourceIndex, Plate targetPlate, int targetIndex)
	{
		if (sourcePlate == targetPlate)
		{
			plateManager.moveGlamour(sourcePlate, sourceIndex, targetIndex);
			PlateRowPanel sourceRow = findRowPanelForPlate(sourcePlate);
			if (sourceRow != null)
			{
				sourceRow.rebuildDetailsPanel();
			}
		}
		else
		{
			plateManager.transferGlamour(sourcePlate, sourceIndex, targetPlate, targetIndex);
			rebuildAllRowPanels();
		}
	}

	private void rebuildAllRowPanels()
	{
		for (Component comp : scrollPane.getContainer().getComponents())
		{
			if (comp instanceof PlateRowPanel)
			{
				((PlateRowPanel) comp).rebuildDetailsPanel();
			}
		}
	}

	public int getScrollPosition()
	{
		return scrollPane.getVerticalScrollBar().getValue();
	}

	public void setScrollPosition(int position)
	{
		SwingUtilities.invokeLater(() -> scrollPane.getVerticalScrollBar().setValue(position));
	}
}

package io.huze.glamourer.ui;

import java.awt.Dimension;
import java.awt.Rectangle;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;

public class VerticalScrollPane extends JScrollPane
{
	public VerticalScrollPane()
	{
		super(new ScrollableContainer());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		getVerticalScrollBar().setPreferredSize(new Dimension(10, 0));
		setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
	}

	ScrollableContainer getContainer()
	{
		return (ScrollableContainer) getViewport().getView();
	}

	void scrollToTop()
	{
		getVerticalScrollBar().setValue(0);
	}

	void scrollToBottom()
	{
		var vertical = getVerticalScrollBar();
		vertical.setValue(vertical.getMaximum());
	}

	/// Scrollable wrapper forces content width to match the viewport, preventing clipping when the scrollbar appears
	public static class ScrollableContainer extends JPanel implements Scrollable
	{
		private ScrollableContainer()
		{
			setBackground(ColorScheme.DARK_GRAY_COLOR);
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

}

package io.huze.glamourer.ui;

import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;

/**
 * Generic Transferable implementation for drag-and-drop operations
 * that transfer a single data type.
 *
 * @param <T> The type of data being transferred
 */
public class SingleFlavorTransferable<T> implements Transferable
{
	private final DataFlavor flavor;
	private final DataFlavor[] flavors;
	private final T data;

	public SingleFlavorTransferable(DataFlavor flavor, T data)
	{
		this.flavor = flavor;
		this.flavors = new DataFlavor[]{flavor};
		this.data = data;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return flavors;
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return this.flavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return data;
	}
}

package io.huze.glamourer.ui;

import java.awt.Color;
import java.awt.Insets;
import java.awt.Point;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.dnd.DragGestureEvent;
import java.awt.dnd.DragSource;
import java.awt.dnd.DragSourceAdapter;
import java.awt.dnd.DragSourceDropEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;

public class DragDropUtil
{
	public static final Color DRAGGING_SOURCE_COLOR = new Color(60, 60, 60);
	public static final int INDICATOR_THICKNESS = 2;

	/// Creates a border that shows a drop indicator line on top or bottom, while preserving the original padding/insets.
	public static Border createIndicatorBorder(Insets originalInsets, boolean showOnTop, Color color)
	{
		int top = originalInsets.top;
		int bottom = originalInsets.bottom;
		int left = originalInsets.left;
		int right = originalInsets.right;

		if (showOnTop)
		{
			return BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(INDICATOR_THICKNESS, 0, 0, 0, color),
				BorderFactory.createEmptyBorder(Math.max(0, top - INDICATOR_THICKNESS), left, bottom, right)
			);
		}
		else
		{
			return BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, INDICATOR_THICKNESS, 0, color),
				BorderFactory.createEmptyBorder(top, left, Math.max(0, bottom - INDICATOR_THICKNESS), right)
			);
		}
	}

	 /// Starts a drag operation with standard visual feedback.
	public static void startDrag(DragGestureEvent dge, Transferable transferable,
								 JComponent visualComponent, Color originalBackground,
								 Runnable onDragEnd)
	{
		// Dim the source component
		visualComponent.setBackground(DRAGGING_SOURCE_COLOR);

		// Use transparent drag image to avoid ghost
		BufferedImage transparentImg = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

		dge.getDragSource().startDrag(
			dge,
			DragSource.DefaultMoveDrop,
			transparentImg,
			new Point(0, 0),
			transferable,
			new DragSourceAdapter()
			{
				@Override
				public void dragDropEnd(DragSourceDropEvent dsde)
				{
					visualComponent.setBackground(originalBackground);
					if (onDragEnd != null)
					{
						SwingUtilities.invokeLater(onDragEnd);
					}
				}
			}
		);
	}

	/// Checks if a drag gesture was initiated with the left mouse button.
	/// Only left-button drags should start drag operations.
	public static boolean isLeftButtonDrag(DragGestureEvent dge)
	{
		if (dge.getTriggerEvent() instanceof MouseEvent)
		{
			MouseEvent me = (MouseEvent) dge.getTriggerEvent();
			return SwingUtilities.isLeftMouseButton(me);
		}
		return true; // Default to allowing if we can't determine
	}

	/// Calculates the target index adjustment when reordering items.
	/// Handles the case where removing an item before the target shifts indices.
	public static int adjustTargetIndex(int sourceIndex, int targetIndex, boolean insertAfter)
	{
		int adjustedTarget = insertAfter ? targetIndex + 1 : targetIndex;

		// If moving within same container and source is before target, adjust for removal
		if (sourceIndex < targetIndex && insertAfter)
		{
			adjustedTarget = targetIndex;
		}

		return adjustedTarget;
	}

	/// Determines whether to show the drop indicator on top or bottom based on drag direction within the same container.
	public static boolean shouldInsertAfter(int sourceIndex, int targetIndex)
	{
		// Dragging down (source above target): insert after (bottom indicator)
		// Dragging up (source below target): insert before (top indicator)
		return sourceIndex < targetIndex;
	}

	/// Extracts transfer data safely, returning null on any error.
	@SuppressWarnings("unchecked")
	public static <T> T getTransferData(Transferable transferable, DataFlavor flavor, Class<T> type)
	{
		try
		{
			if (transferable.isDataFlavorSupported(flavor))
			{
				Object data = transferable.getTransferData(flavor);
				if (type.isInstance(data))
				{
					return (T) data;
				}
			}
		}
		catch (Exception ignored)
		{
		}
		return null;
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.GlamourVisibility;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.party.PartyInterface;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.PluginErrorPanel;

public class PartyPanel extends JPanel implements GlamourerSubPanel
{
	private final PartyInterface partyInterface;
	private final Config config;
	private final IconService iconService;
	private final Set<Long> expandedMembers = new HashSet<>();
	private final JPanel toolbarButtons;
	private final ToggleButton settingsToggleButton;
	private final JPanel settingsPanel;
	private final ToggleSwitch sendToggle;
	private final ToggleSwitch recvToggle;
	private final JPanel contentPanel;
	private final JPanel membersContainer;
	private final PluginErrorPanel infoPanel;

	public PartyPanel(PartyInterface partyInterface, Config config, IconService iconService)
	{
		this.partyInterface = partyInterface;
		this.config = config;
		this.iconService = iconService;

		setLayout(new BorderLayout());

		// --- Toolbar button: settings cog ---
		toolbarButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		toolbarButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton resyncButton = new JButton();
		ImageIcons.setSyncIcon(resyncButton);
		resyncButton.setToolTipText("Resync glamours with all party members");
		resyncButton.addActionListener(e -> partyInterface.resync());
		toolbarButtons.add(resyncButton);

		settingsToggleButton = new ToggleButton();
		ImageIcons.setCogIcon(settingsToggleButton);
		settingsToggleButton.setToolTipText("Settings");
		toolbarButtons.add(settingsToggleButton);

		// --- Settings sub-header (initially hidden) ---
		settingsPanel = new JPanel();
		settingsPanel.setLayout(new BoxLayout(settingsPanel, BoxLayout.Y_AXIS));
		settingsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		settingsPanel.setBorder(new EmptyBorder(6, 8, 6, 8));
		settingsPanel.setVisible(false);

		sendToggle = new ToggleSwitch(config.partySyncSend());
		settingsPanel.add(createToggleRow(Config.NAME_PARTY_SYNC_SEND,
			Config.DESC_PARTY_SYNC_SEND,
			sendToggle,
			config::setPartySyncSend));

		recvToggle = new ToggleSwitch(config.partySyncReceive());
		settingsPanel.add(createToggleRow(Config.NAME_PARTY_SYNC_RECV,
			Config.DESC_PARTY_SYNC_RECV,
			recvToggle,
			config::setPartySyncReceive));

		settingsToggleButton.addActionListener(e -> {
			boolean visible = !settingsPanel.isVisible();
			settingsPanel.setVisible(visible);
			settingsToggleButton.setActive(visible);
		});

		// --- Info panel for empty states ---
		infoPanel = new PluginErrorPanel();
		infoPanel.setVisible(false);

		// --- Content: members list ---
		contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBorder(new EmptyBorder(6, 6, 6, 6));

		JPanel membersSection = new JPanel(new BorderLayout());
		membersSection.setOpaque(false);

		JLabel membersLabel = new JLabel("Party Members");
		membersLabel.setForeground(Color.WHITE);
		membersLabel.setBorder(new EmptyBorder(0, 0, 4, 0));
		membersSection.add(membersLabel, BorderLayout.NORTH);

		membersContainer = new JPanel();
		membersContainer.setLayout(new BoxLayout(membersContainer, BoxLayout.Y_AXIS));
		membersContainer.setOpaque(false);
		membersSection.add(membersContainer, BorderLayout.CENTER);

		contentPanel.add(membersSection);

		JPanel centerPanel = new JPanel(new BorderLayout());
		centerPanel.add(infoPanel, BorderLayout.NORTH);
		VerticalScrollPane scrollPane = new VerticalScrollPane();
		scrollPane.getContainer().add(contentPanel);
		centerPanel.add(scrollPane, BorderLayout.CENTER);
		add(centerPanel, BorderLayout.CENTER);

		// Register for state changes
		partyInterface.setOnStateChanged(() -> SwingUtilities.invokeLater(this::rebuildMembers));

		rebuildMembers();
	}

	private JPanel createToggleRow(String label, String tooltip, ToggleSwitch toggle, Consumer<Boolean> onChange)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, 0, 2, 0));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

		JLabel nameLabel = new JLabel(label);
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setToolTipText(tooltip);
		row.add(nameLabel, BorderLayout.WEST);

		toggle.addItemListener(e -> onChange.accept(toggle.isSelected()));
		row.add(toggle, BorderLayout.EAST);

		return row;
	}

	@Override
	public String getCardKey()
	{
		return "PARTY";
	}

	@Override
	public JPanel getToolbarButtons()
	{
		return toolbarButtons;
	}

	@Nullable
	@Override
	public JPanel getSubHeaderPanel()
	{
		return settingsPanel;
	}

	@Override
	public void onActivate()
	{
		sendToggle.setSelected(config.partySyncSend());
		recvToggle.setSelected(config.partySyncReceive());
		if (!config.partySyncSend() && !config.partySyncReceive())
		{
			settingsPanel.setVisible(true);
			settingsToggleButton.setActive(true);
		}
		rebuildMembers();
	}

	public void rebuildMembers()
	{
		membersContainer.removeAll();

		if (!partyInterface.isPartyPluginActive())
		{
			infoPanel.setContent("Party plugin disabled", "Enable the Party plugin to use Party Sync.");
			infoPanel.setVisible(true);
			contentPanel.setVisible(false);
		}
		else if (!partyInterface.isInParty())
		{
			infoPanel.setContent("Not in a party", "Use the Party plugin to join a party.");
			infoPanel.setVisible(true);
			contentPanel.setVisible(false);
		}
		else
		{
			var members = partyInterface.getMembers();
			if (members.isEmpty())
			{
				infoPanel.setContent("Party empty", "Invite others to join to use Party Sync.");
				infoPanel.setVisible(true);
				contentPanel.setVisible(false);
			}
			else
			{
				infoPanel.setVisible(false);
				contentPanel.setVisible(true);
				for (var member : members)
				{
					membersContainer.add(createMemberRow(member));
				}
			}
		}

		membersContainer.revalidate();
		membersContainer.repaint();
	}

	private JPanel createMemberRow(PartyInterface.PartyMemberInfo member)
	{
		JPanel section = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(4, 4, 4, 4)
		));

		JPanel headerRow = new JPanel(new BorderLayout(2, 0));
		headerRow.setOpaque(false);

		final boolean expanded = expandedMembers.contains(member.memberId);
		JButton expandButton = new JButton();
		ImageIcons.setExpandIcon(expandButton, expanded);
		expandButton.addActionListener(e -> {
			if (!expandedMembers.remove(member.memberId))
			{
				expandedMembers.add(member.memberId);
			}
			rebuildMembers();
		});
		headerRow.add(expandButton, BorderLayout.WEST);

		JLabel nameLabel = new JLabel(member.displayName);
		nameLabel.setForeground(member.hasGlamourer ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		headerRow.add(nameLabel, BorderLayout.CENTER);

		{
			boolean hidden = partyInterface.isMemberHidden(member.memberId);
			boolean canToggle = member.hasGlamourer && member.hasName();

			JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
			rightPanel.setOpaque(false);

			GlamourVisibility visibility = !member.hasGlamourer ? GlamourVisibility.DISABLED
				: hidden ? GlamourVisibility.HIDDEN : GlamourVisibility.VISIBLE;
			JLabel eyeLabel = new JLabel(ImageIcons.getVisibilityIcon(visibility));
			eyeLabel.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
			rightPanel.add(eyeLabel);

			ToggleSwitch toggle = new ToggleSwitch(canToggle && !hidden);
			if (canToggle)
			{
				toggle.addItemListener(e -> {
					boolean nowHidden = !toggle.isSelected();
					partyInterface.setMemberHidden(member.memberId, nowHidden);
					eyeLabel.setIcon(ImageIcons.getVisibilityIcon(
						nowHidden ? GlamourVisibility.HIDDEN : GlamourVisibility.VISIBLE));
				});
			}
			else
			{
				toggle.setEnabled(false);
				toggle.setToolTipText(!member.hasName() ? "Not Logged In" : "Sync Disabled");
			}
			rightPanel.add(toggle);

			headerRow.add(rightPanel, BorderLayout.EAST);
		}

		section.add(headerRow, BorderLayout.NORTH);

		if (expanded)
		{
			section.add(createMemberGlamours(member.memberId), BorderLayout.CENTER);
		}

		return section;
	}

	/// The member's synced glamours, one read-only row each: the glamoured icon and the item name.
	private JPanel createMemberGlamours(long memberId)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		list.setBorder(new EmptyBorder(4, 4, 0, 0));

		var glamours = partyInterface.getMemberGlamours(memberId);
		if (glamours.isEmpty())
		{
			JLabel empty = new JLabel("No synced glamours");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			list.add(empty);
			return list;
		}

		final float iconScale = config.iconScale() / 100f;
		for (Glamour glamour : glamours)
		{
			if (list.getComponentCount() > 0)
			{
				list.add(Box.createVerticalStrut(3));
			}

			JLabel itemName = new JLabel(glamour.getItemName());
			itemName.setForeground(Color.WHITE);

			JPanel row = new JPanel(new BorderLayout(5, 0));
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 3, 3, 3));

			JLabel icon = new JLabel();
			ImageIcons.setScaledIcon(icon, iconService.getIcon(glamour), iconScale);
			row.add(icon, BorderLayout.WEST);
			row.add(itemName, BorderLayout.CENTER);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			list.add(row);
		}
		return list;
	}

}

