		// Left: title, discord, party toggle
		JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		leftPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel titleLabel = new JLabel("Glamourer");
		titleLabel.setForeground(Color.WHITE);
		leftPanel.add(titleLabel);

		JButton discordButton = new JButton();
		ImageIcons.setDiscordIcon(discordButton);
		discordButton.setToolTipText("Join Discord");
		discordButton.addActionListener(e -> {
			try
			{
				LinkBrowser.browse("https://discord.gg/B6dD9R5U36");
			}
			catch (Exception ex)
			{
				log.warn("Failed to open Discord link", ex);
			}
		});
		leftPanel.add(discordButton);

		partyToggleButton = new ToggleButton();
		ImageIcons.setPartyIcon(partyToggleButton);
		partyToggleButton.setToolTipText("Party Sync");
		partyToggleButton.addActionListener(e -> {
			boolean toParty = activeSubPanel != partyPanel;
			partyToggleButton.setActive(toParty);
			activatePanel(toParty ? partyPanel : plateManagerPanel);
		});
		leftPanel.add(partyToggleButton);

		titlePanel.add(leftPanel, BorderLayout.WEST);

		// Right: slot for active panel's toolbar buttons
		toolbarSlot = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		toolbarSlot.setBackground(ColorScheme.DARK_GRAY_COLOR);
		titlePanel.add(toolbarSlot, BorderLayout.EAST);

		// Sub-header slot (for sliders, warnings, etc.)
		subHeaderSlot = new JPanel();
		subHeaderSlot.setLayout(new BoxLayout(subHeaderSlot, BoxLayout.Y_AXIS));

		// North: title bar + sub-header
		JPanel northPanel = new JPanel();
		northPanel.setLayout(new BoxLayout(northPanel, BoxLayout.Y_AXIS));
		northPanel.add(titlePanel);
		northPanel.add(subHeaderSlot);
		add(northPanel, BorderLayout.NORTH);

		// --- Content card layout ---
		contentCards = new CardLayout();
		contentPanel = new JPanel(contentCards);
		contentPanel.add(plateManagerPanel, plateManagerPanel.getCardKey());
		contentPanel.add(partyPanel, partyPanel.getCardKey());
		add(contentPanel, BorderLayout.CENTER);

		// Default: show plates
		activatePanel(plateManagerPanel);
	}

	public void onActivate()
	{
		activeSubPanel.onActivate();
	}

	private void activatePanel(GlamourerSubPanel panel)
	{
		activeSubPanel = panel;

		toolbarSlot.removeAll();
		subHeaderSlot.removeAll();

		var toolbar = panel.getToolbarButtons();
		if (toolbar != null)
		{
			toolbarSlot.add(toolbar);
		}
		var subHeader = panel.getSubHeaderPanel();
		if (subHeader != null)
		{
			subHeaderSlot.add(subHeader);
		}

		contentCards.show(contentPanel, panel.getCardKey());
		panel.onActivate();

		toolbarSlot.revalidate();
		toolbarSlot.repaint();
		subHeaderSlot.revalidate();
		subHeaderSlot.repaint();
	}

	public void showError(Exception ex)
	{
		partyToggleButton.setVisible(false);
		if (activeExceptionPanel != null)
		{
			contentPanel.remove(activeExceptionPanel);
		}
		activeExceptionPanel = new ExceptionPanel(ex);
		contentPanel.add(activeExceptionPanel, activeExceptionPanel.getCardKey());
		activatePanel(activeExceptionPanel);
	}
}

package io.huze.glamourer.ui;

import java.awt.Graphics;
import java.awt.Insets;
import javax.swing.Icon;
import javax.swing.JButton;
import net.runelite.client.ui.ColorScheme;

/// This class is purely visual; it's a regular button with internal state that shows whether it's active or not.
/// State should be maintained somewhere else.
public class ToggleButton extends JButton
{
	@Override
	protected void paintComponent(Graphics g)
	{
		if (Boolean.TRUE.equals(getClientProperty("active")))
		{
			g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
			g.fillRect(0, 0, getWidth(), getHeight());
		}
		Icon icon = getModel().isRollover() && getRolloverIcon() != null ? getRolloverIcon() : getIcon();
		if (icon != null)
		{
			Insets insets = getInsets();
			icon.paintIcon(this, g,
				insets.left + (getWidth() - insets.left - insets.right - icon.getIconWidth()) / 2,
				insets.top + (getHeight() - insets.top - insets.bottom - icon.getIconHeight()) / 2);
		}
	}

	public void setActive(boolean active)
	{
		putClientProperty("active", active);
		repaint();
	}
}

