@Singleton
public class StackVariantSheet extends Sheet<int[]>
{
	private volatile Map<Integer, Set<Integer>> variantsByItemId = Collections.emptyMap();

	public StackVariantSheet()
	{
		super("stack_variant_sheet.csv", new String[]{"id", "variantId"},
			cols -> new int[]{Integer.parseInt(cols[0]), Integer.parseInt(cols[1])});
	}

	public Set<Integer> getVariants(int itemId)
	{
		return variantsByItemId.getOrDefault(itemId, Collections.emptySet());
	}

	@Override
	protected void load(List<int[]> rows)
	{
		Map<Integer, Set<Integer>> map = new HashMap<>();
		for (int[] row : rows)
		{
			map.computeIfAbsent(row[0], k -> new HashSet<>()).add(row[1]);
		}
		this.variantsByItemId = map;
	}
}

package io.huze.glamourer.item;

import io.huze.glamourer.Extensions;
import java.util.regex.Pattern;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.experimental.ExtensionMethod;
import net.runelite.api.ItemComposition;

@AllArgsConstructor(access = AccessLevel.PRIVATE)
@ExtensionMethod({Extensions.class})
public class DedupeKey implements Comparable<DedupeKey>
{
	String strippedName;
	int modelId;
	short[] colorReplace;
	short[] textureReplace;

	public static String fromComponents(String membersName, int modelId, short[] colorReplace, short[] textureReplace)
	{
		return new DedupeKey(
			stripName(membersName),
			similarModelId(modelId),
			colorReplace,
			textureReplace).toString();
	}

	public static String of(ItemComposition itemComposition)
	{
		return fromComponents(
			itemComposition.getMembersName(),
			similarModelId(itemComposition.getInventoryModel()),
			itemComposition.getColorToReplaceWith(),
			itemComposition.getTextureToReplaceWith());
	}

	@Override
	public int compareTo(DedupeKey o)
	{
		return Integer.compare(modelId, o.modelId);
	}

	@Override
	public String toString()
	{
		return String.format("%s:%d:%s:%s",
			strippedName,
			modelId,
			colorReplace.toHex(),
			textureReplace.toHex());
	}

	private static final Pattern PAREN_REPLACE = Pattern.compile("\\(.*\\)");

	private static String stripName(String name)
	{
		String noParens = PAREN_REPLACE.matcher(name).replaceAll("");
		return noParens.replaceAll("[^A-Za-z]+", "");
	}

	private static int similarModelId(int modelId)
	{
		switch (modelId)
		{
			// Normal
			case 2621:
			case 2384:
			case 2697:
				return 2789;
			// Divine
			case 37966:
			case 37975:
			case 37944:
				return 37951;
			// CoX
			case 32768:
			case 32766:
			case 32772:
				return 32527;
			// Barb Mix
			case 26825:
				return 26826;
		}
		return modelId;
	}
}

