import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class DedupeItemManager
{
	private final ItemManager itemManager;
	private final Client client;
	private final StackVariantSheet stackVariantSheet;
	private final Map<String, Integer> dedupeKeyToBestItemMap = new HashMap<>();
	private final Map<Integer, DedupeItemComposition> dedupeMap = new HashMap<>();

	@Nonnull
	public DedupeItemComposition getItemComposition(int itemId)
	{
		var comp = dedupeMap.get(itemId);
		return comp != null ? comp : new DedupeItemCompositionImpl(itemManager, itemId, null);
	}

	@Nullable
	public DedupeItemComposition getItemComposition(@Nonnull String dedupeKey)
	{
		var itemId = dedupeKeyToBestItemMap.get(dedupeKey);
		if (itemId == null)
		{
			return null;
		}
		return getItemComposition(itemId);
	}

	public ItemComposition getItemDefinition(int itemId)
	{
		return client.getItemDefinition(itemId);
	}

	@Nullable
	public String findKeyIgnoreCase(@Nonnull String dedupeKey)
	{
		for (String key : dedupeKeyToBestItemMap.keySet())
		{
			if (key.equalsIgnoreCase(dedupeKey))
			{
				return key;
			}
		}
		return null;
	}

	public Set<Integer> getMatchingItemIdsForCorruptKey(String dedupeKey)
	{
		var split = dedupeKey.split(":");
		if (split.length < 2)
		{
			return Collections.emptySet();
		}
		var keyPrefix = split[0] + ":" + split[1] + ":";
		return dedupeKeyToBestItemMap.entrySet().stream()
			// Ignore case so a re-cased item name finds repair candidates.
			.filter(entry -> entry.getKey().regionMatches(true, 0, keyPrefix, 0, keyPrefix.length()))
			.map(Map.Entry::getValue)
			.collect(Collectors.toSet());
	}

	public boolean isEquippable(int itemId)
	{
		var stats = itemManager.getItemStats(itemId);
		return stats != null && stats.isEquipable();
	}

	private boolean filterItem(ItemComposition itemComposition)
	{
		var name = itemComposition.getMembersName();
		return itemComposition.getNote() != -1 ||
			itemComposition.getPlaceholderTemplateId() != -1 ||
			name == null ||
			name.isBlank() ||
			name.equalsIgnoreCase("null");
	}

	public int canonicalize(int id)
	{
		return itemManager.canonicalize(id);
	}

	public AsyncBufferedImage getImage(int id)
	{
		return itemManager.getImage(id);
	}

	private static class DupeItem
	{
		ItemComposition best;
		Set<Integer> dupeIds;

		DupeItem(ItemComposition composition)
		{
			best = composition;
			dupeIds = new HashSet<>();
		}

		void add(ItemComposition item)
		{
			dupeIds.add(item.getId());
			var name = item.getMembersName();
			var bestName = best.getMembersName();
			var nameIsShorter = name.length() < bestName.length();
			var nameIsGreater = name.length() == bestName.length() && name.compareTo(bestName) > 0;
			if (nameIsShorter || nameIsGreater)
			{
				best = item;
			}
		}
	}

	private boolean initialized;

	public void initializeOnClientThread()
	{
		if (initialized)
		{
			return;
		}
		long startTime = System.nanoTime();
		Map<String, DupeItem> dupeItemMap = new HashMap<>();
		for (int i = 0; i < client.getItemCount(); i++)
		{
			var itemComposition = itemManager.getItemComposition(i);
			if (filterItem(itemComposition))
			{
				continue;
			}
			var key = DedupeKey.of(itemComposition);
			dupeItemMap.computeIfAbsent(key, k -> new DupeItem(itemComposition)).add(itemComposition);
		}

		dedupeMap.clear();
		dedupeKeyToBestItemMap.clear();
		for (var dupeEntry : dupeItemMap.values())
		{
			var bestId = dupeEntry.best.getId();
			dedupeKeyToBestItemMap.put(DedupeKey.of(dupeEntry.best), bestId);
			var dupeIds = dupeEntry.dupeIds;

			Set<Integer> variantIds = new HashSet<>();
			for (int dupeId : dupeIds)
			{
				variantIds.addAll(stackVariantSheet.getVariants(dupeId));
			}
			dupeIds.addAll(variantIds);

			if (dupeIds.size() > 1)
			{
				for (var itemId : dupeIds)
				{
					dedupeMap.put(itemId, new DedupeItemCompositionImpl(itemManager, bestId, dupeIds));
				}
			}
		}
		initialized = true;
		log.debug("DedupeItemManager initialization took {}ms", (System.nanoTime() - startTime) / 1_000_000);
	}
}

package io.huze.glamourer.item;

import java.util.Collection;

public interface DedupeItemComposition
{
	int getId();

	Collection<Integer> getIds();

	String getMembersName();
}

package io.huze.glamourer.item;

import io.huze.glamourer.Extensions;
import java.util.Arrays;
import java.util.Collection;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

@Slf4j
@ExtensionMethod({Extensions.class})
public class DedupeItemCompositionImpl implements DedupeItemComposition
{
	private final ItemComposition delegate;
	private final int[] duplicates;

	DedupeItemCompositionImpl(ItemManager manager, int bestId, Set<Integer> duplicateItems)
	{
		if (duplicateItems == null || duplicateItems.isEmpty())
		{
			duplicateItems = Set.of(bestId);
		}
		duplicates = duplicateItems.toIntArray();
		try
		{
			this.delegate = manager.getItemComposition(bestId);
		}
		catch (Exception e)
		{
			log.error("Error loading delegate: {} {} {}", bestId, duplicateItems, e.getMessage());
			throw e;
		}
	}

	@Override
	public String getMembersName()
	{
		return delegate.getMembersName();
	}

	public Collection<Integer> getIds()
	{
		return Arrays.stream(duplicates)
			.boxed()
			.collect(Collectors.toList());
	}

	@Override
	public int getId()
	{
		return delegate.getId();
	}
}

package io.huze.glamourer.item;

import io.huze.glamourer.CsvLoader;
import io.huze.glamourer.Sheet;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;

@Singleton
public class PetSheet extends Sheet<PetSheet.Row>
{
	@Getter
	private volatile Map<Integer, List<Integer>> npcsByItemId = Collections.emptyMap();
	private volatile Map<Integer, Integer> itemByNpcId = Collections.emptyMap();
	private volatile Map<Integer, List<Integer>> npcModelsByItemId = Collections.emptyMap();

	public PetSheet()
	{
		super("pet_sheet.csv", new String[]{"item_id", "npc_ids", "npc_models"}, PetSheet::parseRow);
	}

	public List<Integer> getNpcIds(int itemId)
	{
		return npcsByItemId.getOrDefault(itemId, Collections.emptyList());
	}

	public int getItemId(int npcId)
	{
		return itemByNpcId.getOrDefault(npcId, -1);
	}

	public List<Integer> getNpcModelIds(int itemId)
	{
		return npcModelsByItemId.getOrDefault(itemId, Collections.emptyList());
	}

	@Override
	protected void load(List<Row> rows)
	{
		Map<Integer, List<Integer>> npcs = new HashMap<>();
		Map<Integer, Integer> item = new HashMap<>();
		Map<Integer, List<Integer>> models = new HashMap<>();
		for (Row row : rows)
		{
			npcs.put(row.itemId, row.npcIds);
			for (int npcId : row.npcIds)
			{
				item.put(npcId, row.itemId);
			}
			if (!row.npcModels.isEmpty())
			{
				models.put(row.itemId, row.npcModels);
			}
		}
		this.npcsByItemId = Collections.unmodifiableMap(npcs);
		this.itemByNpcId = Collections.unmodifiableMap(item);
		this.npcModelsByItemId = Collections.unmodifiableMap(models);
	}

	private static Row parseRow(String[] cols)
	{
		return new Row(Integer.parseInt(cols[0]),
			CsvLoader.parseList(cols[1], Integer::parseInt),
			CsvLoader.parseList(cols[2], Integer::parseInt));
	}

	static final class Row
	{
		private final int itemId;
		private final List<Integer> npcIds;
		private final List<Integer> npcModels;

		Row(int itemId, List<Integer> npcIds, List<Integer> npcModels)
		{
			this.itemId = itemId;
			this.npcIds = npcIds;
			this.npcModels = npcModels;
		}
	}
}

package io.huze.glamourer.item;

import io.huze.glamourer.Sheet;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ModelData;

@Singleton
public class ItemSheet extends Sheet<ItemRow>
{
	private static final String[] CSV_HEADERS = {"id", "release_date", "removal_date", "quest", "category", "male_model0", "male_model1", "male_model2", "female_model0", "female_model1", "female_model2"};

	private final Client client;
	private final PetSheet petSheet;

	private volatile Map<Integer, ItemRow> itemsById = Map.of();
	@Getter
	private volatile Set<Integer> removedItemIds = Set.of();
	@Getter
	private volatile Set<Integer> questItemIds = Set.of();
	@Getter
	private volatile Set<Integer> uncommonItemIds = Set.of();

	@Inject
	public ItemSheet(Client client, PetSheet petSheet)
	{
		super("item_sheet.csv", CSV_HEADERS, ItemRow::fromCsvColumns);
		this.client = client;
		this.petSheet = petSheet;
	}

	@Nonnull
	public Collection<ModelData> getModels(@Nonnull Collection<ItemComposition> itemCompositions)
	{
		var inventoryModelIds = new HashSet<Integer>();
		var otherModelIds = new HashSet<Integer>();
		for (var itemComposition : itemCompositions)
		{
			final var itemId = itemComposition.getId();
			inventoryModelIds.add(itemComposition.getInventoryModel());
			otherModelIds.addAll(petSheet.getNpcModelIds(itemId));
			var row = getItemById(itemId);
			if (row != null)
			{
				for (int modelId : new int[]{
					row.getMaleModel0(), row.getMaleModel1(), row.getMaleModel2(),
					row.getFemaleModel0(), row.getFemaleModel1(), row.getFemaleModel2()})
				{
					if (modelId > 0)
					{
						otherModelIds.add(modelId);
					}
				}
			}
		}

		var modelList = new ArrayList<ModelData>();
		for (int modelId : inventoryModelIds)
		{
			var modelData = client.loadModelData(modelId);
			if (modelData == null)
			{
				throw new IllegalStateException("Failed to load inventory model " + modelId);
			}
			modelList.add(modelData);
		}
		otherModelIds.removeAll(inventoryModelIds);
		for (int modelId : otherModelIds)
		{
			var modelData = client.loadModelData(modelId);
			if (modelData != null)
			{
				modelList.add(modelData);
			}
		}
		return modelList;
	}

	@Nullable
	public ItemRow getItemById(int itemId)
	{
		return itemsById.get(itemId);
	}

	@Override
	protected void load(List<ItemRow> items)
	{
		this.itemsById = items.stream()
			.collect(Collectors.toMap(ItemRow::getId, Function.identity()));
		this.removedItemIds = items.stream()
			.filter(ItemRow::isRemoved)
			.map(ItemRow::getId)
			.collect(Collectors.toSet());
		this.questItemIds = items.stream()
			.filter(ItemRow::isQuest)
			.map(ItemRow::getId)
			.collect(Collectors.toSet());
		this.uncommonItemIds = items.stream()
			.filter(ItemRow::isUncommon)
			.map(ItemRow::getId)
			.collect(Collectors.toSet());
	}
}

