package io.huze.glamourer.color;

import java.awt.Color;
import javax.annotation.Nonnull;
import net.runelite.api.JagexColor;
import static net.runelite.api.JagexColor.packHSL;
import static net.runelite.api.JagexColor.unpackHue;
import static net.runelite.api.JagexColor.unpackLuminance;
import static net.runelite.api.JagexColor.unpackSaturation;

public class Colors
{
	// Inclusive max ints
	public static final int MAX_HUE = JagexColor.HUE_MAX;
	public static final int MAX_SAT = JagexColor.SATURATION_MAX;
	public static final int MAX_LUM = JagexColor.LUMINANCE_MAX;
	// Exclusive max doubles
	private static final double MAX_HUE_D = MAX_HUE + 1;
	private static final double MAX_SAT_D = MAX_SAT + 1;
	private static final double MAX_LUM_D = MAX_LUM + 1;
	// Model lighting clamps face brightness to this range
	private static final int MIN_BRIGHTNESS = 2;
	private static final int MAX_BRIGHTNESS = 126;

	private static final double HUE_OFFSET = (.5D / MAX_HUE_D);
	private static final double SATURATION_OFFSET = (.5D / MAX_SAT_D);
	private static final double HUE_CONE_COUNT = 6;

	public static String formatHSL(short hsl)
	{
		return String.format("%dH/%dS/%dL", unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl));
	}

	public static Color hslToColor(short hsl)
	{
		return hslToColor(unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl));
	}

	public static Color hslToColor(int hue, int sat, int lum)
	{
		double h = (hue / MAX_HUE_D + HUE_OFFSET) * HUE_CONE_COUNT;
		double s = (double) sat / MAX_SAT_D + SATURATION_OFFSET;
		double l = (double) lum / MAX_LUM_D;

		double chroma = (1D - Math.abs(2D * l - 1D)) * s;
		double x = chroma * (1D - Math.abs(h % 2D - 1D));
		double lightness = l - (chroma / 2D);

		double r = lightness, g = lightness, b = lightness;
		switch ((int) h)
		{
			case 0:
				r += chroma;
				g += x;
				break;
			case 1:
				g += chroma;
				r += x;
				break;
			case 2:
				g += chroma;
				b += x;
				break;
			case 3:
				b += chroma;
				g += x;
				break;
			case 4:
				b += chroma;
				r += x;
				break;
			default:
				r += chroma;
				b += x;
				break;
		}
		return new Color((int) (r * 256D), (int) (g * 256D), (int) (b * 256D));
	}

	public static void hslToShadedColors(short hsl, Color[] out)
	{
		hslToShadedColors(unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl), out);
	}

	public static void hslToShadedColors(int hue, int sat, int lum, Color[] out)
	{
		int steps = out.length;
		if (steps == 1)
		{
			out[0] = hslToShadedColor(hue, sat, lum);
			return;
		}
		for (int i = 0; i < steps; i++)
		{
			int brightness = MIN_BRIGHTNESS + (i * (MAX_BRIGHTNESS - MIN_BRIGHTNESS)) / (steps - 1);
			int effectiveLum = lum * brightness / 128;
			out[i] = hslToColor(hue, sat, effectiveLum);
		}
	}

	public static Color hslToShadedColor(short hsl)
	{
		return hslToShadedColor(unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl));
	}

	public static Color hslToShadedColor(int hue, int sat, int lum)
	{
		int medianBrightness = (MIN_BRIGHTNESS + MAX_BRIGHTNESS) / 2;
		return hslToColor(hue, sat, lum * medianBrightness / 128);
	}

	/// Generate a highlighted color for the provided HSL color.
	/// Highlighted colors retain the hue of the input color for better lerping.
	public static short highlight(short hsl)
	{
		return packHSL(unpackHue(hsl), 0, MAX_LUM);
	}

	/// Generate a darkened color for the provided HSL color.
	/// Darkened colors retain the hue of the input color for better lerping.
	public static short darken(short hsl)
	{
		return packHSL(unpackHue(hsl), 0, 0);
	}

	public static short lerpHsl(short start, short end, float t)
	{
		int hue = lerp(unpackHue(start), unpackHue(end), t);
		int sat = lerp(unpackSaturation(start), unpackSaturation(end), t);
		int lum = lerp(unpackLuminance(start), unpackLuminance(end), t);
		return packHSL(hue, sat, lum);
	}

	static int lerp(int start, int end, float t)
	{
		return start + Math.round((end - start) * t);
	}

	/**
	 * Nudge replace values to prevent sequential replacement from chaining.
	 * If replace[i] == find[j] for j > i, the engine applies both replacements to the same face.
	 * Identity replacements (find[j] == replace[j]) are skipped since they cause no visual change.
	 * <p>
	 * When a chain is detected, the nearest non-chaining color is found by searching outward
	 * from the original value: luminance ±1, ±2, ..., then saturation ±1, ±2, ..., then hue.
	 */
	public static void breakColorChains(@Nonnull short[] find, @Nonnull short[] replace)
	{
		assert find.length == replace.length;
		for (int i = 0; i < find.length; i++)
		{
			if (chainsForward(find, replace, i, replace[i]))
			{
				replace[i] = findNearestNonChaining(find, replace, i);
			}
		}
	}

	private static final int[] NUDGE_DIRECTIONS = {1, -1};
	private static final int HUE_SCALE = (MAX_LUM + 1) / (MAX_HUE + 1);
	private static final int SAT_SCALE = (MAX_LUM + 1) / (MAX_SAT + 1);

	private static short findNearestNonChaining(short[] find, short[] replace, int i)
	{
		final var original = replace[i];
		final var h = unpackHue(original);
		final var s = unpackSaturation(original);
		final var l = unpackLuminance(original);

		for (int d = 1; d <= MAX_LUM; d++)
		{
			for (int dir : NUDGE_DIRECTIONS)
			{
				int newL = l + d * dir;
				if (newL >= 0 && newL <= MAX_LUM)
				{
					short candidate = packHSL(h, s, newL);
					if (!chainsForward(find, replace, i, candidate))
					{
						return candidate;
					}
				}
			}

			if (d % HUE_SCALE == 0)
			{
				int hueOffset = d / HUE_SCALE;
				for (int dir : NUDGE_DIRECTIONS)
				{
					int newH = Math.floorMod(h + hueOffset * dir, MAX_HUE + 1);
					short candidate = packHSL(newH, s, l);
					if (!chainsForward(find, replace, i, candidate))
					{
						return candidate;
					}
				}
			}

			if (d % SAT_SCALE == 0)
			{
				int satOffset = d / SAT_SCALE;
				for (int dir : NUDGE_DIRECTIONS)
				{
					int newS = s + satOffset * dir;
					if (newS >= 0 && newS <= MAX_SAT)
					{
						short candidate = packHSL(h, newS, l);
						if (!chainsForward(find, replace, i, candidate))
						{
							return candidate;
						}
					}
				}
			}
		}

		return original;
	}

	private static boolean chainsForward(short[] find, short[] replace, int i, short value)
	{
		for (int j = i + 1; j < find.length; j++)
		{
			if (find[j] != replace[j] && value == find[j])
			{
				return true;
			}
		}
		return false;
	}
}

package io.huze.glamourer.color;

import lombok.Value;

@Value
public class ColorGroupSettings
{
	double maxHueDist; // 0.0-1.0 (0 = identical hue only, 1 = any hue)
	double maxSatDist; // 0.0-1.0
	double maxLumDist; // 0.0-1.0
	boolean separateGrayscale;

	public static final ColorGroupSettings DEFAULT = new ColorGroupSettings(0.04, 0.4, 0.08, true);
}

package io.huze.glamourer.color;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import net.runelite.api.JagexColor;

public class ColorGroup
{
	private static final short SKIN_COLOR = 4550;
	private static final short HAIR_COLOR = 6798;
	private static final short EYE_COLOR = 0;
	// Anchor is the first color added (used for offset calculations)
	private final int anchorHue;
	private final int anchorSat;
	private final int anchorLum;
	private final ColorGroupSettings settings;

	// Indices into the glamour's color array
	@Getter
	private final List<Integer> colorIndices = new ArrayList<>();

	// Each color's [hDelta, sDelta, lDelta] offset from anchor (based on original colors)
	@Getter
	private final List<int[]> offsets = new ArrayList<>();

	// All original HSL values in this group (for checking if new colors can join)
	private final List<short[]> originalHslValues = new ArrayList<>();

	private ColorGroup(short anchorHsl, ColorGroupSettings settings)
	{
		this.anchorHue = JagexColor.unpackHue(anchorHsl);
		this.anchorSat = JagexColor.unpackSaturation(anchorHsl);
		this.anchorLum = JagexColor.unpackLuminance(anchorHsl);
		this.settings = settings;
	}

	private void addColor(int index, short originalHsl)
	{
		int h = JagexColor.unpackHue(originalHsl);
		int s = JagexColor.unpackSaturation(originalHsl);
		int l = JagexColor.unpackLuminance(originalHsl);

		colorIndices.add(index);
		offsets.add(new int[]{h - anchorHue, s - anchorSat, l - anchorLum});
		originalHslValues.add(new short[]{(short) h, (short) s, (short) l});
	}

	// When grays are separated, saturated colors get a more generous luminance threshold
	// since grays are already excluded and color ramps (same hue, varying luminance) should group together
	private static final double SATURATED_LUM_BOOST = 3.0;

	private boolean areGroupable(int h1, int s1, int l1, int h2, int s2, int l2)
	{
		if (settings.isSeparateGrayscale() && (s1 == 0) != (s2 == 0))
		{
			return false;
		}
		double hDiff = Math.abs(h1 - h2) / 64.0;
		hDiff = Math.min(hDiff, 1.0 - hDiff); // circular
		double sDiff = Math.abs(s1 - s2) / 8.0;
		double lDiff = Math.abs(l1 - l2) / 128.0;
		double maxLum = settings.getMaxLumDist();
		if (settings.isSeparateGrayscale() && s1 > 0 && s2 > 0)
		{
			maxLum = Math.min(maxLum * SATURATED_LUM_BOOST, 1.0);
		}
		return hDiff <= settings.getMaxHueDist()
			&& sDiff <= settings.getMaxSatDist()
			&& lDiff <= maxLum;
	}

	private boolean canGroup(short hsl)
	{
		if (hsl == SKIN_COLOR || containsSkinColor())
		{
			return false;
		}

		int h = JagexColor.unpackHue(hsl);
		int s = JagexColor.unpackSaturation(hsl);
		int l = JagexColor.unpackLuminance(hsl);

		for (short[] existing : originalHslValues)
		{
			if (areGroupable(h, s, l, existing[0], existing[1], existing[2]))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isGray()
	{
		return !originalHslValues.isEmpty() && originalHslValues.get(0)[1] == 0;
	}

	private boolean containsSkinColor()
	{
		for (short[] hsl : originalHslValues)
		{
			if (JagexColor.packHSL(hsl[0], hsl[1], hsl[2]) == SKIN_COLOR)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Checks if the replacement colors still maintain the expected relative offsets.
	 * If any color has been individually edited to break the pattern, returns false.
	 *
	 * @param pairs The color pairs to check
	 * @return true if replacements are coherent (maintain same relative offsets), false otherwise
	 */
	public boolean areReplacementsCoherent(List<ColorReplacement> pairs)
	{
		if (colorIndices.size() <= 1)
		{
			return true;
		}

		// Get the first replacement color as reference
		ColorReplacement firstPair = pairs.get(colorIndices.get(0));
		int refH = JagexColor.unpackHue(firstPair.getReplacement());
		int refS = JagexColor.unpackSaturation(firstPair.getReplacement());
		int refL = JagexColor.unpackLuminance(firstPair.getReplacement());

		// Check if all other colors maintain the same relative offsets
		for (int i = 1; i < colorIndices.size(); i++)
		{
			int colorIdx = colorIndices.get(i);
			int[] expectedOffset = offsets.get(i);

			ColorReplacement pair = pairs.get(colorIdx);
			int actualH = JagexColor.unpackHue(pair.getReplacement());
			int actualS = JagexColor.unpackSaturation(pair.getReplacement());
			int actualL = JagexColor.unpackLuminance(pair.getReplacement());

			// Calculate expected values based on first replacement + original offset
			// Hue wraps around (circular), sat/lum clamp
			int expectedH = ((refH + expectedOffset[0]) % 64 + 64) % 64;
			int expectedS = clamp(refS + expectedOffset[1], 0, 7);
			int expectedL = clamp(refL + expectedOffset[2], 0, 127);

			// Allow small tolerance for clamping/rounding effects
			// For hue, also check wrapped distance (e.g., 0 and 63 are close)
			int hueDiff = Math.abs(actualH - expectedH);
			int wrappedHueDiff = 64 - hueDiff;
			if (Math.min(hueDiff, wrappedHueDiff) > 1 ||
				Math.abs(actualS - expectedS) > 0 ||
				Math.abs(actualL - expectedL) > 1)
			{
				return false;
			}
		}

		return true;
	}

	public static List<ColorGroup> groupColors(List<ColorReplacement> pairs, ColorGroupSettings settings)
	{
		List<ColorGroup> groups = assignToInitialGroups(pairs, settings);
		mergeConnectedGroups(groups);
		finalizeGroups(groups);
		return groups;
	}

	private static List<ColorGroup> assignToInitialGroups(List<ColorReplacement> pairs, ColorGroupSettings settings)
	{
		List<ColorGroup> groups = new ArrayList<>();
		int index = 0;

		for (ColorReplacement pair : pairs)
		{
			short originalHsl = pair.getOriginal();
			ColorGroup matchingGroup = findMatchingGroup(groups, originalHsl);

			if (matchingGroup != null)
			{
				matchingGroup.addColor(index, originalHsl);
			}
			else
			{
				ColorGroup newGroup = new ColorGroup(originalHsl, settings);
				newGroup.addColor(index, originalHsl);
				groups.add(newGroup);
			}
			index++;
		}
		return groups;
	}

	private static ColorGroup findMatchingGroup(List<ColorGroup> groups, short hsl)
	{
		for (ColorGroup group : groups)
		{
			if (group.canGroup(hsl))
			{
				return group;
			}
		}
		return null;
	}

	private static void mergeConnectedGroups(List<ColorGroup> groups)
	{
		boolean merged;
		do
		{
			merged = tryMergeOnePair(groups);
		} while (merged);
	}

	private static boolean tryMergeOnePair(List<ColorGroup> groups)
	{
		for (int i = 0; i < groups.size(); i++)
		{
			for (int j = i + 1; j < groups.size(); j++)
			{
				if (groups.get(i).shouldMergeWith(groups.get(j)))
				{
					groups.get(i).mergeFrom(groups.get(j));
					groups.remove(j);
					return true;
				}
			}
		}
		return false;
	}

	private static void finalizeGroups(List<ColorGroup> groups)
	{
		for (ColorGroup group : groups)
		{
			group.sortByLuminance();
		}
		groups.sort((a, b) -> {
			int aOrder = a.containsSkinColor() ? 2 : a.isGray() ? 1 : 0;
			int bOrder = b.containsSkinColor() ? 2 : b.isGray() ? 1 : 0;
			if (aOrder != bOrder)
			{
				return Integer.compare(aOrder, bOrder);
			}
			if (aOrder == 1)
			{
				// Grays: sort by luminance descending (brighter first)
				return Short.compare(b.originalHslValues.get(0)[2], a.originalHslValues.get(0)[2]);
			}
			return Short.compare(a.originalHslValues.get(0)[0], b.originalHslValues.get(0)[0]);
		});
	}

	/**
	 * Checks if this group should be merged with another group.
	 * Returns true if any color in this group is within threshold of any color in the other group.
	 */
	private boolean shouldMergeWith(ColorGroup other)
	{
		if (containsSkinColor() || other.containsSkinColor())
		{
			return false;
		}
		for (short[] myHsl : originalHslValues)
		{
			for (short[] otherHsl : other.originalHslValues)
			{
				if (areGroupable(myHsl[0], myHsl[1], myHsl[2],
					otherHsl[0], otherHsl[1], otherHsl[2]))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Merges all colors from another group into this group.
	 */
	private void mergeFrom(ColorGroup other)
	{
		colorIndices.addAll(other.colorIndices);
		offsets.addAll(other.offsets);
		originalHslValues.addAll(other.originalHslValues);
	}

	/**
	 * Sorts the colors in this group by luminance (brightest first).
	 * Recalculates offsets relative to the new first color.
	 */
	private void sortByLuminance()
	{
		if (colorIndices.size() <= 1)
		{
			return;
		}

		Integer[] sortOrder = createLuminanceSortOrder();
		reorderBySortOrder(sortOrder);
		recalculateOffsets();
	}

	private Integer[] createLuminanceSortOrder()
	{
		Integer[] sortOrder = new Integer[colorIndices.size()];
		for (int i = 0; i < sortOrder.length; i++)
		{
			sortOrder[i] = i;
		}

		java.util.Arrays.sort(sortOrder, (a, b) -> {
			short[] hslA = originalHslValues.get(a);
			short[] hslB = originalHslValues.get(b);
			int cmp = Short.compare(hslB[2], hslA[2]); // Luminance descending
			if (cmp != 0) return cmp;
			cmp = Short.compare(hslA[0], hslB[0]); // Hue ascending
			if (cmp != 0) return cmp;
			return Short.compare(hslA[1], hslB[1]); // Saturation ascending
		});

		return sortOrder;
	}

	private void reorderBySortOrder(Integer[] sortOrder)
	{
		List<Integer> newColorIndices = new ArrayList<>();
		List<int[]> newOffsets = new ArrayList<>();
		List<short[]> newOriginalHslValues = new ArrayList<>();

		for (int i : sortOrder)
		{
			newColorIndices.add(colorIndices.get(i));
			newOffsets.add(offsets.get(i));
			newOriginalHslValues.add(originalHslValues.get(i));
		}

		colorIndices.clear();
		colorIndices.addAll(newColorIndices);
		offsets.clear();
		offsets.addAll(newOffsets);
		originalHslValues.clear();
		originalHslValues.addAll(newOriginalHslValues);
	}

	private void recalculateOffsets()
	{
		short[] newAnchor = originalHslValues.get(0);
		for (int i = 0; i < offsets.size(); i++)
		{
			short[] hsl = originalHslValues.get(i);
			offsets.set(i, new int[]{hsl[0] - newAnchor[0], hsl[1] - newAnchor[1], hsl[2] - newAnchor[2]});
		}
	}

	/**
	 * Calculates the new HSL value for a color in this group when the anchor color changes.
	 *
	 * @param newAnchorHsl The new HSL value for the anchor (from user selection)
	 * @param offsetIndex  Index into the offsets list for the specific color
	 * @return Adjusted HSL value for the color (hue wraps, sat/lum clamp)
	 */
	public short calculateNewColor(short newAnchorHsl, int offsetIndex)
	{
		int newH = JagexColor.unpackHue(newAnchorHsl);
		int newS = JagexColor.unpackSaturation(newAnchorHsl);
		int newL = JagexColor.unpackLuminance(newAnchorHsl);

		int[] offset = offsets.get(offsetIndex);
		int finalH = ((newH + offset[0]) % 64 + 64) % 64;
		int finalS = clamp(newS + offset[1], 0, 7);
		int finalL = clamp(newL + offset[2], 0, 127);

		return JagexColor.packHSL(finalH, finalS, finalL);
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package io.huze.glamourer.party;

import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.plate.GlamourBinaryCodec;
import java.io.IOException;
import java.util.List;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import net.runelite.client.party.messages.PartyMemberMessage;

@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class GlamourMessage extends PartyMemberMessage
{
	final boolean patch;
	final byte[] data;

	static GlamourMessage revokeAll() throws IOException
	{
		return update(List.of());
	}

	static GlamourMessage update(List<GlamourData> glamours) throws IOException
	{
		return new GlamourMessage(false, GlamourBinaryCodec.encodeList(glamours));
	}

	static GlamourMessage patch(List<GlamourData> glamours) throws IOException
	{
		return new GlamourMessage(true, GlamourBinaryCodec.encodeList(glamours));
	}
}

package io.huze.glamourer.party;

import io.huze.glamourer.Config;
import io.huze.glamourer.Extensions;
import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.glam.GlamourEngine;
import io.huze.glamourer.item.DedupeItemManager;
import io.huze.glamourer.item.PetSheet;
import io.huze.glamourer.npc.FollowerChanged;
import io.huze.glamourer.npc.FollowerTracker;
import io.huze.glamourer.npc.PetGlamourSync;
import io.huze.glamourer.plate.GlamourBinaryCodec;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.party.messages.UserSync;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.party.PartyPlugin;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
@ExtensionMethod({Extensions.class})
public class PartyInterface
{
	private static final String UNKNOWN_NAME = "<unknown>";
	@Inject
	Client client;
	@Inject
	PartyService partyService;
	@Inject
	WSClient wsClient;
	@Inject
	ClientThread clientThread;
	@Inject
	GlamourEngine glamourEngine;
	@Inject
	DedupeItemManager ddItemManager;
	@Inject
	Config config;
	@Inject
	PlayerBlacklist blacklist;
	@Inject
	PluginManager pluginManager;
	@Inject
	PetSheet petSheet;
	@Inject
	PetGlamourSync petGlamourSync;
	@Inject
	FollowerTracker followerTracker;

	private final Map<Long, PartyMember> partyMembers = new ConcurrentHashMap<>();
	/// Client thread only.
	private int lastSentFollowerIndex = -1;
	private Set<Integer> syncedItemIds = new HashSet<>();
	private volatile boolean isStarted;
	private volatile boolean updateQueued;

	@Setter
	@Nonnull
	private Runnable onStateChanged = () -> {};

	// --- Data classes ---

	@RequiredArgsConstructor
	public static final class PartyMemberInfo
	{
		public final long memberId;
		@Nonnull
		public final String displayName;
		public final boolean hasGlamourer;

		public boolean hasName()
		{
			return !UNKNOWN_NAME.equals(displayName);
		}
	}

	final class PartyMember
	{
		public final long id;
		@Nonnull
		volatile String lastKnownName = UNKNOWN_NAME;
		/// Client thread only
		@Nonnull
		String standardizedName = UNKNOWN_NAME;
		/// Synced worn and pet item glamours. Client thread only.
		@Nonnull
		public final Map<Integer, GlamourData> itemIdToGlamour = new LinkedHashMap<>();
		/// Last broadcast follower. Client thread only.
		private int followerWorld = -1;
		private int followerViewId = -1;
		private int followerIndex = -1;

		PartyMember(long memberId)
		{
			this.id = memberId;
		}

		private boolean hasName()
		{
			return !UNKNOWN_NAME.equals(standardizedName);
		}

		void handleGlamourMessage(GlamourMessage msg)
		{
			List<GlamourData> glamourData;
			try
			{
				glamourData = GlamourBinaryCodec.decodeList(msg.data);
			}
			catch (IOException e)
			{
				log.warn("[PartySync] failed to decode glamour message from member {}", msg.getMemberId(), e);
				return;
			}

			clientThread.invoke(() -> {
				if (!msg.patch)
				{
					itemIdToGlamour.clear();
				}
				glamourData.forEach(g -> itemIdToGlamour.put(g.getItemId(), g));
				reapply();
				notifyStateChanged();
			});
		}

		void handleFollowerMessage(FollowerMessage msg)
		{
			clientThread.invoke(() -> {
				followerWorld = msg.world;
				followerViewId = msg.viewId;
				followerIndex = msg.index;
				reapply();
			});
		}

		void maybeUpdateName(@Nullable String newName)
		{
			newName = newName != null ? newName : UNKNOWN_NAME;
			if (!lastKnownName.equals(newName))
			{
				log.debug("[PartySync] member {} name changed: '{}' -> '{}'", id, lastKnownName, newName);
				removeFromParty();
				lastKnownName = newName;
				standardizedName = UNKNOWN_NAME.equals(newName) ? UNKNOWN_NAME : Text.standardize(newName);
				reapply();
				notifyStateChanged();
			}
		}

		void removeFromParty()
		{
			petGlamourSync.removePartyMember(id);
			if (hasName())
			{
				glamourEngine.removePlayerGlamour(standardizedName);
			}
		}

		private void reapply()
		{
			if (hasName())
			{
				if (isEligible())
				{
					glamourEngine.updatePlayerGlamour(standardizedName, itemIdToGlamour);
				}
				else
				{
					glamourEngine.removePlayerGlamour(standardizedName);
				}
			}
			if (isEligible() && !itemIdToGlamour.isEmpty())
			{
				final boolean sameWorld = followerWorld == client.getWorld();
				petGlamourSync.updatePartyMember(id,
					standardizedName,
					itemIdToGlamour,
					sameWorld ? followerViewId : -1,
					sameWorld ? followerIndex : -1);
			}
			else
			{
				petGlamourSync.removePartyMember(id);
			}
		}

		private boolean isEligible()
		{
			return config.partySyncReceive() && !blacklist.contains(lastKnownName);
		}
	}

	public static final class RequestUpdateMessage extends PartyMemberMessage
	{
	}

	public static final class LeaveMessage extends PartyMemberMessage
	{
	}

	// --- Lifecycle ---

	public boolean isPartyPluginActive()
	{
		try
		{
			var plugin = pluginManager.getPlugins().stream()
				.filter(p -> p.getClass() == PartyPlugin.class)
				.findFirst()
				.orElse(null);
			return pluginManager.isPluginActive(plugin);
		}
		catch (Exception | AssertionError e)
		{
			return false;
		}
	}

	public void startUp()
	{
		log.debug("[PartySync] startUp");
		isStarted = true;
		wsClient.registerMessage(RequestUpdateMessage.class);
		wsClient.registerMessage(LeaveMessage.class);
		wsClient.registerMessage(GlamourMessage.class);
		wsClient.registerMessage(FollowerMessage.class);

		if (partyService.isInParty())
		{
			requestUpdate();
			sendUpdate();
		}
	}

	public void shutDown()
	{
		log.debug("[PartySync] shutDown");
		isStarted = false;
		if (partyService.isInParty())
		{
			partyService.send(new LeaveMessage());
		}
		partyLeave();

		wsClient.unregisterMessage(RequestUpdateMessage.class);
		wsClient.unregisterMessage(LeaveMessage.class);
		wsClient.unregisterMessage(GlamourMessage.class);
		wsClient.unregisterMessage(FollowerMessage.class);
	}

	// --- Event handlers ---

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		if (event.getPartyId() != null)
		{
			log.debug("[PartySync] joined party {}", event.getPartyId());
			if (!config.partySyncPrompted())
			{
				promptEnableSync();
				config.setPartySyncPrompted(true);
			}
		}
		else
		{
			log.debug("[PartySync] left party");
			partyLeave();
		}
		notifyStateChanged();
	}

	private void promptEnableSync()
	{
		boolean fullyDisabled = !config.partySyncReceive() && !config.partySyncPrompted();
		if (fullyDisabled)
		{
			SwingUtilities.invokeLater(() -> {
				int result = JOptionPane.showConfirmDialog(
					null,
					"Would you like to enable Glamourer Party Sync?\n"
						+ "Your party members will see your glamours and you will see theirs.\n"
						+ "This can be changed at any time in the settings.",
					"Glamourer Party Sync",
					JOptionPane.YES_NO_OPTION,
					JOptionPane.QUESTION_MESSAGE
				);
				if (result == JOptionPane.YES_OPTION)
				{
					config.setPartySyncSend(true);
					config.setPartySyncReceive(true);
				}
			});
		}
	}

	@Subscribe
	public void onUserSync(UserSync event)
	{
		log.debug("[PartySync] user sync from member {}", event.getMemberId());
		updateQueued = true;
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		log.debug("[PartySync] user parted: member {}", event.getMemberId());
		removeMember(event.getMemberId());
		notifyStateChanged();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> {
				if (client.getLocalPlayer() == null)
				{
					return false;
				}
				sendUpdate();
				partyMembers.values().forEach(PartyMember::reapply);
				return true;
			});
		}
	}

	@Subscribe
	public void onFollowerChanged(FollowerChanged event)
	{
		sendFollower(event.getViewId(), event.getIndex());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!isStarted || !partyService.isInParty())
		{
			return;
		}

		if (updateQueued)
		{
			updateQueued = false;
			sendUpdate();
		}

		Set<Long> currentMemberIds = new HashSet<>();
		for (var member : partyService.getMembers())
		{
			currentMemberIds.add(member.getMemberId());
		}
		var it = partyMembers.entrySet().iterator();
		while (it.hasNext())
		{
			var entry = it.next();
			var member = entry.getValue();
			if (currentMemberIds.contains(entry.getKey()))
			{
				member.maybeUpdateName(getMemberDisplayName(member.id));
			}
			else
			{
				log.debug("[PartySync] cleaning up stale member {}", entry.getKey());
				it.remove();
				member.removeFromParty();
				notifyStateChanged();
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV || !shouldSendUpdates())
		{
			return;
		}

		Set<Integer> currentIds = client.getLocalPlayerEquippableItemIds(ddItemManager);
		Set<Integer> newIds = new HashSet<>(currentIds);
		newIds.removeAll(syncedItemIds);
		syncedItemIds = currentIds;

		if (newIds.isEmpty())
		{
			return;
		}

		List<GlamourData> patch = glamourEngine.getGlamourSnapshotForItems(newIds);
		if (!patch.isEmpty())
		{
			try
			{
				log.debug("[PartySync] sending patch: {} new glamours for {} new equippable items", patch.size(), newIds.size());
				partyService.send(GlamourMessage.patch(patch));
			}
			catch (IOException e)
			{
				log.warn("[PartySync] failed to encode inventory patch", e);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(Config.GROUP))
		{
			return;
		}
		switch (event.getKey())
		{
			case Config.KEY_PARTY_SYNC_SEND:
				if (config.partySyncSend())
				{
					sendUpdate();
				}
				else
				{
					sendRevoke();
				}
				break;
			case Config.KEY_PARTY_SYNC_RECV:
				clientThread.invoke(() -> partyMembers.values().forEach(PartyMember::reapply));
				break;
		}
	}

	@Subscribe
	public void onRequestUpdateMessage(RequestUpdateMessage msg)
	{
		if (isSelf(msg))
		{
			return;
		}
		log.debug("[PartySync] received RequestUpdateMessage from member {}", msg.getMemberId());
		sendUpdate();
	}

	@Subscribe
	public void onLeaveMessage(LeaveMessage msg)
	{
		if (isSelf(msg))
		{
			return;
		}
		log.debug("[PartySync] received Leave from member {}", msg.getMemberId());
		removeMember(msg.getMemberId());
		notifyStateChanged();
	}

	@Subscribe
	public void onGlamourMessage(GlamourMessage msg)
	{
		if (isSelf(msg))
		{
			return;
		}

		String playerName = getMemberDisplayName(msg.getMemberId());
		log.debug("[PartySync] received {} from '{}' (member {})", msg.patch ? "patch" : "update", playerName, msg.getMemberId());

		PartyMember data = getOrCreateMemberData(msg.getMemberId());
		data.handleGlamourMessage(msg);
	}

	@Subscribe
	public void onFollowerMessage(FollowerMessage msg)
	{
		if (isSelf(msg))
		{
			return;
		}
		log.debug("[PartySync] received follower {} from member {}", msg.index, msg.getMemberId());
		PartyMember data = getOrCreateMemberData(msg.getMemberId());
		data.handleFollowerMessage(msg);
	}

	// --- Party state ---

	private void requestUpdate()
	{
		log.debug("[PartySync] request update");
		partyService.send(new RequestUpdateMessage());
	}

	public void resync()
	{
		if (!isStarted || !partyService.isInParty())
		{
			return;
		}
		requestUpdate();
		sendUpdate();
	}

	private void partyLeave()
	{
		clientThread.invoke(() -> {
			glamourEngine.clearPlayerGlamours();
			petGlamourSync.clearPartyMembers();
			partyMembers.clear();
			syncedItemIds.clear();
			lastSentFollowerIndex = -1;
		});
		updateQueued = false;
	}

	private void removeMember(long memberId)
	{
		PartyMember data = partyMembers.remove(memberId);
		if (data != null)
		{
			clientThread.invoke(data::removeFromParty);
		}
	}

	private PartyMember getOrCreateMemberData(long memberId)
	{
		return partyMembers.computeIfAbsent(memberId, PartyMember::new);
	}

	@Nullable
	private String getMemberDisplayName(long memberId)
	{
		var member = partyService.getMemberById(memberId);
		return member != null ? member.getDisplayName() : null;
	}

	private void notifyStateChanged()
	{
		onStateChanged.run();
	}

	// --- Sending ---

	private void sendFollower(int followerViewId, int followerIndex)
	{
		if (!shouldSendUpdates())
		{
			return;
		}
		if (followerIndex == -1 && lastSentFollowerIndex == -1)
		{
			return;
		}
		lastSentFollowerIndex = followerIndex;
		log.debug("[PartySync] sending follower {} in view {}", followerIndex, followerViewId);
		partyService.send(new FollowerMessage(client.getWorld(), followerViewId, followerIndex));
	}

	public void sendUpdate()
	{
		clientThread.invoke(() -> {
			if (!shouldSendUpdates())
			{
				return;
			}
			sendFollower(followerTracker.getFollowerViewId(), followerTracker.getFollowerIndex());
			var itemIds = new LinkedHashSet<>(client.getLocalPlayerEquippableItemIds(ddItemManager));
			itemIds.addAll(petSheet.getNpcsByItemId().keySet());
			var snapshot = glamourEngine.getGlamourSnapshotForItems(itemIds);
			try
			{
				log.debug("[PartySync] sending update: {} glamours", snapshot.size());
				syncedItemIds = snapshot.stream().map(GlamourData::getItemId).collect(Collectors.toSet());
				partyService.send(GlamourMessage.update(snapshot));
			}
			catch (IOException e)
			{
				log.warn("[PartySync] failed to encode update", e);
			}
		});
	}

	public void sendPatch(Set<Integer> itemIds)
	{
		clientThread.invoke(() -> {
			if (!shouldSendUpdates())
			{
				return;
			}
			List<GlamourData> patch = glamourEngine.getGlamourSnapshotForItems(itemIds);
			if (!patch.isEmpty())
			{
				try
				{
					log.debug("[PartySync] sending glamour patch: {} glamours", patch.size());
					syncedItemIds.addAll(itemIds);
					partyService.send(GlamourMessage.patch(patch));
				}
				catch (IOException e)
				{
					log.warn("[PartySync] failed to encode patch", e);
				}
			}
		});
	}

	public void sendRevoke()
	{
		if (!isStarted || !partyService.isInParty())
		{
			return;
		}
		try
		{
			log.debug("[PartySync] revoking glamour data");
			partyService.send(GlamourMessage.revokeAll());
		}
		catch (IOException e)
		{
			log.warn("[PartySync] failed to encode revoke", e);
		}
	}

	// --- Queries ---

	public boolean isInParty()
	{
		return partyService.isInParty();
	}

	public List<PartyMemberInfo> getMembers()
	{
		if (!partyService.isInParty() || partyService.getLocalMember() == null)
		{
			return List.of();
		}
		long localId = partyService.getLocalMember().getMemberId();
		List<PartyMemberInfo> result = new ArrayList<>();
		for (var member : partyService.getMembers())
		{
			if (member.getMemberId() == localId)
			{
				continue;
			}
			var glamourMember = partyMembers.get(member.getMemberId());
			boolean hasGlamour = glamourMember != null;
			String name = member.getDisplayName() != null ? member.getDisplayName() : UNKNOWN_NAME;
			result.add(new PartyMemberInfo(member.getMemberId(), name, hasGlamour));
		}
		return result;
	}

	public Collection<Glamour> getMemberGlamours(long memberId)
	{
		PartyMember member = partyMembers.get(memberId);
		if (member != null && member.hasName())
		{
			return glamourEngine.getPlayerGlamours(member.standardizedName);
		}
		return Collections.emptySet();
	}

	public boolean isMemberHidden(long memberId)
	{
		String name = getMemberDisplayName(memberId);
		return name != null && !UNKNOWN_NAME.equals(name) && blacklist.contains(name);
	}

	public void setMemberHidden(long memberId, boolean hidden)
	{
		String name = getMemberDisplayName(memberId);
		if (name == null || UNKNOWN_NAME.equals(name))
		{
			return;
		}
		if (hidden)
		{
			blacklist.add(name);
		}
		else
		{
			blacklist.remove(name);
		}
		PartyMember glamourMember = partyMembers.get(memberId);
		if (glamourMember != null)
		{
			clientThread.invoke(glamourMember::reapply);
		}
	}

	private boolean isSelf(PartyMemberMessage message)
	{
		var localMember = partyService.getLocalMember();
		return localMember == null || localMember.getMemberId() == message.getMemberId();
	}

	private boolean shouldSendUpdates()
	{
		return isStarted && partyService.isInParty() && config.partySyncSend() && client.getGameState() == GameState.LOGGED_IN;
	}
}

package io.huze.glamourer.party;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import io.huze.glamourer.Config;
import java.lang.reflect.Type;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class PlayerBlacklist
{
	static final String CONFIG_KEY = "playerBlacklist";
	private static final Type STRING_SET_TYPE = new TypeToken<Set<String>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;
	private final Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);

	@Inject
	public PlayerBlacklist(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	@Inject
	public synchronized void load()
	{
		names.clear();
		String json = configManager.getConfiguration(Config.GROUP, CONFIG_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Set<String> parsed = gson.fromJson(json, STRING_SET_TYPE);
			if (parsed != null)
			{
				names.addAll(parsed);
			}
		}
		catch (JsonSyntaxException e)
		{
			log.error("Failed to parse hidden party members", e);
		}
	}

	public synchronized boolean contains(String name)
	{
		return names.contains(name);
	}

	public synchronized void add(String name)
	{
		if (names.add(name))
		{
			save();
		}
	}

	public synchronized void remove(String name)
	{
		if (names.remove(name))
		{
			save();
		}
	}

	private void save()
	{
		if (names.isEmpty())
		{
			configManager.unsetConfiguration(Config.GROUP, CONFIG_KEY);
		}
		else
		{
			configManager.setConfiguration(Config.GROUP, CONFIG_KEY, gson.toJson(names));
		}
	}
}

