package io.huze.glamourer.glam;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.color.Colors;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nonnull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.ItemComposition;

@Slf4j
class GlamState
{
	private final int model;
	@Nonnull
	private final short[] colorFind;
	@Nonnull
	private final short[] colorReplace;
	@Nonnull
	private final short[] textureFind;
	@Nonnull
	private final short[] textureReplace;
	private final boolean immutable;
	public final int colorLength;

	GlamState(final int model,
			  @Nonnull final short[] colorFind,
			  @Nonnull final short[] colorReplace,
			  @Nonnull final short[] textureFind,
			  @Nonnull final short[] textureReplace,
			  final boolean immutable)
	{
		this.model = model;
		assert colorFind.length == colorReplace.length;
		this.colorFind = colorFind;
		this.colorReplace = colorReplace;
		assert textureFind.length == textureReplace.length;
		this.textureFind = textureFind;
		this.textureReplace = textureReplace;
		this.immutable = immutable;
		this.colorLength = colorFind.length;
	}

	synchronized GlamState deepCopy(boolean immutable)
	{
		return new GlamState(
			model,
			colorFind.clone(),
			colorReplace.clone(),
			textureFind.clone(),
			textureReplace.clone(),
			immutable);
	}

	/// Assumes the state is primed
	synchronized void applyColorReplacements(List<ColorReplacement> replacements)
	{
		// Snapshot the original colorReplace so that mutations from earlier replacements
		// don't cause later replacements to match the wrong index.
		var originalColorReplace = colorReplace.clone();
		var applied = new boolean[replacements.size()];
		for (int i = 0; i < replacements.size(); i++)
		{
			applied[i] = applyModelColorReplacement(replacements.get(i));
		}
		for (int i = 0; i < replacements.size(); i++)
		{
			if (!applied[i])
			{
				applied[i] = applyOriginalColorReplacement(replacements.get(i), originalColorReplace);
			}
		}
		for (int i = 0; i < applied.length; i++)
		{
			if (!applied[i])
			{
				log.warn("Failed to apply color replacement: {}", replacements.get(i));
			}
		}
	}

	private boolean applyModelColorReplacement(ColorReplacement replacement)
	{
		if (replacement.getModel() != null)
		{
			for (int i = 0; i < colorFind.length; i++)
			{
				if (colorFind[i] == replacement.getModel())
				{
					replaceColor(i, replacement.getReplacement());
					return true;
				}
			}
		}
		return false;
	}

	private boolean applyOriginalColorReplacement(ColorReplacement replacement, short[] originalColorReplace)
	{
		for (int i = 0; i < colorFind.length; i++)
		{
			if (originalColorReplace[i] == replacement.getOriginal())
			{
				replaceColor(i, replacement.getReplacement());
				return true;
			}
		}
		return false;
	}

	synchronized short getColor(int i)
	{
		return colorReplace[i];
	}

	synchronized void replaceColor(int i, short color)
	{
		if (immutable)
		{
			throw new IllegalStateException("Cannot modify immutable GlamState");
		}
		colorReplace[i] = color;
	}

	/// Assumes the state is primed
	synchronized void applyTextureReplacements(List<TextureReplacement> replacements)
	{
		for (TextureReplacement replacement : replacements)
		{
			apply(replacement);
		}
	}

	private void apply(TextureReplacement replacement)
	{
		for (int i = 0; i < textureFind.length; i++)
		{
			if (textureFind[i] == replacement.getOriginal())
			{
				replaceTexture(i, replacement.getReplacement());
			}
		}
	}

	synchronized void replaceTexture(int i, short textureId)
	{
		if (immutable)
		{
			throw new IllegalStateException("Cannot modify immutable GlamState");
		}
		textureReplace[i] = textureId;
	}

	synchronized void applyOriginalTo(final ItemComposition comp)
	{
		comp.setColorToReplace(colorFind);
		comp.setColorToReplaceWith(colorFind);
		comp.setTextureToReplace(textureFind);
		comp.setTextureToReplaceWith(textureFind);
	}

	synchronized void applyTo(final ItemComposition comp)
	{
		var colorReplace = this.colorReplace.clone();
		Colors.breakColorChains(colorFind, colorReplace);
		comp.setColorToReplace(colorFind);
		comp.setColorToReplaceWith(colorReplace);
		comp.setTextureToReplace(textureFind);
		comp.setTextureToReplaceWith(textureReplace);
	}

	private static void arrayCopyEqualLength(@Nonnull short[] src, @Nonnull short[] dest)
	{
		assert src.length == dest.length;
		System.arraycopy(src, 0, dest, 0, src.length);
	}

	synchronized void applyTo(final ColorTextureOverride override)
	{
		var colorReplace = override.getColorToReplaceWith();
		arrayCopyEqualLength(this.colorReplace, colorReplace);
		Colors.breakColorChains(colorFind, colorReplace);
		arrayCopyEqualLength(textureReplace, override.getTextureToReplaceWith());
	}

	@Nonnull
	public synchronized List<ColorReplacement> getColorReplacements()
	{
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		for (int i = 0; i < colorFind.length; i++)
		{
			colorReplacements.add(new ColorReplacement(colorFind[i], colorReplace[i]));
		}
		return colorReplacements;
	}

	@Nonnull
	public synchronized List<TextureReplacement> getTextureReplacements()
	{
		List<TextureReplacement> textureReplacements = new ArrayList<>();
		for (int i = 0; i < textureFind.length; i++)
		{
			textureReplacements.add(new TextureReplacement(textureFind[i], textureReplace[i]));
		}
		return textureReplacements;
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.plate.DisplayStyle;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class Glamourer
{
	private final GlamourEngine engine;
	private final ClientThread clientThread;

	@Nonnull
	public CompletableFuture<Glamour> startGlamourAsync(int itemId)
	{
		CompletableFuture<Glamour> future = new CompletableFuture<>();
		clientThread.invokeLater(() -> {
			future.complete(engine.startGlamour(itemId));
		});
		return future;
	}

	@Nonnull
	public CompletableFuture<GlamourLoadResult> loadGlamoursAsync(@Nonnull List<GlamourData> dataList)
	{
		CompletableFuture<GlamourLoadResult> future = new CompletableFuture<>();
		clientThread.invokeLater(() -> {
			var loaded = new ArrayList<Glamour>();
			var failed = new ArrayList<GlamourData>();
			for (GlamourData data : dataList)
			{
				try
				{
					loaded.add(engine.loadGlamour(data));
				}
				catch (Throwable e)
				{
					log.error("Failed to load glamour for item {}", data, e);
					failed.add(data);
				}
			}
			future.complete(new GlamourLoadResult(loaded, failed));
		});
		return future;
	}

	public void apply(@Nonnull Glamour glam, @Nonnull DisplayStyle displayStyle)
	{
		engine.stageApply(glam, displayStyle);
	}

	public void batch(@Nonnull Runnable action)
	{
		engine.batch(action);
	}

	@Nonnull
	public GlamourVisibility getVisibility(@Nonnull Glamour glam, boolean plateEnabled)
	{
		if (!plateEnabled)
		{
			return GlamourVisibility.DISABLED;
		}
		return engine.getStagedVisibility(glam);
	}

	@Setter
	@Nonnull
	private Consumer<Glamour> onHighlightOverrideChanged = override -> {};

	public void setHighlightOverride(@Nonnull Glamour override)
	{
		engine.setHighlightOverride(override);
		onHighlightOverrideChanged.accept(override);
	}

	public void clearHighlightOverride()
	{
		engine.setHighlightOverride(null);
		onHighlightOverrideChanged.accept(null);
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.Extensions;
import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.item.DedupeKey;
import io.huze.glamourer.item.ItemSheet;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.ItemComposition;
import net.runelite.api.ModelData;

@Slf4j
@ExtensionMethod({java.util.Arrays.class, Extensions.class})
public class PrimedItem
{
	@Getter
	@Setter
	private ItemComposition itemComposition;
	// Store name and model in case other plugins tamper with them.
	@Getter
	private final String name;
	@Getter
	private final int model;

	// The itemComposition's backup visual data.
	// Must never be mutated; only stored to revert the item back to its preprimed state on shutdown.
	@Nullable
	private final short[] backupColorFind;
	@Nullable
	private final short[] backupColorReplace;
	@Nullable
	private final short[] backupTexFind;
	@Nullable
	private final short[] backupTexReplace;

	// Primed data is visually equivalent to the backup data, but includes all unique colors and textures in all models.
	@Nonnull
	private final short[] primedColorFind;
	@Nonnull
	private final short[] primedColorReplace;
	@Nonnull
	private final short[] primedTexFind;
	@Nonnull
	private final short[] primedTexReplace;

	@Getter(lazy = true)
	private final List<ColorReplacement> originalColorReplacements = initBackupColorReplacements();
	@Getter(lazy = true)
	private final List<ColorReplacement> colorReplacements = initColorReplacements();

	private PrimedItem(ItemComposition itemComposition,
					   @Nonnull short[] modelColors,
					   @Nonnull short[] modelTextures)
	{
		this.name = itemComposition.getMembersName();
		this.model = itemComposition.getInventoryModel();

		this.backupColorFind = itemComposition.getColorToReplace();
		this.backupColorReplace = itemComposition.getColorToReplaceWith();
		this.backupTexFind = itemComposition.getTextureToReplace();
		this.backupTexReplace = itemComposition.getTextureToReplaceWith();

		this.primedColorFind = modelColors;
		this.primedColorReplace = applyReplacements(modelColors, backupColorFind, backupColorReplace);
		this.primedTexFind = modelTextures;
		this.primedTexReplace = applyReplacements(modelTextures, backupTexFind, backupTexReplace);

		reprime(itemComposition);
	}

	@Nonnull
	public static PrimedItem of(@Nonnull ItemComposition pureItemComposition, @Nonnull ItemSheet sheet,
								@Nonnull Collection<ItemComposition> groupMembers)
	{
		var colorSet = new HashSet<Short>();
		var textureSet = new HashSet<Short>();
		for (ModelData datum : sheet.getModels(groupMembers))
		{
			for (var color : datum.getFaceColors())
			{
				colorSet.add(color);
			}
			if (datum.getFaceTextures() != null)
			{
				for (var texture : datum.getFaceTextures())
				{
					if (texture != -1)
					{
						textureSet.add(texture);
					}
				}
			}
		}
		var modelColors = colorSet.toShortArray();
		modelColors.sort();
		var modelTextures = textureSet.toShortArray();
		modelTextures.sort();

		return new PrimedItem(pureItemComposition, modelColors, modelTextures);
	}

	@Nonnull
	public static PrimedItem ofDummy(@Nonnull ItemComposition pureItemComposition, @Nonnull PrimedItem realItem)
	{
		return new PrimedItem(pureItemComposition, realItem.primedColorFind.clone(), realItem.primedTexFind.clone());
	}

	private static short[] applyReplacements(@Nonnull short[] values, @Nullable short[] find, @Nullable short[] replace)
	{
		var replacements = values.clone();
		if (find != null && replace != null)
		{
			for (int i = 0; i < values.length; i++)
			{
				for (int j = 0; j < find.length; j++)
				{
					if (replacements[i] == find[j])
					{
						replacements[i] = replace[j];
					}
				}
			}
		}
		return replacements;
	}

	public String getDedupeKey()
	{
		return DedupeKey.fromComponents(name, model, backupColorReplace, backupTexReplace);
	}

	public void reprime()
	{
		itemComposition.setColorToReplace(primedColorFind.clone());
		itemComposition.setColorToReplaceWith(primedColorReplace.clone());
		itemComposition.setTextureToReplace(primedTexFind.clone());
		itemComposition.setTextureToReplaceWith(primedTexReplace.clone());
	}

	public void reprime(ItemComposition itemComposition)
	{
		this.itemComposition = itemComposition;
		reprime();
	}

	public void revert()
	{
		itemComposition.setColorToReplace(backupColorFind);
		itemComposition.setColorToReplaceWith(backupColorReplace);
		itemComposition.setTextureToReplace(backupTexFind);
		itemComposition.setTextureToReplaceWith(backupTexReplace);
	}

	private static void arrayCopyEqualLength(/*@Nonnull*/ short[] src, /*@Nonnull*/ short[] dest)
	{
		if (src == null)
		{
			throw new IllegalArgumentException("arrayCopyEqualLength src was null");
		}
		if (dest == null)
		{
			throw new IllegalArgumentException("arrayCopyEqualLength dest was null");
		}
		if (src.length != dest.length)
		{
			throw new IllegalArgumentException("arrayCopyEqualLength " + src.length + " != " + dest.length);
		}
		System.arraycopy(src, 0, dest, 0, src.length);
	}

	public void prime(@Nonnull ColorTextureOverride override)
	{
		try
		{
			arrayCopyEqualLength(primedColorReplace, override.getColorToReplaceWith());
			arrayCopyEqualLength(primedTexReplace, override.getTextureToReplaceWith());
		}
		catch (Throwable t)
		{
			log.warn("Failed to prime {} {}", name, itemComposition.getId(), t);
		}
	}

	/// Run on a mutable item composition; the composition's visual changes are reset after.
	public void runOnMutableItemComp(Consumer<ItemComposition> runnable)
	{
		// TODO dont need to change colorfind because it never changes except on revert
		final var colorFind = itemComposition.getColorToReplace();
		final var colorReplace = itemComposition.getColorToReplaceWith();
		final var texFind = itemComposition.getTextureToReplace();
		final var texReplace = itemComposition.getTextureToReplaceWith();
		try
		{
			runnable.accept(itemComposition);
		}
		finally
		{
			itemComposition.setColorToReplace(colorFind);
			itemComposition.setColorToReplaceWith(colorReplace);
			itemComposition.setTextureToReplace(texFind);
			itemComposition.setTextureToReplaceWith(texReplace);
		}
	}

	private static final short[] EMPTY = {};
	@Nonnull
	private static short[] nullableClone(@Nullable short[] a)
	{
		return a == null ? EMPTY : a.clone();
	}

	@Nonnull
	GlamState getPrimedState()
	{
		return new GlamState(
			model,
			nullableClone(primedColorFind),
			nullableClone(primedColorReplace),
			nullableClone(primedTexFind),
			nullableClone(primedTexReplace),
			false
		);
	}

	private List<ColorReplacement> initBackupColorReplacements()
	{
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		if (backupColorFind != null && backupColorReplace != null)
		{
			for (int i = 0; i < backupColorFind.length; i++)
			{
				colorReplacements.add(new ColorReplacement(backupColorFind[i], backupColorReplace[i]));
			}
		}
		return colorReplacements;
	}

	private List<ColorReplacement> initColorReplacements()
	{
		assert primedColorFind != null;
		assert primedColorReplace != null;
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		for (int i = 0; i < primedColorFind.length; i++)
		{
			colorReplacements.add(new ColorReplacement(primedColorFind[i], primedColorReplace[i]));
		}
		return colorReplacements;
	}
}

package io.huze.glamourer.glam;

import net.runelite.api.ItemComposition;

public class WornOnlyGlamour extends Glamour
{
	protected final Glamour source;

	public WornOnlyGlamour(Glamour source)
	{
		super(source);
		this.source = source;
	}

	@Override
	boolean isDirty()
	{
		return source.isDirty();
	}

	@Override
	boolean clearDirty()
	{
		return source.clearDirty();
	}

	@Override
	protected void apply(ItemComposition itemComposition)
	{
		staged.applyOriginalTo(itemComposition);
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.ItemComposition;

@Slf4j
public class Glamour
{
	@Nullable
	private final String key;
	private final PrimedItem primedItem;
	@Getter
	private final Collection<Integer> itemIds;
	final GlamState staged;
	private final AtomicBoolean dirty = new AtomicBoolean();

	@Nonnull
	public GlamourData getData(boolean verbose)
	{
		return getData(-1, verbose);
	}

	@Nonnull
	public GlamourData getData(int itemId, boolean verbose)
	{
		var colorReplacements = getColorReplacements();
		if (!verbose)
		{
			// Only keep modelColor for entries with duplicate original colors
			Set<Short> seen = new HashSet<>();
			Set<Short> duplicates = new HashSet<>();
			for (var cr : colorReplacements)
			{
				if (!seen.add(cr.getOriginal()))
				{
					duplicates.add(cr.getOriginal());
				}
			}
			for (var cr : colorReplacements)
			{
				if (!duplicates.contains(cr.getOriginal())
					&& cr.getModel() != null && cr.getModel() == cr.getOriginal())
				{
					cr.setModel(null);
				}
			}
		}

		var colorList = colorReplacements.stream()
			.filter((cr) -> verbose || cr.hasChanged())
			.collect(Collectors.toList());

		var textureList = getTextureReplacements().stream()
			.filter(tr -> verbose || tr.hasChanged())
			.collect(Collectors.toList());

		return new GlamourData(
			itemId == -1 ? key : null,
			itemId == -1 ? getPrimaryItemId() : itemId,
			colorList,
			textureList.isEmpty() ? null : textureList);
	}

	/// Load glamour from serialized GlamourData.
	@Nonnull
	public static Glamour load(@Nonnull PrimedItem primedItem, @Nonnull Collection<Integer> duplicateItemIds, @Nonnull GlamourData data)
	{
		var glamState = primedItem.getPrimedState();
		var colorReplacements = data.getColorReplacements();
		glamState.applyColorReplacements(colorReplacements);
		var textureReplacements = data.getTextureReplacements();
		if (textureReplacements != null)
		{
			glamState.applyTextureReplacements(textureReplacements);
		}
		return new Glamour(data.getItemKey(), primedItem, duplicateItemIds, glamState);
	}

	@Nonnull
	public static Glamour start(@Nonnull PrimedItem primedItem, @Nonnull Collection<Integer> duplicateItemIds)
	{
		return new Glamour(primedItem.getDedupeKey(), primedItem, duplicateItemIds, primedItem.getPrimedState());
	}

	private Glamour(@Nullable String key,
					PrimedItem primedItem,
					Collection<Integer> itemIds,
					GlamState staged)
	{
		this.key = key;
		this.primedItem = primedItem;
		this.itemIds = itemIds;
		this.staged = staged;
	}

	protected Glamour(Glamour source)
	{
		this.key = source.key;
		this.primedItem = source.primedItem;
		this.itemIds = source.itemIds;
		this.staged = source.staged;
	}

	public int getPrimaryItemId()
	{
		return primedItem.getItemComposition().getId();
	}

	public String getItemName()
	{
		return primedItem.getName();
	}

	public boolean isEquivalent(Glamour other)
	{
		return this == other || other instanceof WornOnlyGlamour && this == ((WornOnlyGlamour) other).source;
	}

	protected void apply(ItemComposition itemComposition)
	{
		staged.applyTo(itemComposition);
	}

	private boolean sizeMismatch(@Nonnull ColorTextureOverride override)
	{
		{
			var expectedSize = staged.getColorReplacements().size();
			var actualSize = override.getColorToReplaceWith().length;
			if (expectedSize != actualSize)
			{
				log.warn("Mismatched color replace size ({} != {}) for item {}:{}", expectedSize, actualSize, getPrimaryItemId(), getItemName());
				return true;
			}
		}
		{
			var expectedSize = staged.getTextureReplacements().size();
			var actualSize = override.getTextureToReplaceWith().length;
			if (expectedSize != actualSize)
			{
				log.warn("Mismatched texture replace size ({} != {}) for item {}:{}", expectedSize, actualSize, getPrimaryItemId(), getItemName());
				return true;
			}
		}
		return false;
	}

	protected void applyReplacement(@Nonnull ColorTextureOverride override)
	{
		if (sizeMismatch(override))
		{
			return;
		}
		staged.applyTo(override);
	}

	public void replaceColorIndex(int index, short after)
	{
		staged.replaceColor(index, after);
		dirty.set(true);
	}

	public void replaceTextureIndex(int index, short after)
	{
		staged.replaceTexture(index, after);
		dirty.set(true);
	}

	@Nonnull
	public List<TextureReplacement> getTextureReplacements()
	{
		return staged.getTextureReplacements();
	}

	@Nonnull
	public List<ColorReplacement> getColorReplacements()
	{
		return getColorReplacementsFrom(staged);
	}

	public List<ColorReplacement> getDisplayedColorReplacements()
	{
		return getColorReplacementsFrom(snapshotState());
	}

	private List<ColorReplacement> getColorReplacementsFrom(GlamState state)
	{
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		for (var stagedReplacement : state.getColorReplacements())
		{
			var modelColor = stagedReplacement.getOriginal();
			var originalHsl = modelColor;
			for (var originalReplacement : primedItem.getOriginalColorReplacements())
			{
				if (originalReplacement.getOriginal() == modelColor)
				{
					originalHsl = originalReplacement.getReplacement();
					break;
				}
			}
			var cr = new ColorReplacement(originalHsl, stagedReplacement.getReplacement());
			cr.setModel(modelColor);
			colorReplacements.add(cr);
		}
		return colorReplacements;
	}

	boolean isDirty()
	{
		return dirty.get();
	}

	boolean clearDirty()
	{
		return dirty.getAndSet(false);
	}

	GlamState snapshotState()
	{
		return staged.deepCopy(true);
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.Extensions;
import io.huze.glamourer.item.DummyItemSheet;
import io.huze.glamourer.item.DedupeItemComposition;
import io.huze.glamourer.item.DedupeItemManager;
import io.huze.glamourer.item.ItemSheet;
import io.huze.glamourer.plate.DisplayStyle;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.PlayerChanged;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.events.PlayerSpawned;
import net.runelite.api.events.PostItemComposition;
import net.runelite.api.events.WorldChanged;
import net.runelite.api.kit.KitType;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
@ExtensionMethod({Extensions.class})
public class GlamourEngine
{
	private static final int IMAGE_BATCH_DELAY_MS = 1;
	private static final int RECONCILE_DELAY_MS = 1;

	private final Client client;
	private final ClientThread clientThread;
	private final DedupeItemManager ddItemManager;
	private final ItemSheet itemSheet;
	private final DummyItemSheet dummyItemSheet;
	private final ScheduledExecutorService executor;

	@Setter
	@Nonnull
	private Runnable onGlamoursChanged = () -> {};

	// --- Glamour state ---
	private final Map<Integer, PrimedItem> primedItemMap = new HashMap<>();
	/// What should be applied — written on main thread, read on client thread during reconcile.
	/// All access to staged maps must hold stageLock.
	private final Object stageLock = new Object();
	private final Map<Integer, Glamour> stagedGlamourMap = new HashMap<>();
	private final Map<Integer, Glamour> stagedDefaultEquipMap = new HashMap<>();
	/// What is actually applied — only touched on the client thread.
	private final Map<Integer, Glamour> appliedGlamourMap = new HashMap<>();
	private final Map<Integer, Glamour> appliedDefaultEquipMap = new HashMap<>();
	/// Per-player overrides (keys are standardized names)
	private final Map<String, Map<Integer, Glamour>> playerOverrides = new HashMap<>();
	private final Map<Player, Set<KitType>> activePlayerOverrides = new HashMap<>();
	@Nullable
	private volatile Glamour highlightOverride;

	@Nullable
	private volatile Future<?> reconcileFuture;
	private volatile boolean batchMode;

	// --- Icon state ---
	/// Guards both icon batch fields below.
	private final Object iconLock = new Object();
	/// Stores ItemID -> Queue of all icon generating to perform in the next batch.
	private final Map<Integer, Queue<IconPending>> pendingIconBatch = new HashMap<>();
	@Nullable
	private Future<?> createIconBatchFuture;

	private void resetItemCaches()
	{
		client.getItemModelCache().reset();
		client.getItemSpriteCache().reset();
	}

	/* ==================== Glamour operations ==================== */

	@Nonnull
	PrimedItem getPrimedItem(int itemId)
	{
		return getAndUpdatePrimedItem(itemId, null);
	}

	@Nonnull
	private PrimedItem getPrimedItem(int visibleItemId, int itemId)
	{
		if (visibleItemId == itemId)
		{
			return getPrimedItem(itemId);
		}
		// Visible item is a dummy; prime it using the real item.
		var primedItem = primedItemMap.get(visibleItemId);
		if (primedItem == null)
		{
			var visibleComp = ddItemManager.getItemDefinition(visibleItemId);
			primedItem = PrimedItem.ofDummy(visibleComp, getPrimedItem(itemId));
			primedItemMap.put(visibleItemId, primedItem);
		}
		return primedItem;
	}

	@Nonnull
	private PrimedItem getAndUpdatePrimedItem(int itemId, @Nullable ItemComposition itemComposition)
	{
		var primedItem = primedItemMap.get(itemId);
		if (primedItem == null)
		{
			itemComposition = itemComposition != null ? itemComposition : ddItemManager.getItemDefinition(itemId);
			var groupMembers = new ArrayList<ItemComposition>();
			for (int memberId : ddItemManager.getItemComposition(itemId).getIds())
			{
				groupMembers.add(memberId == itemId ? itemComposition : ddItemManager.getItemDefinition(memberId));
			}
			primedItem = PrimedItem.of(itemComposition, itemSheet, groupMembers);
			primedItemMap.put(itemId, primedItem);
		}
		else if (itemComposition != null)
		{
			primedItem.reprime(itemComposition);
		}
		return primedItem;
	}

	@Subscribe(priority = Float.MAX_VALUE)
	public void onPostItemComposition(PostItemComposition event)
	{
		final var itemComp = event.getItemComposition();
		final var itemId = itemComp.getId();

		if (primedItemMap.containsKey(itemId))
		{
			getAndUpdatePrimedItem(itemId, itemComp);
		}

		Glamour glamour;
		if ((glamour = appliedGlamourMap.get(itemId)) != null)
		{
			glamour.apply(itemComp);
		}
	}

	/// -1 priority so other plugins >= 0 changes happen before we reconcile.
	@Subscribe(priority = -1)
	public void onPlayerSpawned(PlayerSpawned event)
	{
		reconcilePlayer(event.getPlayer());
	}

	@Subscribe(priority = -1)
	public void onPlayerChanged(PlayerChanged event)
	{
		var player = event.getPlayer();
		if (activePlayerOverrides.containsKey(player))
		{
			reconcilePlayer(event.getPlayer());
		}
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		clearPlayerOverrides(event.getPlayer());
		activePlayerOverrides.remove(event.getPlayer());
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		activePlayerOverrides.clear();
	}

	@Subscribe(priority = -1)
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() instanceof Player && activePlayerOverrides.containsKey(event.getActor()))
		{
			reconcilePlayer((Player) event.getActor());
		}
	}

	/**
	 * Get glamours for player.
	 */
	@Nonnull
	private Map<Integer, Glamour> getPlayerGlamours(@Nonnull Player player)
	{
		if (player == client.getLocalPlayer())
		{
			var override = highlightOverride;
			if (override != null)
			{
				var merged = new HashMap<>(appliedGlamourMap);
				for (int itemId : override.getItemIds())
				{
					merged.put(itemId, override);
				}
				return merged;
			}
			return appliedGlamourMap;
		}
		var standardizedName = player.getName();
		if (standardizedName != null)
		{
			standardizedName = Text.standardize(standardizedName);
		}
		var basePlayerOverrides = playerOverrides.get(standardizedName);
		if (basePlayerOverrides != null)
		{
			var playerOverrides = new HashMap<>(appliedDefaultEquipMap);
			playerOverrides.putAll(basePlayerOverrides);
			return playerOverrides;
		}
		return appliedDefaultEquipMap;
	}

	private void reconcilePlayerByName(@Nonnull String standardizedName)
	{
		for (var entry : activePlayerOverrides.entrySet())
		{
			var player = entry.getKey();
			var name = player.getName();
			if (name != null && standardizedName.equals(Text.standardize(name)))
			{
				reconcilePlayer(player);
			}
		}
	}

	/**
	 * Reconcile player equipment overrides. Client thread only.
	 */
	private void reconcilePlayer(@Nonnull Player player)
	{
		var empty = EnumSet.noneOf(KitType.class);
		var currentKit = activePlayerOverrides.putIfAbsent(player, empty);
		currentKit = currentKit == null ? empty : currentKit;

		// Extract item ID overrides from animation.
		int rightItemId = -1;
		int leftItemId = -1;
		int animationId = player.getAnimation();
		if (animationId != -1)
		{
			var animation = client.loadAnimation(animationId);
			if (animation != null)
			{
				rightItemId = animation.getRightHandItem();
				leftItemId = animation.getLeftHandItem();
			}
		}
		var activeKit = EnumSet.noneOf(KitType.class);
		var overrides = getPlayerGlamours(player);
		var comp = player.getPlayerComposition();
		var equipmentIds = comp.getEquipmentIds();
		for (int kitIdx = 0; kitIdx < equipmentIds.length; kitIdx++)
		{
			KitType kit = KitType.values()[kitIdx];
			int equipmentId = equipmentIds[kitIdx];
			int visibleItemId = equipmentId - PlayerComposition.ITEM_OFFSET;
			if (kit == KitType.WEAPON && rightItemId != -1)
			{
				visibleItemId = rightItemId;
			}
			else if (kit == KitType.SHIELD && leftItemId != -1)
			{
				visibleItemId = leftItemId;
			}
			else if (equipmentId < PlayerComposition.ITEM_OFFSET)
			{
				continue;
			}
			int itemId = dummyItemSheet.getItemIdForVisibleItemId(visibleItemId);

			// Apply override if one exists
			var override = overrides.get(itemId);
			if (override != null)
			{
				getPrimedItem(visibleItemId, itemId);
				override.applyReplacement(comp.createColorTextureOverride(kit, visibleItemId));
				activeKit.add(kit);
				continue;
			}

			// Apply original if item is primed
			var primedItem = primedItemMap.get(visibleItemId);
			if (primedItem != null)
			{
				primedItem.prime(comp.createColorTextureOverride(kit, visibleItemId));
				activeKit.add(kit);
				continue;
			}

			// Remove old override if kit is no longer glamoured
			if (currentKit.contains(kit))
			{
				comp.removeColorTextureOverride(kit);
			}
		}
		comp.setHash();
		currentKit.clear();
		currentKit.addAll(activeKit);
	}

	private void clearPlayerOverrides(@Nonnull Player player)
	{
		var overrides = activePlayerOverrides.get(player);
		if (overrides != null && player.getPlayerComposition() != null)
		{
			var comp = player.getPlayerComposition();
			overrides.forEach(comp::removeColorTextureOverride);
			comp.setHash();
		}
	}

	/**
	 * Backfill player state from missed onPlayerSpawned events.
	 * Only necessary if plugin startUp happens after login.
	 * Main thread only.
	 */
	public void backfillPlayerState()
	{
		clientThread.invokeLater(() -> {
			if (client.getGameState().getState() < GameState.LOGGED_IN.getState())
			{
				return false;
			}
			var worldView = client.getTopLevelWorldView();
			for (var player : worldView.players())
			{
				onPlayerSpawned(new PlayerSpawned(player));
			}
			for (var subWorldView : worldView.worldViews())
			{
				for (var player : subWorldView.players())
				{
					onPlayerSpawned(new PlayerSpawned(player));
				}
			}
			return true;
		});
	}

	/**
	 * Start glamour for item ID. Client thread only.
	 */
	Glamour startGlamour(int itemId)
	{
		var itemComp = ddItemManager.getItemComposition(itemId);
		return Glamour.start(getPrimedItem(itemId), itemComp.getIds());
	}

	/// Loads each datum, skipping and logging any that fail — the one policy for turning synced data
	/// back into glamours outside the engine.
	public List<Glamour> loadGlamours(Collection<GlamourData> data)
	{
		List<Glamour> loaded = new ArrayList<>(data.size());
		for (GlamourData datum : data)
		{
			try
			{
				loaded.add(loadGlamour(datum));
			}
			catch (Exception e)
			{
				log.debug("Failed to load a glamour", e);
			}
		}
		return loaded;
	}

	/**
	 * Load glamour from data. Client thread only.
	 */
	Glamour loadGlamour(GlamourData data)
	{
		DedupeItemComposition comp;
		if (data.getItemKey() != null)
		{
			comp = ddItemManager.getItemComposition(data.getItemKey());
			if (comp == null)
			{
				// No item was found for this glamour's key; the key is corrupted.
				// Try to repair the corruption by finding a new item that most closely resembles the original glamour.
				data = DataRepairer.tryRepairOrThrow(this, ddItemManager, data);
				comp = ddItemManager.getItemComposition(data.getItemKey());
			}
		}
		else if (data.getItemId() != null)
		{
			comp = ddItemManager.getItemComposition(data.getItemId());
		}
		else
		{
			throw new IllegalArgumentException("Illegal GlamourData with no item key or id");
		}
		return Glamour.load(getPrimedItem(comp.getId()), comp.getIds(), data);
	}

	/**
	 * Stage apply glamour. Callable from any thread.
	 */
	void stageApply(Glamour glam, DisplayStyle displayStyle)
	{
		boolean changed = glam.isDirty();
		synchronized (stageLock)
		{
			for (int key : glam.getItemIds())
			{
				if (displayStyle == DisplayStyle.GLOBAL)
				{
					changed |= stagedDefaultEquipMap.putIfAbsent(key, glam) == null;
				}
				changed |= stagedGlamourMap.putIfAbsent(key, glam) == null;
			}
		}
		if (changed)
		{
			scheduleReconcile();
		}
	}

	private void clearAllStaged()
	{
		synchronized (stageLock)
		{
			stagedGlamourMap.clear();
			stagedDefaultEquipMap.clear();
		}
	}

	/**
	 * Check the staged visibility of a glamour. Callable from any thread.
	 */
	GlamourVisibility getStagedVisibility(@Nonnull Glamour glam)
	{
		synchronized (stageLock)
		{
			for (int key : glam.getItemIds())
			{
				Glamour staged = stagedGlamourMap.get(key);
				if (glam.isEquivalent(staged))
				{
					return GlamourVisibility.VISIBLE;
				}
			}
			for (int key : glam.getItemIds())
			{
				Glamour staged = stagedDefaultEquipMap.get(key);
				if (glam.isEquivalent(staged))
				{
					return GlamourVisibility.OTHERS;
				}
			}
		}
		return GlamourVisibility.HIDDEN;
	}

	/**
	 * Callable from any thread.
	 */
	public boolean isGlobal(int itemId)
	{
		synchronized (stageLock)
		{
			return stagedDefaultEquipMap.containsKey(itemId);
		}
	}

	/**
	 * Clear all staged glamours, run the action to re-stage, then schedule a single reconcile.
	 */
	void batch(Runnable action)
	{
		batchMode = true;
		try
		{
			clearAllStaged();
			action.run();
		}
		finally
		{
			batchMode = false;
		}
		scheduleReconcile();
	}

	private void scheduleReconcile()
	{
		if (batchMode)
		{
			return;
		}
		Future<?> existing = reconcileFuture;
		if (existing == null || existing.isDone())
		{
			reconcileFuture = executor.schedule(
				() -> clientThread.invokeLater(this::reconcile),
				RECONCILE_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Reconcile any differences between staged and applied glamours.
	 */
	private void reconcile()
	{
		Map<Integer, Glamour> staged;
		Map<Integer, Glamour> stagedEquip;
		synchronized (stageLock)
		{
			staged = new HashMap<>(stagedGlamourMap);
			stagedEquip = new HashMap<>(stagedDefaultEquipMap);
		}
		var currentlyApplied = new HashSet<>(appliedGlamourMap.values());
		var shouldBeApplied = new HashSet<>(staged.values());

		boolean itemsChanged = false;
		for (Glamour glam : currentlyApplied)
		{
			if (!shouldBeApplied.contains(glam))
			{
				for (int itemId : glam.getItemIds())
				{
					var primedItem = primedItemMap.get(itemId);
					if (primedItem != null)
					{
						primedItem.reprime();
					}
				}
				itemsChanged = true;
			}
		}
		for (Glamour glam : shouldBeApplied)
		{
			if (!currentlyApplied.contains(glam) || glam.clearDirty())
			{
				for (int itemId : glam.getItemIds())
				{
					glam.apply(getPrimedItem(itemId).getItemComposition());
				}
				itemsChanged = true;
			}
		}

		if (itemsChanged)
		{
			appliedGlamourMap.clear();
			appliedGlamourMap.putAll(staged);
			resetItemCaches();
		}

		var equipChanged = !stagedEquip.equals(appliedDefaultEquipMap);
		if (itemsChanged || equipChanged)
		{
			appliedDefaultEquipMap.clear();
			appliedDefaultEquipMap.putAll(stagedEquip);
			for (var entry : activePlayerOverrides.entrySet())
			{
				reconcilePlayer(entry.getKey());
			}
			onGlamoursChanged.run();
		}
	}

	/**
	 * Revert all applied glamours for shutdown.
	 * Main thread only.
	 */
	public void revertAll()
	{
		highlightOverride = null;
		clientThread.invokeLater(() -> {
			for (var entry : activePlayerOverrides.entrySet())
			{
				var player = entry.getKey();
				clearPlayerOverrides(player);
			}
			activePlayerOverrides.clear();
			playerOverrides.clear();
			clearAllStaged();
			appliedGlamourMap.clear();
			appliedDefaultEquipMap.clear();
			primedItemMap.values().forEach(PrimedItem::revert);
			resetItemCaches();
		});
	}

	void setHighlightOverride(@Nullable Glamour override)
	{
		highlightOverride = override;
		refreshLocalEquipment();
	}

	private void refreshLocalEquipment()
	{
		clientThread.invokeLater(() -> {
			var player = client.getLocalPlayer();
			if (player == null)
			{
				return;
			}
			reconcilePlayer(player);
		});
	}

	/* ==================== Sync related operations ==================== */

	/**
	 * Snapshot glamours for specific item IDs only.
	 * Client thread only.
	 */
	@Nonnull
	public List<GlamourData> getGlamourSnapshotForItems(@Nonnull Collection<Integer> itemIds)
	{
		Map<Integer, Glamour> staged = new LinkedHashMap<>();
		synchronized (stageLock)
		{
			for (int itemId : itemIds)
			{
				var glamour = stagedGlamourMap.get(itemId);
				if (glamour != null)
				{
					staged.put(itemId, glamour);
				}
			}
		}
		List<GlamourData> snapshot = new ArrayList<>(staged.size());
		for (var entry : staged.entrySet())
		{
			snapshot.add(entry.getValue().getData(entry.getKey(), false));
		}
		return snapshot;
	}

	/**
	 * Apply glamours to a player.
	 * Client thread only.
	 */
	public void updatePlayerGlamour(@Nonnull String standardizedName, @Nonnull Map<Integer, GlamourData> glamours)
	{
		Map<Integer, Glamour> overrideMap = new LinkedHashMap<>();
		for (var data : glamours.entrySet())
		{
			try
			{
				overrideMap.put(data.getKey(), loadGlamour(data.getValue()));
			}
			catch (Exception e)
			{
				log.warn("Failed to load glamour for {}: {}", standardizedName, data.getKey(), e);
			}
		}
		playerOverrides.put(standardizedName, overrideMap);
		reconcilePlayerByName(standardizedName);
	}

	public Collection<Glamour> getPlayerGlamours(@Nonnull String standardizedName)
	{
		var glamours = playerOverrides.get(standardizedName);
		return glamours != null ? glamours.values() : Collections.emptySet();
	}

	/**
	 * Remove all player glamour data.
	 * Client thread only.
	 */
	public void clearPlayerGlamours()
	{
		var standardizedNames = new HashSet<>(playerOverrides.keySet());
		playerOverrides.clear();
		standardizedNames.forEach(this::reconcilePlayerByName);
	}

	/**
	 * Remove all glamour data for a player.
	 * Client thread only.
	 */
	public void removePlayerGlamour(@Nonnull String standardizedName)
	{
		playerOverrides.remove(standardizedName);
		reconcilePlayerByName(standardizedName);
	}

	/* ==================== Icon operations ==================== */

	/**
	 * Returns an AsyncBufferedImage that will populate with the icon at the next available opportunity.
	 */
	@Nonnull
	AsyncBufferedImage getIcon(int itemId, GlamState glamState)
	{
		AsyncBufferedImage img = new AsyncBufferedImage(
			clientThread, Constants.ITEM_SPRITE_WIDTH, Constants.ITEM_SPRITE_HEIGHT, BufferedImage.TYPE_INT_ARGB);
		IconPending iconPending = new IconPending(img, glamState);
		executor.execute(() -> queueIconCreation(itemId, iconPending));
		return img;
	}

	private void queueIconCreation(final int itemId, @Nonnull final IconPending iconPending)
	{
		synchronized (iconLock)
		{
			pendingIconBatch.computeIfAbsent(itemId, k -> new ArrayDeque<>()).add(iconPending);
			scheduleIconBatch();
		}
	}

	/// Caller must hold iconLock.
	private void scheduleIconBatch()
	{
		if (createIconBatchFuture == null && !pendingIconBatch.isEmpty())
		{
			createIconBatchFuture = executor.schedule(
				() -> clientThread.invokeLater(this::executeIconBatch),
				IMAGE_BATCH_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	private void executeIconBatch()
	{
		// Snapshot current batch items and start a new empty batch.
		Map<Integer, Queue<IconPending>> batch;
		synchronized (iconLock)
		{
			batch = new HashMap<>(pendingIconBatch);
			pendingIconBatch.clear();
			createIconBatchFuture = null;
		}

		// Render once per item id per round until every queue is empty.
		while (!batch.isEmpty())
		{
			resetItemCaches();
			for (var it = batch.entrySet().iterator(); it.hasNext(); )
			{
				var entry = it.next();
				final var itemId = entry.getKey();
				if (entry.getValue().isEmpty())
				{
					it.remove();
					continue;
				}
				final var iconState = entry.getValue().poll();
				// Touch the item definition to ensure our reference is fresh.
				ddItemManager.getItemDefinition(itemId);
				getPrimedItem(itemId).runOnMutableItemComp(itemComp -> {
					iconState.state.applyTo(itemComp);
					if (createSprite(itemId, iconState.image))
					{
						iconState.image.loaded();
					}
					else
					{
						// Retry failures. ItemManager AsyncBufferedImage retries infinitely so this should be safe.
						queueIconCreation(itemId, iconState);
					}
				});
			}
		}
		resetItemCaches();
		synchronized (iconLock)
		{
			scheduleIconBatch();
		}
	}

	private boolean createSprite(int itemId, @Nonnull BufferedImage target)
	{
		var spritePixels = client.createItemSprite(
			itemId,
			10000,
			1,
			SpritePixels.DEFAULT_SHADOW_COLOR,
			ItemQuantityMode.NEVER,
			false,
			Constants.CLIENT_DEFAULT_ZOOM
		);
		if (spritePixels != null)
		{
			spritePixels.toBufferedImage(target);
			return true;
		}
		return false;
	}
}

package io.huze.glamourer.glam;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.awt.image.BufferedImage;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class IconService
{
	private final Cache<IconKey, BufferedImage> iconCache = CacheBuilder.newBuilder()
		.maximumSize(256)
		.expireAfterAccess(60, TimeUnit.SECONDS)
		.build();
	private final GlamourEngine engine;

	@Nonnull
	public BufferedImage getIcon(Glamour glamour)
	{
		return getIcon(glamour.getPrimaryItemId(), glamour.snapshotState());
	}

	@Nonnull
	BufferedImage getIcon(final int itemId, final GlamState state)
	{
		IconKey key = IconKey.of(itemId, state);
		BufferedImage cached = iconCache.getIfPresent(key);
		if (cached != null)
		{
			return cached;
		}
		var img = engine.getIcon(itemId, state);
		iconCache.put(key, img);
		img.onLoaded(() -> {
			BufferedImage copy = new BufferedImage(
				img.getColorModel(), img.getRaster(), img.isAlphaPremultiplied(), null);
			iconCache.put(key, copy);
		});
		return img;
	}
}

package io.huze.glamourer.glam;

import lombok.AllArgsConstructor;
import lombok.Getter;

@AllArgsConstructor
public enum GlamourVisibility
{
	/// Unspecified visibility (no icon)
	UNSPECIFIED("Unspecified"),
	/// Glamour is disabled and completely non-visible. (Grey slash eye)
	DISABLED("Disabled"),
	/// Glamour is enabled, but hidden due to conflict. (Red slash eye)
	HIDDEN("Hidden by another plate"),
	/// Glamour is visible on items, local player, and maybe others. (Green eye)
	VISIBLE("Visible"),
	/// Glamour is visible only on others. (Yellow eye)
	OTHERS("Visible only on other players");

	@Getter
	final String tooltip;
}

package io.huze.glamourer.glam;

import io.huze.glamourer.Extensions;
import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.stream.Collectors;
import lombok.Value;
import lombok.experimental.ExtensionMethod;

@Value
@ExtensionMethod({Extensions.class})
class IconKey
{
	int itemId;
	String colorReplace;
	String textureReplace;

	static IconKey of(int itemId, GlamState state)
	{
		var colorReplace = state.getColorReplacements().stream()
			.map(ColorReplacement::getReplacement)
			.collect(Collectors.toList());
		var textureReplace = state.getTextureReplacements().stream()
			.map(TextureReplacement::getReplacement)
			.collect(Collectors.toList());
		return new IconKey(
			itemId,
			colorReplace.toHex(),
			textureReplace.toHex());
	}

	@Override
	public String toString()
	{
		return String.format("%d:%s:%s",
			itemId,
			colorReplace,
			textureReplace);
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.glam.GlamourEngine;
import io.huze.glamourer.item.PetSheet;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class PetGlamourSync
{
	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final GlamourEngine glamourEngine;
	private final NpcGlamourer npcGlamourer;
	private final PetSheet petSheet;
	private final FollowerTracker followerTracker;
	private final HouseTracker houseTracker;

	/// Member pet glamours keyed by party member id. Client thread only.
	private final Map<Long, PlayerPetGlamours> partyMembers = new HashMap<>();

	/// Is NPC ID a non-follower pet (PoH menagerie). Client thread only.
	private final Map<Integer, Boolean> nonFollowerPetByNpcId = new HashMap<>();

	/// Is end-of-tick glamour sync queued. Client thread only.
	private boolean syncQueued;

	public void startUp()
	{
		eventBus.register(houseTracker);
		eventBus.register(followerTracker);
		eventBus.register(this);
		followerTracker.start();
	}

	public void shutDown()
	{
		eventBus.unregister(this);
		eventBus.unregister(followerTracker);
		eventBus.unregister(houseTracker);
	}

	/// Client thread only.
	public void updatePartyMember(long memberId, String standardizedName,
		Map<Integer, GlamourData> itemGlamours, int followerViewId, int followerIndex)
	{
		partyMembers.put(memberId,
			new PlayerPetGlamours(standardizedName, filterNonPetGlamours(itemGlamours), followerViewId, followerIndex));
		queueSync();
	}

	/// Client thread only.
	public void removePartyMember(long memberId)
	{
		if (partyMembers.remove(memberId) != null)
		{
			queueSync();
		}
	}

	/// Client thread only.
	public void clearPartyMembers()
	{
		if (!partyMembers.isEmpty())
		{
			partyMembers.clear();
			queueSync();
		}
	}

	/// Glamours for visited PoH owner's Menagerie pets
	/// We don't actually know what pets are in their menagerie, so we must return all pet glamours.
	private Map<Integer, NpcGlamour> getVisitedOwnerGlamours()
	{
		String houseOwner = houseTracker.getCurrentOwnerName();
		if (houseOwner != null)
		{
			for (PlayerPetGlamours member : partyMembers.values())
			{
				if (houseOwner.equals(member.standardizedName))
				{
					return member.petGlamours;
				}
			}
		}
		return Map.of();
	}

	private Map<Integer, NpcGlamour> filterNonPetGlamours(Map<Integer, GlamourData> itemGlamours)
	{
		Map<Integer, List<Integer>> pets = petSheet.getNpcsByItemId();
		Map<Integer, NpcGlamour> glamours = new HashMap<>();
		itemGlamours.forEach((itemId, data) -> {
			if (pets.containsKey(itemId))
			{
				NpcGlamour glamour = NpcGlamour.of(data.getColorReplacements(), data.getTextureReplacements());
				if (!glamour.isEmpty())
				{
					glamours.put(itemId, glamour);
				}
			}
		});
		return glamours;
	}

	public void sync()
	{
		var petItemsToNpcIds = petSheet.getNpcsByItemId();
		Map<Integer, NpcGlamour> ours = getOurGlamours(petItemsToNpcIds.keySet());
		syncKinds(petItemsToNpcIds, ours);
		syncInstances(petItemsToNpcIds, ours);
	}

	private Map<Integer, NpcGlamour> getOurGlamours(Set<Integer> itemIds)
	{
		Map<Integer, NpcGlamour> glamours = new HashMap<>();
		for (GlamourData data : glamourEngine.getGlamourSnapshotForItems(itemIds))
		{
			Integer itemId = data.getItemId();
			if (itemId != null)
			{
				glamours.put(itemId, NpcGlamour.of(data.getColorReplacements(), data.getTextureReplacements()));
			}
		}
		return glamours;
	}

	private void syncKinds(Map<Integer, List<Integer>> petItemsToNpcIds, Map<Integer, NpcGlamour> ourGlamours)
	{
		final var ownerGlamours = getVisitedOwnerGlamours();
		for (var petItemsToNpcId : petItemsToNpcIds.entrySet())
		{
			final int itemId = petItemsToNpcId.getKey();
			NpcGlamour ours = ourGlamours.getOrDefault(itemId, NpcGlamour.empty());
			NpcGlamour placed = ownerGlamours.getOrDefault(itemId, ours);
			NpcGlamour follower = glamourEngine.isGlobal(itemId) ? ours : NpcGlamour.empty();
			for (int npcId : petItemsToNpcId.getValue())
			{
				NpcGlamour kindGlamour = placed == follower
					? placed
					: isNonFollowerPet(npcId) ? placed : follower;
				npcGlamourer.setKindGlamour(npcId, kindGlamour);
			}
		}
	}

	private void syncInstances(Map<Integer, List<Integer>> petItemsToNpcIds, Map<Integer, NpcGlamour> ourGlamours)
	{
		final int ourViewId = followerTracker.getFollowerViewId();
		final int ourIndex = followerTracker.getFollowerIndex();

		Map<NpcInstanceKey, NpcGlamour> instances = new HashMap<>();
		for (PlayerPetGlamours member : partyMembers.values())
		{
			if (member.followerIndex == -1
				|| (member.followerIndex == ourIndex && member.followerViewId == ourViewId))
			{
				continue;
			}
			member.petGlamours.forEach((itemId, glamour) ->
				addInstance(instances, member.followerViewId, member.followerIndex,
					petItemsToNpcIds.getOrDefault(itemId, List.of()), glamour));
		}

		if (ourIndex != -1)
		{
			final int itemId = petSheet.getItemId(followerTracker.getFollowerId());
			NpcGlamour ours = itemId == -1 || glamourEngine.isGlobal(itemId)
				? NpcGlamour.empty()
				: ourGlamours.getOrDefault(itemId, NpcGlamour.empty());
			addInstance(instances, ourViewId, ourIndex, petItemsToNpcIds.getOrDefault(itemId, List.of()), ours);
		}

		npcGlamourer.setInstanceGlamours(instances);
	}

	private static void addInstance(Map<NpcInstanceKey, NpcGlamour> instances, int viewId,
		int npcIndex, List<Integer> npcIds, NpcGlamour glamour)
	{
		if (glamour.isEmpty())
		{
			return;
		}
		for (int npcId : npcIds)
		{
			instances.put(new NpcInstanceKey(viewId, npcIndex, npcId), glamour);
		}
	}

	private boolean isNonFollowerPet(int npcId)
	{
		return nonFollowerPetByNpcId.computeIfAbsent(npcId, id -> {
			NPCComposition composition = client.getNpcDefinition(id);
			return composition != null && !composition.isFollower();
		});
	}

	public void queueSync()
	{
		if (syncQueued)
		{
			return;
		}
		syncQueued = true;
		clientThread.invokeAtTickEnd(() -> {
			syncQueued = false;
			sync();
		});
	}

	private void queueSyncFor(NPC npc)
	{
		if (petSheet.getItemId(npc.getId()) != -1 && isNonFollowerPet(npc.getId()))
		{
			queueSync();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		queueSyncFor(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		queueSyncFor(event.getNpc());
	}

	@Subscribe
	public void onFollowerChanged(FollowerChanged event)
	{
		// Immediate sync instead of queued to prevent color pop-in
		sync();
	}

	public void setHighlight(@Nullable Glamour highlight)
	{
		clientThread.invoke(() -> applyHighlight(highlight));
	}

	/// Client thread only.
	private void applyHighlight(@Nullable Glamour highlight)
	{
		if (highlight == null || !previewOnPet(highlight))
		{
			// Ended, not a pet, or nothing to land on.
			npcGlamourer.clearHighlight();
		}
	}

	/// Client thread only.
	private boolean previewOnPet(Glamour highlight)
	{
		for (int itemId : highlight.getItemIds())
		{
			List<Integer> npcIds = petSheet.getNpcIds(itemId);
			if (npcIds.isEmpty())
			{
				continue;
			}
			NpcGlamour displayed = NpcGlamour.of(highlight.getDisplayedColorReplacements(),
				highlight.getTextureReplacements());
			if (glamourEngine.isGlobal(itemId))
			{
				npcGlamourer.setHighlight(npcIds, displayed);
				return true;
			}

			if (petSheet.getItemId(followerTracker.getFollowerId()) == itemId)
			{
				npcGlamourer.setHighlight(npcIds, followerTracker.getFollowerViewId(),
					followerTracker.getFollowerIndex(), displayed);
				return true;
			}
			if (getVisitedOwnerGlamours().containsKey(itemId))
			{
				return false;
			}
			List<Integer> placed = new ArrayList<>();
			for (int npcId : npcIds)
			{
				if (isNonFollowerPet(npcId))
				{
					placed.add(npcId);
				}
			}
			if (placed.isEmpty())
			{
				return false;
			}
			npcGlamourer.setHighlight(placed, displayed);
			return true;
		}
		return false;
	}
}

package io.huze.glamourer.npc;

import java.util.Arrays;
import javax.annotation.Nullable;
import net.runelite.api.Model;

final class GlamouredKind
{
	private final GlamouredModelData modelData;
	private int generation;
	private int frameCounter;
	@Nullable
	private int[][] glamouredLitFaces;
	@Nullable
	private int[][] modelFaces;
	@Nullable
	private int[][] lastWrittenFaces;
	@Nullable
	private short[] appliedTextures;

	GlamouredKind(GlamouredModelData modelData)
	{
		this.modelData = modelData;
	}

	boolean isPatchedInFrame(int frameCounter)
	{
		return this.frameCounter == frameCounter;
	}

	void setLastPatchedFrame(int frameCounter)
	{
		this.frameCounter = frameCounter;
	}

	boolean needsGlamourForGeneration(int generation)
	{
		return glamouredLitFaces == null || this.generation != generation;
	}

	boolean updateGlamour(NpcGlamour glamour, int generation)
	{
		modelData.applyGlamour(glamour);
		Model lit = modelData.light();
		if (lit == null)
		{
			return false;
		}
		glamouredLitFaces = GlamouredModelData.getFaceColorsOf(lit);
		this.generation = generation;
		return true;
	}

	void apply(Model live)
	{
		int[][] target = GlamouredModelData.getFaceColorsOf(live);
		if (this.modelFaces != null && this.modelFaces[0] == target[0] && lastWrittenFaces == glamouredLitFaces)
		{
			return;
		}
		final int[][] original = modelData.getOriginalLitColors();
		final int n = original[0].length;
		for (int i = 1; i < target.length; i++)
		{
			if (target[i].length < n)
			{
				return;
			}
		}
		if (!startsWith(target[0], original[0])
			&& (lastWrittenFaces == null || !startsWith(target[0], lastWrittenFaces[0])))
		{
			return;
		}
		for (int i = 0; i < target.length; i++)
		{
			System.arraycopy(glamouredLitFaces[i], 0, target[i], 0, n);
		}
		this.modelFaces = target;
		lastWrittenFaces = glamouredLitFaces;
		applyTextures(live);
	}

	private void applyTextures(Model live)
	{
		short[] target = live.getFaceTextures();
		short[] glamoured = modelData.getFaceTextures();
		if (target == null || glamoured == null)
		{
			return;
		}
		System.arraycopy(glamoured, 0, target, 0, Math.min(glamoured.length, target.length));
		appliedTextures = target;
	}

	boolean revertIfNotPatched(int frame)
	{
		if (frameCounter == frame)
		{
			return false;
		}
		revert();
		return true;
	}

	void revert()
	{
		if (modelFaces != null && lastWrittenFaces != null && startsWith(modelFaces[0], lastWrittenFaces[0]))
		{
			int[][] original = modelData.getOriginalLitColors();
			for (int i = 0; i < original.length; i++)
			{
				System.arraycopy(original[i], 0, modelFaces[i], 0, original[i].length);
			}
			short[] originalTextures = modelData.getOriginalTextures();
			if (appliedTextures != null && originalTextures != null)
			{
				System.arraycopy(originalTextures, 0, appliedTextures, 0,
					Math.min(originalTextures.length, appliedTextures.length));
			}
		}
		modelFaces = null;
		lastWrittenFaces = null;
		appliedTextures = null;
	}

	private static boolean startsWith(int[] live, int[] expected)
	{
		return live.length >= expected.length
			&& Arrays.equals(live, 0, expected.length, expected, 0, expected.length);
	}
}

package io.huze.glamourer.npc;

class NpcInstanceKey
{
	private final int viewId;
	private final int npcIndex;
	private final int npcId;

	NpcInstanceKey(int viewId, int npcIndex, int npcId)
	{
		this.viewId = viewId;
		this.npcIndex = npcIndex;
		this.npcId = npcId;
	}

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof NpcInstanceKey))
		{
			return false;
		}
		NpcInstanceKey key = (NpcInstanceKey) other;
		return viewId == key.viewId && npcIndex == key.npcIndex && npcId == key.npcId;
	}

	@Override
	public int hashCode()
	{
		return 31 * (31 * viewId + npcIndex) + npcId;
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.color.Colors;
import javax.annotation.Nullable;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;

final class GlamouredModelData
{
	/// Constants match RuneLite's NPC lighting before per-NPC Lighting adjustments.
	private static final int NPC_AMBIENT = 64;
	private static final int NPC_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	private final ModelData data;
	private final short[] originalColors;
	@Nullable
	private final short[] originalTextures;
	@Getter
	private final int[][] originalLitColors;
	@Nullable
	private final short[] compositionFind;
	@Nullable
	private final short[] compositionReplace;
	private final int ambient;
	private final int contrast;

	private GlamouredModelData(ModelData data, int[][] originalLitColors,
		@Nullable short[] compositionFind, @Nullable short[] compositionReplace, int ambient, int contrast)
	{
		this.data = data;
		this.originalColors = data.getFaceColors().clone();
		this.originalTextures = data.getFaceTextures() != null ? data.getFaceTextures().clone() : null;
		this.originalLitColors = originalLitColors;
		this.compositionFind = compositionFind;
		this.compositionReplace = compositionReplace;
		this.ambient = ambient;
		this.contrast = contrast;
	}

	@Nullable
	static GlamouredModelData load(Client client, NpcSheet npcSheet, int npcId)
	{
		NPCComposition composition = client.getNpcDefinition(npcId);
		if (composition == null)
		{
			return null;
		}
		int[] modelIds = composition.getModels();
		if (modelIds == null || modelIds.length == 0)
		{
			return null;
		}

		ModelData[] parts = new ModelData[modelIds.length];
		for (int i = 0; i < modelIds.length; i++)
		{
			ModelData part = client.loadModelData(modelIds[i]);
			if (part == null)
			{
				return null;
			}
			parts[i] = part;
		}

		// Don't merge a solo part because it re-derives normals which causes minor lighting differences.
		ModelData merged = parts.length == 1 ? parts[0].shallowCopy() : client.mergeModels(parts);
		if (merged == null)
		{
			return null;
		}

		merged.cloneColors()
			.cloneVertices()
			.cloneTransparencies();
		// cloneTextures throws on a model with no textures.
		if (merged.getFaceTextures() != null)
		{
			merged.cloneTextures();
		}

		short[] find = composition.getColorToReplace();
		short[] replace = composition.getColorToReplaceWith();
		applyCompositionRecolors(find, replace, merged);

		NpcSheet.Lighting lighting = npcSheet.getLighting(npcId);
		final int ambient = NPC_AMBIENT + lighting.getAmbient();
		final int contrast = NPC_CONTRAST + lighting.getContrast();
		Model originalLit = merged.light(ambient, contrast, LIGHT_X, LIGHT_Y, LIGHT_Z);
		if (originalLit == null)
		{
			return null;
		}
		return new GlamouredModelData(merged, getFaceColorsOf(originalLit), find, replace, ambient, contrast);
	}

	void applyGlamour(NpcGlamour glamour)
	{
		System.arraycopy(originalColors, 0, data.getFaceColors(), 0, originalColors.length);
		short[] textures = data.getFaceTextures();
		if (textures != null && originalTextures != null)
		{
			System.arraycopy(originalTextures, 0, textures, 0, originalTextures.length);
		}

		short[] from = new short[countChanged(glamour)];
		short[] to = new short[from.length];
		int next = 0;
		for (ColorReplacement replacement : glamour.getColors())
		{
			if (replacement.hasChanged())
			{
				from[next] = getOverriddenColor(getModelColor(replacement));
				to[next] = replacement.getReplacement();
				next++;
			}
		}
		Colors.breakColorChains(from, to);
		for (int i = 0; i < from.length; i++)
		{
			data.recolor(from[i], to[i]);
		}

		glamour.applyTextures(textures);
	}

	@Nullable
	Model light()
	{
		return data.light(ambient, contrast, LIGHT_X, LIGHT_Y, LIGHT_Z);
	}

	@Nullable
	Model copyPose(Model posed)
	{
		final int count = data.getVerticesCount();
		System.arraycopy(posed.getVerticesX(), 0, data.getVerticesX(), 0, count);
		System.arraycopy(posed.getVerticesY(), 0, data.getVerticesY(), 0, count);
		System.arraycopy(posed.getVerticesZ(), 0, data.getVerticesZ(), 0, count);

		byte[] src = posed.getFaceTransparencies();
		byte[] dst = data.getFaceTransparencies();
		if (src != null && dst != null)
		{
			System.arraycopy(src, 0, dst, 0, Math.min(src.length, dst.length));
		}
		return light();
	}

	int getVerticesCount()
	{
		return data.getVerticesCount();
	}

	@Nullable
	short[] getFaceTextures()
	{
		return data.getFaceTextures();
	}

	@Nullable
	short[] getOriginalTextures()
	{
		return originalTextures;
	}

	static int[][] getFaceColorsOf(Model model)
	{
		return new int[][]{model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3()};
	}

	private static void applyCompositionRecolors(@Nullable short[] find, @Nullable short[] replace, ModelData merged)
	{
		if (find == null || replace == null)
		{
			return;
		}
		for (int i = 0; i < find.length && i < replace.length; i++)
		{
			merged.recolor(find[i], replace[i]);
		}
	}

	private static int countChanged(NpcGlamour glamour)
	{
		int changed = 0;
		for (ColorReplacement replacement : glamour.getColors())
		{
			if (replacement.hasChanged())
			{
				changed++;
			}
		}
		return changed;
	}

	private static short getModelColor(ColorReplacement replacement)
	{
		Short model = replacement.getModel();
		return model != null ? model : replacement.getOriginal();
	}

	private short getOverriddenColor(short color)
	{
		if (compositionFind == null || compositionReplace == null)
		{
			return color;
		}
		for (int i = 0; i < compositionFind.length && i < compositionReplace.length; i++)
		{
			if (compositionFind[i] == color)
			{
				return compositionReplace[i];
			}
		}
		return color;
	}
}

