package io.huze.glamourer.npc;

import java.util.function.BooleanSupplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

@Slf4j
class GlamouredInstance extends RuneLiteObjectController
{
	private final Client client;
	private final NPC npc;
	private final NpcSheet npcSheet;
	private final BooleanSupplier realNpcDrawn;

	@Nullable
	private GlamouredModelData modelData;

	/// The glamour the model was built with
	@Nullable
	private NpcGlamour appliedGlamour;

	/// The last reason a frame failed to draw, logged once per change rather than per frame.
	@Nullable
	private String bailReason;
	private boolean isCenteredOnTile;

	GlamouredInstance(Client client, NPC npc, NpcSheet npcSheet, BooleanSupplier realNpcDrawn)
	{
		this.client = client;
		this.npc = npc;
		this.npcSheet = npcSheet;
		this.realNpcDrawn = realNpcDrawn;
		setRadius(0);
	}

	@Override
	@Nullable
	public Model getModel()
	{
		if (isCenteredOnTile && !realNpcDrawn.getAsBoolean())
		{
			return null;
		}
		if (modelData == null)
		{
			bail("no model");
			return null;
		}

		Model npcModel = npc.getModel();
		if (npcModel == null)
		{
			bail("actor model null");
			return null;
		}
		if (npcModel.getVerticesCount() < modelData.getVerticesCount())
		{
			bail("actor model vertex count mismatch");
			return null;
		}

		return modelData.copyPose(npcModel);
	}

	/// Return true if the director should suppress the actor
	boolean update(NpcGlamour glamour)
	{
		WorldView worldView = npc.getWorldView();
		LocalPoint location = npc.getLocalLocation();
		if (worldView == null || !worldView.contains(location))
		{
			setActive(false);
			return false;
		}

		if (!refreshModel(glamour))
		{
			return false;
		}

		LocalPoint tileCentre = LocalPoint.fromWorld(worldView, npc.getWorldLocation());
		isCenteredOnTile = tileCentre != null
			&& tileCentre.getX() == location.getX() && tileCentre.getY() == location.getY();
		setLocation(location, worldView.getPlane());
		setOrientation(npc.getCurrentOrientation());
		setZ(groundHeight(location, worldView));
		setActive(true);
		return true;
	}

	private boolean refreshModel(NpcGlamour glamour)
	{
		if (modelData != null && glamour.equals(appliedGlamour))
		{
			return true;
		}
		if (modelData == null)
		{
			modelData = GlamouredModelData.load(client, npcSheet, npc.getId());
			if (modelData == null)
			{
				return bail("nothing to build from");
			}
		}

		Model posed = npc.getModel();
		if (posed == null)
		{
			return bail("the actor has no model");
		}
		if (posed.getVerticesCount() < modelData.getVerticesCount())
		{
			return bail("the actor's model has " + posed.getVerticesCount()
				+ " vertices, the rebuild " + modelData.getVerticesCount());
		}

		modelData.applyGlamour(glamour);
		appliedGlamour = glamour;
		bailReason = null;
		return true;
	}

	private boolean bail(String reason)
	{
		if (!reason.equals(bailReason))
		{
			bailReason = reason;
			log.debug("Instance for \"{}\" not drawing: {}", npc.getName(), reason);
		}
		return false;
	}

	void setActive(boolean active)
	{
		if (active)
		{
			client.registerRuneLiteObject(this);
		}
		else
		{
			client.removeRuneLiteObject(this);
		}
	}

	private int groundHeight(LocalPoint location, WorldView worldView)
	{
		int height = Perspective.getFootprintTileHeight(client, location, worldView.getPlane(), npc.getFootprintSize());
		return height - npc.getAnimationHeightOffset();
	}
}

package io.huze.glamourer.npc;

import java.util.Objects;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/// Tracks the owner of the house the player is currently in.
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class HouseTracker
{
	private final Client client;

	/// Standardized name if visiting or null if local player's house / not in a house.
	@Getter
	@Nullable
	private volatile String currentOwnerName;
	/// Standardized name of who might be visited based on the name dialog.
	@Nullable
	private String pendingOwnerName;
	private boolean enteringFromBoard;
	private boolean enteringHouse;

	/// The last house entered from the board, which is what its "Visit-Last" returns to.
	@Nullable
	private String lastBoardOwner;

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
			case LOGGED_IN:
				final String entered = consumePendingOwner();
				if (!client.getTopLevelWorldView().isInstance())
				{
					setOwner(null);
				}
				else if (entered != null && enteringHouse)
				{
					setOwner(entered);
				}
				if (event.getGameState() == GameState.LOGGED_IN)
				{
					enteringHouse = false;
				}
				break;
			case LOGIN_SCREEN:
			case HOPPING:
				pendingOwnerName = null;
				enteringFromBoard = false;
				enteringHouse = false;
				lastBoardOwner = null;
				setOwner(null);
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (event.getIndex() == VarClientID.LAST_NAMEDIALOG)
		{
			String name = client.getVarcStrValue(VarClientID.LAST_NAMEDIALOG);
			pendingOwnerName = name == null || name.isBlank() ? null : Text.standardize(name);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() == InterfaceID.PohBoard.BUTTON)
		{
			enteringFromBoard = true;
		}
		else if ("Visit-Last".equalsIgnoreCase(event.getMenuOption()))
		{
			enteringFromBoard = true;
			pendingOwnerName = lastBoardOwner;
		}
	}

	@Nullable
	private String consumePendingOwner()
	{
		String owner = pendingOwnerName;
		if (owner != null && enteringFromBoard)
		{
			lastBoardOwner = owner;
		}
		pendingOwnerName = null;
		enteringFromBoard = false;
		return owner;
	}

	private void setOwner(@Nullable String owner)
	{
		if (!Objects.equals(owner, currentOwnerName))
		{
			currentOwnerName = owner;
			log.debug("house: {}", owner == null ? "none" : owner + "'s");
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.POH_LOADING)
		{
			enteringHouse = true;
		}
	}
}

package io.huze.glamourer.npc;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
class InstanceDirector
{
	private final Client client;
	private final EventBus eventBus;
	private final RenderCallbackManager renderCallbackManager;
	private final NpcSheet npcSheet;
	private final Map<NPC, GlamouredInstance> instances = new IdentityHashMap<>();
	/// Actors whose draws should be suppressed
	private final Set<Actor> hidden = Collections.newSetFromMap(new IdentityHashMap<>());
	/// Actors whose draws were actually suppressed
	private final Set<Actor> drawnByClient = Collections.newSetFromMap(new IdentityHashMap<>());

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			if (hidden.isEmpty())
			{
				return true;
			}
			Actor actor = getActorBehind(object);
			if (actor instanceof NPC && hidden.contains(actor))
			{
				drawnByClient.add(actor);
				return false;
			}
			return true;
		}
	};

	void startUp()
	{
		eventBus.register(this);
		renderCallbackManager.register(renderCallback);
	}

	void shutDown()
	{
		eventBus.unregister(this);
		renderCallbackManager.unregister(renderCallback);
	}

	void beginFrame()
	{
		hidden.clear();
		drawnByClient.clear();
	}

	void drawInstanceFor(NPC npc, NpcGlamour glamour)
	{
		GlamouredInstance instance = instances.get(npc);
		if (instance == null)
		{
			instance = new GlamouredInstance(client, npc, npcSheet, () -> drawnByClient.contains(npc));
			instances.put(npc, instance);
		}

		if (instance.update(glamour))
		{
			hidden.add(npc);
		}
	}

	void endFrame()
	{
		for (Map.Entry<NPC, GlamouredInstance> entry : instances.entrySet())
		{
			if (!hidden.contains(entry.getKey()))
			{
				entry.getValue().setActive(false);
			}
		}
	}

	void hideAllInstances()
	{
		for (GlamouredInstance instance : instances.values())
		{
			instance.setActive(false);
		}
	}

	void destroyAllInstances()
	{
		hidden.clear();
		drawnByClient.clear();
		hideAllInstances();
		instances.clear();
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		GlamouredInstance instance = instances.remove(event.getNpc());
		if (instance != null)
		{
			instance.setActive(false);
		}
		hidden.remove(event.getNpc());
	}

	@Nullable
	private Actor getActorBehind(TileObject object)
	{
		if (object instanceof GameObject)
		{
			Renderable renderable = ((GameObject) object).getRenderable();
			if (renderable instanceof Actor)
			{
				return (Actor) renderable;
			}
		}
		return null;
	}
}

